window.QUESTIONS={"list":[{"t":"s1","q":{"uk":"Що таке обгін?","ru":"Что такое обгон?"},"a":[{"uk":"Будь-яке випередження іншого транспортного засобу","ru":"Любое опережение другого транспортного средства","w":{"uk":"Не будь-яке: якщо ви обганяєте сусідньою смугою свого напрямку, без виїзду на зустрічну, — це випередження, а не обгін.","ru":"Не любое: если вы опережаете по соседней полосе своего направления, без выезда на встречную, — это опережение, а не обгон."}},{"uk":"Випередження одного або кількох транспортних засобів, пов'язане з виїздом на смугу зустрічного руху","ru":"Опережение одного или нескольких транспортных средств, связанное с выездом на полосу встречного движения"},{"uk":"Рух швидше за сусідню смугу","ru":"Движение быстрее соседней полосы","w":{"uk":"Рух швидше за сусідню смугу — це визначення випередження. Обгін обов'язково пов'язаний з виїздом на зустрічну смугу.","ru":"Движение быстрее соседней полосы — это определение опережения. Обгон обязательно связан с выездом на встречную полосу."}}],"c":1,"e":{"uk":"Обгін — випередження з виїздом на смугу зустрічного руху. Рух швидше за попутний транспорт сусідньою смугою — це випередження.","ru":"Обгон — опережение с выездом на полосу встречного движения. Движение быстрее попутного транспорта по соседней полосе — это опережение."},"ref":["1.10"],"id":"q1bfaf927f"},{"t":"s1","q":{"uk":"Яку видимість Правила вважають недостатньою?","ru":"Какую видимость Правила считают недостаточной?"},"a":[{"uk":"Менше 100 м","ru":"Менее 100 м","w":{"uk":"100 м — це межа для заборони розвороту, а не визначення недостатньої видимості. Недостатня — менше 300 м.","ru":"100 м — это порог для запрета разворота, а не определение недостаточной видимости. Недостаточная — менее 300 м."}},{"uk":"Менше 200 м","ru":"Менее 200 м","w":{"uk":"Такого значення в Правилах немає: недостатньою вважається видимість менше 300 м.","ru":"Такого значения в Правилах нет: недостаточной считается видимость менее 300 м."}},{"uk":"Менше 300 м у сутінках, тумані, дощ, снігопад тощо","ru":"Менее 300 м в сумерках, тумане, дождь, снегопад и т. п."}],"c":2,"e":{"uk":"Недостатня видимість — видимість дороги в напрямку руху менше ніж 300 м у сутінках, в умовах туману, дощу, снігопаду тощо.","ru":"Недостаточная видимость — видимость дороги в направлении движения менее 300 м в сумерках, в условиях тумана, дождя, снегопада и т. п."},"ref":["1.10"],"id":"q1abd56efe"},{"t":"s1","q":{"uk":"Чи є перехрестям місце, де до дороги прилягає виїзд з АЗС?","ru":"Является ли перекрёстком место, где к дороге примыкает выезд с АЗС?"},"a":[{"uk":"Так","ru":"Да","w":{"uk":"Правила прямо кажуть: місце прилягання виїзду з прилеглої території (АЗС, двір, стоянка) перехрестям не вважається.","ru":"Правила прямо говорят: место примыкания выезда с прилегающей территории (АЗС, двор, стоянка) перекрёстком не считается."}},{"uk":"Ні, це виїзд з прилеглої території","ru":"Нет, это выезд с прилегающей территории"}],"c":1,"e":{"uk":"Не вважається перехрестям місце прилягання до дороги виїзду з прилеглої території (двір, стоянка, АЗС). Той, хто виїжджає, пропускає всіх на дорозі.","ru":"Не считается перекрёстком место примыкания к дороге выезда с прилегающей территории (двор, стоянка, АЗС). Выезжающий пропускает всех на дороге."},"ref":["1.10","10.2"],"id":"q4f49bbc8d"},{"t":"s1","q":{"uk":"Яка з доріг є головною на перехресті дороги з асфальтовим покриттям і ґрунтової, якщо знаків немає?","ru":"Какая из дорог является главной на перекрёстке дороги с асфальтовым покрытием и грунтовой, если знаков нет?"},"a":[{"uk":"Дорога з покриттям","ru":"Дорога с покрытием"},{"uk":"Ґрунтова, бо вона праворуч","ru":"Грунтовая, так как она справа","w":{"uk":"«Перешкода праворуч» діє лише на рівнозначних дорогах. Дорога з покриттям завжди головна відносно ґрунтової.","ru":"«Помеха справа» действует только на равнозначных дорогах. Дорога с покрытием всегда главная по отношению к грунтовой."}},{"uk":"Вони рівнозначні","ru":"Они равнозначны","w":{"uk":"Ні: дорога з покриттям є головною відносно ґрунтової навіть без знаків.","ru":"Нет: дорога с покрытием является главной по отношению к грунтовой даже без знаков."}}],"c":0,"e":{"uk":"Головна дорога — дорога з покриттям відносно ґрунтової або позначена знаками {s:1.22}, {s:1.23.1}–{s:1.23.4}, {s:2.3}. Ділянка покриття на другорядній дорозі перед самим перехрестям не робить її рівнозначною.","ru":"Главная дорога — дорога с покрытием по отношению к грунтовой или обозначенная знаками {s:1.22}, {s:1.23.1}–{s:1.23.4}, {s:2.3}. Участок покрытия на второстепенной дороге прямо перед перекрёстком не делает её равнозначной."},"ref":["1.10"],"id":"qee89f9c49"},{"t":"s1","q":{"uk":"Скільки транспортних засобів мінімально утворюють колону?","ru":"Сколько транспортных средств минимально образуют колонну?"},"a":[{"uk":"Два","ru":"Два","w":{"uk":"Два автомобілі ще не колона: за Правилами потрібно щонайменше три транспортні засоби.","ru":"Два автомобиля ещё не колонна: по Правилам нужно не менее трёх транспортных средств."}},{"uk":"Три","ru":"Три"},{"uk":"П'ять","ru":"Пять","w":{"uk":"Забагато: колона починається вже з трьох транспортних засобів. П'ять — це розмір групи в колоні без супроводу.","ru":"Слишком много: колонна начинается уже с трёх транспортных средств. Пять — это размер группы в колонне без сопровождения."}}],"c":1,"e":{"uk":"Колона транспортних засобів — організована група з трьох і більше транспортних засобів, що рухаються разом в одному напрямку один за одним з увімкненим ближнім світлом.","ru":"Колонна транспортных средств — организованная группа из трёх и более транспортных средств, движущихся вместе в одном направлении друг за другом с включённым ближним светом."},"ref":["1.10"],"id":"q88a767a90"},{"t":"s1","q":{"uk":"Людина веде велосипед по узбіччю. Хто вона з погляду Правил?","ru":"Человек ведёт велосипед по обочине. Кто он с точки зрения Правил?"},"a":[{"uk":"Велосипедист","ru":"Велосипедист","w":{"uk":"Велосипедист — той, хто керує велосипедом. Хто веде велосипед поруч, прирівнюється до пішохода.","ru":"Велосипедист — тот, кто управляет велосипедом. Кто ведёт велосипед рядом, приравнивается к пешеходу."}},{"uk":"Пішохід","ru":"Пешеход"},{"uk":"Водій","ru":"Водитель","w":{"uk":"Водій — особа, яка керує транспортним засобом. Людина, що йде пішки й веде велосипед, — пішохід.","ru":"Водитель — лицо, управляющее транспортным средством. Человек, идущий пешком и ведущий велосипед, — пешеход."}}],"c":1,"e":{"uk":"До пішоходів прирівнюються особи, які ведуть велосипед, мопед, мотоцикл, везуть санки, візок, дитячу коляску чи рухаються в кріслі колісному без двигуна.","ru":"К пешеходам приравниваются лица, ведущие велосипед, мопед, мотоцикл, везущие санки, тележку, детскую коляску или передвигающиеся в кресле-коляске без двигателя."},"ref":["1.10"],"id":"q7ddf167d8"},{"t":"s1","q":{"uk":"Яка мінімальна ширина смуги руху за Правилами?","ru":"Какая минимальная ширина полосы движения по Правилам?"},"a":[{"uk":"2,5 м","ru":"2,5 м","w":{"uk":"Замало: за визначенням смуга руху має ширину щонайменше 2,75 м.","ru":"Слишком мало: по определению полоса движения имеет ширину не менее 2,75 м."}},{"uk":"2,75 м","ru":"2,75 м"},{"uk":"3,5 м","ru":"3,5 м","w":{"uk":"3,5 м — типова ширина смуги на трасі, але мінімум за Правилами — 2,75 м.","ru":"3,5 м — типичная ширина полосы на трассе, но минимум по Правилам — 2,75 м."}}],"c":1,"e":{"uk":"Смуга руху — поздовжня смуга на проїзній частині завширшки щонайменше 2,75 м.","ru":"Полоса движения — продольная полоса на проезжей части шириной не менее 2,75 м."},"ref":["1.10"],"id":"qa1685d6bf"},{"t":"s1","q":{"uk":"Пішохідний перехід, на якому світлофор працює в режимі миготливого жовтого, вважається...","ru":"Пешеходный переход, на котором светофор работает в режиме мигающего жёлтого, считается..."},"a":[{"uk":"регульованим","ru":"регулируемым","w":{"uk":"Миготливий жовтий не регулює рух. Перехід із таким світлофором Правила відносять до нерегульованих.","ru":"Мигающий жёлтый не регулирует движение. Переход с таким светофором Правила относят к нерегулируемым."}},{"uk":"нерегульованим","ru":"нерегулируемым"}],"c":1,"e":{"uk":"Нерегульований пішохідний перехід — той, де немає регулювальника, а світлофори відсутні, вимкнені чи миготять жовтим.","ru":"Нерегулируемый пешеходный переход — тот, где нет регулировщика, а светофоры отсутствуют, выключены или мигают жёлтым."},"ref":["1.10"],"id":"q0c3c0d13b"},{"t":"s1","q":{"uk":"Що Правила вважають темною порою доби?","ru":"Что Правила считают тёмным временем суток?"},"a":[{"uk":"Частину доби від заходу до сходу сонця","ru":"Часть суток от захода до восхода солнца"},{"uk":"Час з 22:00 до 6:00","ru":"Время с 22:00 до 6:00","w":{"uk":"Правила не прив'язують темну пору до годинника: вона триває від заходу до сходу сонця, а це залежить від пори року.","ru":"Правила не привязывают тёмное время к часам: оно длится от захода до восхода солнца, а это зависит от времени года."}},{"uk":"Час, коли увімкнено вуличне освітлення","ru":"Время, когда включено уличное освещение","w":{"uk":"Освітлення тут ні до чого: темна пора — від заходу до сходу сонця, навіть на освітленій вулиці.","ru":"Освещение здесь ни при чём: тёмное время — от захода до восхода солнца, даже на освещённой улице."}}],"c":0,"e":{"uk":"Темна пора доби — частина доби від заходу до сходу сонця.","ru":"Тёмное время суток — часть суток от захода до восхода солнца."},"ref":["1.10"],"id":"q6a3a32f57"},{"t":"s3","q":{"uk":"Наближається автомобіль з увімкненим синім маячком і сиреною. Що зобов'язаний зробити водій, який може йому заважати?","ru":"Приближается автомобиль с включённым синим маячком и сиреной. Что обязан сделать водитель, который может ему мешать?"},"a":[{"uk":"Продовжувати рух, не змінюючи смуги","ru":"Продолжать движение, не меняя полосы","w":{"uk":"Якщо ви можете заважати машині із синім маячком, ви зобов'язані поступитися, а не їхати як раніше.","ru":"Если вы можете мешать машине с синим маячком, вы обязаны уступить, а не ехать как прежде."}},{"uk":"Дати дорогу й забезпечити безперешкодний проїзд","ru":"Уступить дорогу и обеспечить беспрепятственный проезд"},{"uk":"Зупинитися посеред смуги","ru":"Остановиться посреди полосы","w":{"uk":"Зупинка посеред смуги якраз перекриє дорогу спецтранспорту. Треба звільнити шлях, наприклад притиснутися праворуч.","ru":"Остановка посреди полосы как раз перекроет дорогу спецтранспорту. Нужно освободить путь, например прижаться вправо."}}],"c":1,"e":{"uk":"Водії, які можуть заважати транспортному засобу із синім маячком та (або) спеціальним звуковим сигналом, зобов'язані дати йому дорогу. Якщо ввімкнено синій і червоний або лише червоний маячок — зупинитися біля правого краю.","ru":"Водители, которые могут мешать транспортному средству с синим маячком и (или) специальным звуковым сигналом, обязаны уступить ему дорогу. Если включены синий и красный или только красный маячок — остановиться у правого края."},"ref":["3.2"],"id":"qffe63bc61"},{"t":"s3","q":{"uk":"Позаду наближається автомобіль з увімкненими синім і червоним маячками. Як діяти?","ru":"Сзади приближается автомобиль с включёнными синим и красным маячками. Как поступить?"},"a":[{"uk":"Зупинитися біля правого краю проїзної частини (на правому узбіччі)","ru":"Остановиться у правого края проезжей части (на правой обочине)"},{"uk":"Прискоритися, щоб не заважати","ru":"Ускориться, чтобы не мешать","w":{"uk":"Прискорюватися не можна: при синьому і червоному маячках Правила вимагають зупинитися біля правого краю.","ru":"Ускоряться нельзя: при синем и красном маячках Правила требуют остановиться у правого края."}},{"uk":"Перестроїтися ліворуч","ru":"Перестроиться налево","w":{"uk":"Перестроюватися ліворуч не можна — це шлях спецтранспорту. Треба зупинитися праворуч.","ru":"Перестраиваться налево нельзя — это путь спецтранспорта. Нужно остановиться справа."}}],"c":0,"e":{"uk":"Якщо ввімкнено синій і червоний або лише червоний маячок, водії зобов'язані зупинитися біля правого краю проїзної частини. На дорозі з розділювальною смугою — водії попутного напрямку.","ru":"Если включены синий и красный или только красный маячок, водители обязаны остановиться у правого края проезжей части. На дороге с разделительной полосой — водители попутного направления."},"ref":["3.2"],"id":"q2ab91d744"},{"t":"s3","q":{"uk":"Чи дає оранжевий проблисковий маячок перевагу в русі?","ru":"Даёт ли оранжевый проблесковый маячок преимущество в движении?"},"a":[{"uk":"Так, як і синій","ru":"Да, как и синий","w":{"uk":"Ні, перевагу дає лише синій (червоний) маячок. Оранжевий лише попереджає про небезпеку.","ru":"Нет, преимущество даёт только синий (красный) маячок. Оранжевый только предупреждает об опасности."}},{"uk":"Ні, він лише привертає увагу і попереджає про небезпеку","ru":"Нет, он только привлекает внимание и предупреждает об опасности"}],"c":1,"e":{"uk":"Оранжевий маячок (дорожна техніка, великогабаритний транспорт, автобус «Діти» тощо) не дає переваги, а служить для привернення уваги та попередження про небезпеку.","ru":"Оранжевый маячок (дорожная техника, крупногабаритный транспорт, автобус «Дети» и т. п.) не даёт преимущества, а служит для привлечения внимания и предупреждения об опасности."},"ref":["3.6"],"id":"q102449b9c"},{"t":"s3","q":{"uk":"Попереду на узбіччі стоїть поліцейський автомобіль з увімкненим синім маячком. До якої швидкості треба знизити швидкість?","ru":"Впереди на обочине стоит полицейский автомобиль с включённым синим маячком. До какой скорости нужно снизить скорость?"},"a":[{"uk":"20 км/год","ru":"20 км/ч","w":{"uk":"Правила вимагають знизити швидкість до 40 км/год, а не до 20 км/год.","ru":"Правила требуют снизить скорость до 40 км/ч, а не до 20 км/ч."}},{"uk":"40 км/год","ru":"40 км/ч"},{"uk":"60 км/год","ru":"60 км/ч","w":{"uk":"60 км/год — забагато: біля машини із синім маячком, що стоїть, — не більше 40 км/год.","ru":"60 км/ч — слишком много: возле стоящей машины с синим маячком — не более 40 км/ч."}}],"c":1,"e":{"uk":"Наближаючись до нерухомого транспортного засобу з увімкненим синім маячком, водій знижує швидкість до 40 км/год, а на сигнал регулювальника — зупиняється.","ru":"Приближаясь к неподвижному транспортному средству с включённым синим маячком, водитель снижает скорость до 40 км/ч, а по сигналу регулировщика — останавливается."},"ref":["3.5"],"id":"qeb6fcad38"},{"t":"s3","q":{"uk":"Чи можна обганяти колону, яку супроводжує автомобіль із синім і червоним маячками?","ru":"Можно ли обгонять колонну, которую сопровождает автомобиль с синим и красным маячками?"},"a":[{"uk":"Так, якщо зустрічна смуга вільна","ru":"Да, если встречная полоса свободна","w":{"uk":"Вільна зустрічна смуга нічого не змінює: обгін колони зі спецсупроводом заборонений завжди.","ru":"Свободная встречная полоса ничего не меняет: обгон колонны со спецсопровождением запрещён всегда."}},{"uk":"Ні, обгін і випередження такої колони заборонені, як і займати в ній місце","ru":"Нет, обгон и опережение такой колонны запрещены, как и занимать в ней место"}],"c":1,"e":{"uk":"Заборонено обганяти й випереджати транспортні засоби з увімкненими спецмаячками і супроводжувану ними колону, рухатися поруч зі швидкістю колони або займати місце в ній.","ru":"Запрещено обгонять и опережать транспортные средства с включёнными спецмаячками и сопровождаемую ими колонну, двигаться рядом со скоростью колонны или занимать в ней место."},"ref":["3.4"],"id":"q6f14dc3ee"},{"t":"s3","q":{"uk":"Ліворуч наближається автомобіль швидкої допомоги з увімкненим синім маячком і сиреною. Хто проїде перехрестя першим?","ru":"Слева приближается автомобиль скорой помощи с включённым синим маячком и сиреной. Кто проедет перекрёсток первым?"},"a":[{"uk":"Автомобіль 1, бо швидка ліворуч","ru":"Автомобиль 1, так как скорая слева","w":{"uk":"Правило «перешкода праворуч» не діє щодо транспорту із синім маячком і сиреною: йому поступаються всі.","ru":"Правило «помеха справа» не действует в отношении транспорта с синим маячком и сиреной: ему уступают все."}},{"uk":"Автомобіль швидкої допомоги","ru":"Автомобиль скорой помощи"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"straight","label":"1","color":"red","me":true},{"arm":"W","move":"straight","label":"2","type":"ambulance"}]}},"c":1,"e":{"uk":"Транспортному засобу з увімкненим синім маячком і спеціальним звуковим сигналом треба дати дорогу, незалежно від правил проїзду перехресть.","ru":"Транспортному средству с включённым синим маячком и специальным звуковым сигналом нужно уступить дорогу независимо от правил проезда перекрёстков."},"ref":["3.2"],"id":"q70bee0ccc"},{"t":"s4","q":{"uk":"Як мають іти пішоходи узбіччям поза населеним пунктом?","ru":"Как должны идти пешеходы по обочине вне населённого пункта?"},"a":[{"uk":"Назустріч руху транспортних засобів","ru":"Навстречу движению транспортных средств"},{"uk":"У напрямку руху транспортних засобів","ru":"В направлении движения транспортных средств","w":{"uk":"За містом пішоходи йдуть назустріч транспорту, щоб бачити машини, що наближаються. У напрямку руху йдуть лише ті, хто веде велосипед чи мотоцикл.","ru":"За городом пешеходы идут навстречу транспорту, чтобы видеть приближающиеся машины. В направлении движения идут только те, кто ведёт велосипед или мотоцикл."}},{"uk":"Будь-як","ru":"Как угодно","w":{"uk":"Правила чітко визначають напрямок: поза населеним пунктом — назустріч руху транспорту.","ru":"Правила чётко определяют направление: вне населённого пункта — навстречу движению транспорта."}}],"c":0,"e":{"uk":"Поза населеними пунктами пішоходи йдуть узбіччям чи краєм проїзної частини назустріч руху транспорту. Ті, хто веде велосипед чи мотоцикл або рухається в кріслі колісному без двигуна, — у напрямку руху.","ru":"Вне населённых пунктов пешеходы идут по обочине или краю проезжей части навстречу движению транспорта. Те, кто ведёт велосипед или мотоцикл или передвигается в кресле-коляске без двигателя, — в направлении движения."},"ref":["4.3"],"id":"q803d925d1"},{"t":"s4","q":{"uk":"Де пішохід може перейти дорогу, якщо поблизу немає переходу і перехрестя?","ru":"Где пешеход может перейти дорогу, если поблизости нет перехода и перекрёстка?"},"a":[{"uk":"Будь-де і під будь-яким кутом","ru":"Где угодно и под любым углом","w":{"uk":"Переходити можна лише під прямим кутом і там, де дорогу добре видно, а не будь-де.","ru":"Переходить можно только под прямым углом и там, где дорогу хорошо видно, а не где угодно."}},{"uk":"Під прямим кутом там, де дорогу добре видно в обидва боки, якщо в ній не більше трьох смуг для обох напрямків","ru":"Под прямым углом там, где дорогу хорошо видно в обе стороны, если в ней не более трёх полос для обоих направлений"},{"uk":"Лише через розділювальну смугу","ru":"Только через разделительную полосу","w":{"uk":"Навпаки: якщо є розділювальна смуга, переходити поза переходом заборонено.","ru":"Наоборот: если есть разделительная полоса, переходить вне перехода запрещено."}}],"c":1,"e":{"uk":"Поза переходом можна переходити дорогу з не більше ніж трьома смугами (для обох напрямків) під прямим кутом у місці з хорошою оглядовістю, переконавшись у безпеці. Якщо є розділювальна смуга, чотири й більше смуг або огородження — заборонено.","ru":"Вне перехода можно переходить дорогу не более чем с тремя полосами (для обоих направлений) под прямым углом в месте с хорошей обзорностью, убедившись в безопасности. Если есть разделительная полоса, четыре и более полос или ограждение — запрещено."},"ref":["4.8","4.14"],"id":"q86a9952d2"},{"t":"s4","q":{"uk":"Що зобов'язані мати пішоходи, які йдуть узбіччям у темну пору доби?","ru":"Что обязаны иметь пешеходы, идущие по обочине в тёмное время суток?"},"a":[{"uk":"Світлоповертальні елементи (стрічку, жилет тощо)","ru":"Световозвращающие элементы (ленту, жилет и т. п.)"},{"uk":"Ліхтарик","ru":"Фонарик","w":{"uk":"Ліхтарик не вимагається. Обов'язкові світлоповертальні елементи на одязі.","ru":"Фонарик не требуется. Обязательны световозвращающие элементы на одежде."}},{"uk":"Нічого","ru":"Ничего","w":{"uk":"У темряві пішохід на узбіччі мусить мати світлоповертальні елементи, інакше водій його не помітить.","ru":"В темноте пешеход на обочине обязан иметь световозвращающие элементы, иначе водитель его не заметит."}}],"c":0,"e":{"uk":"У темну пору доби та за недостатньої видимості пішоходи на проїзній частині чи узбіччі мають використовувати світлоповертальні елементи або одяг з ними.","ru":"В тёмное время суток и при недостаточной видимости пешеходы на проезжей части или обочине должны использовать световозвращающие элементы или одежду с ними."},"ref":["4.4"],"id":"q4524ca53b"},{"t":"s4","q":{"uk":"Пішохід почав переходити на зелений, але не встиг: увімкнувся червоний. Як йому діяти?","ru":"Пешеход начал переходить на зелёный, но не успел: включился красный. Как ему поступить?"},"a":[{"uk":"Бігти назад","ru":"Бежать назад","w":{"uk":"Повертатися бігом небезпечно: машини вже рушають. Треба зупинитися на острівці чи осьовій лінії.","ru":"Возвращаться бегом опасно: машины уже трогаются. Нужно остановиться на островке или осевой линии."}},{"uk":"Зупинитися на острівці безпеки або лінії, що розділяє потоки, і чекати дозвільного сигналу","ru":"Остановиться на островке безопасности или линии, разделяющей потоки, и ждать разрешающего сигнала"},{"uk":"Продовжити перехід, бо він має перевагу","ru":"Продолжить переход, так как у него преимущество","w":{"uk":"На червоний пішохід перевагу втрачає. Він чекає на острівці безпеки, доки знову ввімкнеться зелений.","ru":"На красный пешеход теряет преимущество. Он ждёт на островке безопасности, пока снова включится зелёный."}}],"c":1,"e":{"uk":"Пішоходи, які не встигли закінчити перехід, чекають на острівці безпеки чи лінії, що розділяє протилежні потоки (а якщо їх немає — посередині), і продовжують рух на дозвільний сигнал. Водії, проїжджаючи повз них, тримають безпечний інтервал.","ru":"Пешеходы, не успевшие закончить переход, ждут на островке безопасности или линии, разделяющей встречные потоки (а если их нет — посередине), и продолжают движение на разрешающий сигнал. Водители, проезжая мимо них, соблюдают безопасный интервал."},"ref":["4.9","18.3"],"id":"q9f99be67e"},{"t":"s5","q":{"uk":"Звідки пасажир може виходити з автомобіля, якщо немає посадкового майданчика, тротуару чи узбіччя?","ru":"Откуда пассажир может выходить из автомобиля, если нет посадочной площадки, тротуара или обочины?"},"a":[{"uk":"З крайньої смуги проїзної частини, але не з боку суміжної смуги руху, якщо це безпечно","ru":"С крайней полосы проезжей части, но не со стороны смежной полосы движения, если это безопасно"},{"uk":"З будь-якого боку","ru":"С любой стороны","w":{"uk":"Не з будь-якого: виходити з боку суміжної смуги руху заборонено — там їдуть машини.","ru":"Не с любой: выходить со стороны смежной полосы движения запрещено — там едут машины."}},{"uk":"Виходити заборонено","ru":"Выходить запрещено","w":{"uk":"Виходити можна: якщо немає майданчика, тротуару чи узбіччя, дозволено з крайньої смуги за умови безпеки.","ru":"Выходить можно: если нет площадки, тротуара или обочины, разрешено с крайней полосы при условии безопасности."}}],"c":0,"e":{"uk":"Посадку й висадку здійснюють після зупинки з посадкового майданчика, тротуару чи узбіччя, а якщо це неможливо — з крайньої смуги (але не з боку суміжної смуги руху), якщо це безпечно.","ru":"Посадку и высадку осуществляют после остановки с посадочной площадки, тротуара или обочины, а если это невозможно — с крайней полосы (но не со стороны смежной полосы движения), если это безопасно."},"ref":["5.1"],"id":"qe67eb2ae2"},{"t":"s5","q":{"uk":"Що заборонено пасажирам під час руху?","ru":"Что запрещено пассажирам во время движения?"},"a":[{"uk":"Розмовляти з водієм","ru":"Разговаривать с водителем","w":{"uk":"Розмовляти не заборонено. Заборонено відволікати водія від керування і заважати йому.","ru":"Разговаривать не запрещено. Запрещено отвлекать водителя от управления и мешать ему."}},{"uk":"Відволікати водія, відчиняти двері до зупинки, стояти в кузові вантажівки","ru":"Отвлекать водителя, открывать двери до остановки, стоять в кузове грузовика"},{"uk":"Пристібатися ременем на задньому сидінні","ru":"Пристёгиваться ремнём на заднем сиденье","w":{"uk":"Навпаки, пасажири зобов'язані бути пристебнутими, у тому числі на задньому сидінні.","ru":"Наоборот, пассажиры обязаны быть пристёгнутыми, в том числе на заднем сиденье."}}],"c":1,"e":{"uk":"Пасажирам заборонено відволікати водія, відчиняти двері, не переконавшись у зупинці біля тротуару чи узбіччя, заважати зачиненню дверей, їздити на підніжках, стояти в кузові вантажного автомобіля чи сидіти на бортах.","ru":"Пассажирам запрещено отвлекать водителя, открывать двери, не убедившись в остановке у тротуара или обочины, мешать закрыванию дверей, ездить на подножках, стоять в кузове грузового автомобиля или сидеть на бортах."},"ref":["5.3"],"id":"qfee0faa57"},{"t":"s6","q":{"uk":"З якого віку дозволено їздити дорогою на велосипеді?","ru":"С какого возраста разрешено ездить по дороге на велосипеде?"},"a":[{"uk":"З 12 років","ru":"С 12 лет","w":{"uk":"12 років — замало: їздити дорогою на велосипеді можна з 14 років.","ru":"12 лет — мало: ездить по дороге на велосипеде можно с 14 лет."}},{"uk":"З 14 років","ru":"С 14 лет"},{"uk":"З 16 років","ru":"С 16 лет","w":{"uk":"16 років — вік для мотоциклів (категорії A1, A). Велосипедом дорогою можна з 14.","ru":"16 лет — возраст для мотоциклов (категории A1, A). На велосипеде по дороге можно с 14."}}],"c":1,"e":{"uk":"Рухатися дорогою на велосипеді дозволено особам, які досягли 14 років.","ru":"Двигаться по дороге на велосипеде разрешено лицам, достигшим 14 лет."},"ref":["6.1"],"id":"q723c923e6"},{"t":"s6","q":{"uk":"Велодоріжка перетинає дорогу поза перехрестям. Хто має перевагу?","ru":"Велодорожка пересекает дорогу вне перекрёстка. У кого преимущество?"},"a":[{"uk":"Велосипедисти","ru":"Велосипедисты","w":{"uk":"Поза перехрестям велосипедисти, що перетинають дорогу з велодоріжки, поступаються транспорту на дорозі.","ru":"Вне перекрёстка велосипедисты, пересекающие дорогу с велодорожки, уступают транспорту на дороге."}},{"uk":"Транспортні засоби, що рухаються дорогою","ru":"Транспортные средства, движущиеся по дороге"}],"img":{"sign":"1.34"},"c":1,"e":{"uk":"Якщо велосипедна доріжка перетинає дорогу поза перехрестям, велосипедисти дають дорогу транспортним засобам на дорозі. Водієві ж варто бути особливо уважним: знак {s:1.34} попереджає про можливу появу велосипедистів.","ru":"Если велосипедная дорожка пересекает дорогу вне перекрёстка, велосипедисты уступают дорогу транспортным средствам на дороге. Водителю же стоит быть особенно внимательным: знак {s:1.34} предупреждает о возможном появлении велосипедистов."},"ref":["6.5"],"id":"q07e4425eb"},{"t":"s6","q":{"uk":"Якого кольору мають бути світлоповертачі велосипеда позаду?","ru":"Какого цвета должны быть световозвращатели велосипеда сзади?"},"a":[{"uk":"Червоного","ru":"Красного"},{"uk":"Білого","ru":"Белого","w":{"uk":"Білий світлоповертач ставлять спереду, а не позаду.","ru":"Белый световозвращатель ставят спереди, а не сзади."}},{"uk":"Оранжевого","ru":"Оранжевого","w":{"uk":"Оранжеві світлоповертачі — по боках велосипеда. Позаду — червоний.","ru":"Оранжевые световозвращатели — по бокам велосипеда. Сзади — красный."}}],"c":0,"e":{"uk":"Велосипед обладнують звуковим сигналом і світлоповертачами: спереду — білого, по боках — оранжевого, позаду — червоного кольору. Уночі має горіти ліхтар (фара).","ru":"Велосипед оборудуют звуковым сигналом и световозвращателями: спереди — белого, по бокам — оранжевого, сзади — красного цвета. Ночью должен гореть фонарь (фара)."},"ref":["6.2"],"id":"qea9c435c5"},{"t":"s7","q":{"uk":"Коли дозволено переганяти стадо тварин дорогою?","ru":"Когда разрешено перегонять стадо животных по дороге?"},"a":[{"uk":"Лише у світлу пору доби","ru":"Только в светлое время суток"},{"uk":"У будь-який час із ліхтарями","ru":"В любое время с фонарями","w":{"uk":"Ліхтарі не допомагають: переганяти тварин у темну пору заборонено взагалі.","ru":"Фонари не помогают: перегонять животных в тёмное время запрещено вообще."}},{"uk":"Лише вночі, коли мало транспорту","ru":"Только ночью, когда мало транспорта","w":{"uk":"Уночі переганяти тварин якраз заборонено — лише у світлу пору доби.","ru":"Ночью перегонять животных как раз запрещено — только в светлое время суток."}}],"c":0,"e":{"uk":"Переганяти стадо дорогою дозволено лише у світлу пору доби, з достатньою кількістю погоничів, якомога ближче до правого краю.","ru":"Перегонять стадо по дороге разрешено только в светлое время суток, с достаточным количеством погонщиков, как можно ближе к правому краю."},"ref":["7.6"],"id":"q8d422d51f"},{"t":"s2","q":{"uk":"Які документи водій легкового автомобіля зобов'язаний мати при собі?","ru":"Какие документы водитель легкового автомобиля обязан иметь при себе?"},"a":[{"uk":"Лише посвідчення водія","ru":"Только водительское удостоверение","w":{"uk":"Одного посвідчення мало: потрібні також реєстраційний документ на автомобіль і поліс ОСЦПВ.","ru":"Одного удостоверения мало: нужны также регистрационный документ на автомобиль и полис ОСАГО."}},{"uk":"Посвідчення водія відповідної категорії, реєстраційний документ на автомобіль і чинний поліс ОСЦПВ (можна електронний)","ru":"Удостоверение водителя соответствующей категории, регистрационный документ на автомобиль и действующий полис ОСАГО (можно электронный)"},{"uk":"Посвідчення водія, паспорт і медичну довідку","ru":"Удостоверение водителя, паспорт и медицинскую справку","w":{"uk":"Паспорт і медична довідка не входять до переліку п. 2.1. Потрібні техпаспорт і поліс.","ru":"Паспорт и медсправка не входят в перечень п. 2.1. Нужны техпаспорт и полис."}}],"c":1,"e":{"uk":"Водій має мати посвідчення на право керування відповідної категорії, реєстраційний документ на транспортний засіб і чинний поліс обов'язкового страхування цивільно-правової відповідальності (на паперовому або електронному носії).","ru":"Водитель должен иметь удостоверение на право управления соответствующей категории, регистрационный документ на транспортное средство и действующий полис обязательного страхования гражданско-правовой ответственности (на бумажном или электронном носителе)."},"ref":["2.1"],"id":"q28326420c"},{"t":"s2","q":{"uk":"Чи можна під час руху розмовляти по телефону, тримаючи його в руці?","ru":"Можно ли во время движения разговаривать по телефону, держа его в руке?"},"a":[{"uk":"Так, якщо розмова коротка","ru":"Да, если разговор короткий","w":{"uk":"Тривалість розмови не має значення: будь-яка розмова з телефоном у руці під час руху заборонена.","ru":"Длительность разговора не важна: любой разговор с телефоном в руке во время движения запрещён."}},{"uk":"Ні. Дозволено лише через гарнітуру або гучний зв'язок без утримання в руці","ru":"Нет. Разрешено только через гарнитуру или громкую связь, не держа в руке"},{"uk":"Так, у населеному пункті на швидкості до 20 км/год","ru":"Да, в населённом пункте на скорости до 20 км/ч","w":{"uk":"Швидкість і місце не мають значення: тримати телефон у руці під час руху заборонено завжди.","ru":"Скорость и место не важны: держать телефон в руке во время движения запрещено всегда."}}],"c":1,"e":{"uk":"Водієві заборонено під час руху користуватися засобами зв'язку, тримаючи їх у руці (виняток — водії оперативних транспортних засобів під час невідкладного завдання).","ru":"Водителю запрещено во время движения пользоваться средствами связи, держа их в руке (исключение — водители оперативных транспортных средств во время неотложного задания)."},"ref":["2.9"],"id":"q5b1c437dd"},{"t":"s2","q":{"uk":"Кому можна передати керування своїм автомобілем?","ru":"Кому можно передать управление своим автомобилем?"},"a":[{"uk":"Будь-якому повнолітньому пасажиру","ru":"Любому совершеннолетнему пассажиру","w":{"uk":"Вік пасажира не важливий: керувати може лише той, хто має при собі посвідчення відповідної категорії.","ru":"Возраст пассажира не важен: управлять может только тот, у кого при себе удостоверение соответствующей категории."}},{"uk":"Особі, яка має при собі посвідчення водія відповідної категорії і не перебуває в стані сп'яніння чи хворобливому стані","ru":"Лицу, имеющему при себе удостоверение водителя соответствующей категории и не находящемуся в состоянии опьянения или болезненном состоянии"},{"uk":"Будь-кому, якщо власник сидить поруч","ru":"Кому угодно, если владелец сидит рядом","w":{"uk":"Присутність власника не замінює посвідчення. Без посвідчення керувати можна лише під час навчальної їзди з інструктором.","ru":"Присутствие владельца не заменяет удостоверения. Без удостоверения управлять можно только во время учебной езды с инструктором."}}],"c":1,"e":{"uk":"Керування можна передати особі, що має при собі посвідчення на право керування відповідної категорії. Заборонено передавати керування особам у стані сп'яніння, під дією ліків, у хворобливому стані або без посвідчення (крім навчальної їзди).","ru":"Управление можно передать лицу, имеющему при себе удостоверение на право управления соответствующей категории. Запрещено передавать управление лицам в состоянии опьянения, под действием лекарств, в болезненном состоянии или без удостоверения (кроме учебной езды)."},"ref":["2.2","2.9"],"id":"q6ac4c0d76"},{"t":"s2","q":{"uk":"Чи можна в населеному пункті не пристібатися ременем безпеки?","ru":"Можно ли в населённом пункте не пристёгиваться ремнём безопасности?"},"a":[{"uk":"Так, усім водіям","ru":"Да, всем водителям","w":{"uk":"Ні, ремінь обов'язковий для всіх, у тому числі в місті. Винятки — лише особи з інвалідністю та оперативні служби.","ru":"Нет, ремень обязателен для всех, в том числе в городе. Исключения — только лица с инвалидностью и оперативные службы."}},{"uk":"Лише особам з інвалідністю, яким фізіологічні особливості не дозволяють користуватися ременем, та водіям і пасажирам оперативних і спеціальних транспортних засобів","ru":"Только лицам с инвалидностью, которым физиологические особенности не позволяют пользоваться ремнём, и водителям и пассажирам оперативных и специальных транспортных средств"},{"uk":"Так, якщо швидкість не перевищує 50 км/год","ru":"Да, если скорость не превышает 50 км/ч","w":{"uk":"Швидкість тут ні до чого: пристібатися треба за будь-якої швидкості.","ru":"Скорость здесь ни при чём: пристёгиваться нужно при любой скорости."}}],"c":1,"e":{"uk":"Водій зобов'язаний користуватися ременем і не перевозити непристебнутих пасажирів. Виняток у населених пунктах — особи з інвалідністю, яким фізіологічні особливості не дозволяють пристебнутися, та водії і пасажири оперативних і спеціальних транспортних засобів.","ru":"Водитель обязан пользоваться ремнём и не перевозить непристёгнутых пассажиров. Исключение в населённых пунктах — лица с инвалидностью, которым физиологические особенности не позволяют пристегнуться, и водители и пассажиры оперативных и специальных транспортных средств."},"ref":["2.3"],"id":"qf63d75ae9"},{"t":"s2","q":{"uk":"Ви стали учасником ДТП, є постраждалі. Що зробити насамперед?","ru":"Вы стали участником ДТП, есть пострадавшие. Что сделать в первую очередь?"},"a":[{"uk":"Зупинитися, увімкнути аварійку, виставити знак аварійної зупинки, надати домедичну допомогу і викликати швидку","ru":"Остановиться, включить аварийку, выставить знак аварийной остановки, оказать домедицинскую помощь и вызвать скорую"},{"uk":"Відвезти автомобіль на узбіччя, щоб не заважати руху","ru":"Отогнать автомобиль на обочину, чтобы не мешать движению","w":{"uk":"Після ДТП заборонено переміщати автомобіль і предмети — треба зберегти сліди пригоди.","ru":"После ДТП запрещено перемещать автомобиль и предметы — нужно сохранить следы происшествия."}},{"uk":"Поїхати за допомогою до найближчого відділку поліції","ru":"Поехать за помощью в ближайший отдел полиции","w":{"uk":"Їхати з місця ДТП не можна: треба залишатися на місці, допомогти потерпілим і повідомити поліцію телефоном.","ru":"Уезжать с места ДТП нельзя: нужно оставаться на месте, помочь пострадавшим и сообщить в полицию по телефону."}}],"c":0,"e":{"uk":"Водій, причетний до ДТП, зупиняється й залишається на місці, вмикає аварійну сигналізацію, виставляє знак аварійної зупинки, не переміщує автомобіль і предмети, надає домедичну допомогу, викликає швидку та повідомляє поліцію.","ru":"Водитель, причастный к ДТП, останавливается и остаётся на месте, включает аварийную сигнализацию, выставляет знак аварийной остановки, не перемещает автомобиль и предметы, оказывает домедицинскую помощь, вызывает скорую и сообщает в полицию."},"ref":["2.10"],"id":"q8c30f5884"},{"t":"s2","q":{"uk":"Сталася ДТП за участю двох застрахованих автомобілів: постраждалих немає, водії тверезі й згодні щодо обставин. Як можна оформити пригоду?","ru":"Произошло ДТП с участием двух застрахованных автомобилей: пострадавших нет, водители трезвые и согласны насчёт обстоятельств. Как можно оформить происшествие?"},"a":[{"uk":"Лише викликавши поліцію","ru":"Только вызвав полицию","w":{"uk":"Не лише: за таких умов водії мають право оформити європротокол без поліції.","ru":"Не только: при таких условиях водители вправе оформить европротокол без полиции."}},{"uk":"Самостійно скласти спільне повідомлення для страховика (європротокол) без виклику поліції","ru":"Самостоятельно составить совместное сообщение для страховщика (европротокол) без вызова полиции"},{"uk":"Розійтися без оформлення","ru":"Разъехаться без оформления","w":{"uk":"Пригоду треба оформити — хоча б самостійно складеним повідомленням для страховика, інакше збиток не відшкодують.","ru":"Происшествие нужно оформить — хотя бы самостоятельно составленным сообщением для страховщика, иначе ущерб не возместят."}}],"c":1,"e":{"uk":"Якщо зіткнулися лише два застраховані автомобілі, ніхто не постраждав, водії не мають ознак сп'яніння і згодні щодо обставин, вони можуть самі скласти повідомлення для страховика (паперове чи електронне) і залишити місце ДТП без виклику поліції.","ru":"Если столкнулись только два застрахованных автомобиля, никто не пострадал, водители не имеют признаков опьянения и согласны насчёт обстоятельств, они могут сами составить сообщение для страховщика (бумажное или электронное) и покинуть место ДТП без вызова полиции."},"ref":["2.11"],"id":"qce6a3a342"},{"t":"s2","q":{"uk":"З якого віку можна отримати право керування автомобілем категорії B?","ru":"С какого возраста можно получить право управления автомобилем категории B?"},"a":[{"uk":"З 16 років","ru":"С 16 лет","w":{"uk":"З 16 років можна отримати лише категорії A1 і A (мотоцикли).","ru":"С 16 лет можно получить только категории A1 и A (мотоциклы)."}},{"uk":"З 17 років","ru":"С 17 лет","w":{"uk":"Такої вікової межі в Правилах немає: категорія B — з 18 років.","ru":"Такого возрастного порога в Правилах нет: категория B — с 18 лет."}},{"uk":"З 18 років","ru":"С 18 лет"},{"uk":"З 19 років","ru":"С 19 лет","w":{"uk":"З 19 років відкриваються категорії з причепом (BE, C1E, CE). Категорія B — з 18.","ru":"С 19 лет открываются категории с прицепом (BE, C1E, CE). Категория B — с 18."}}],"c":2,"e":{"uk":"Категорії A1 і A — з 16 років; B1, B, C1, C — з 18 років; BE, C1E, CE — з 19 років; D1, D, D1E, DE, T — з 21 року.","ru":"Категории A1 и A — с 16 лет; B1, B, C1, C — с 18 лет; BE, C1E, CE — с 19 лет; D1, D, D1E, DE, T — с 21 года."},"ref":["2.13"],"id":"qe88996abe"},{"t":"s2","q":{"uk":"Якими транспортними засобами дозволяє керувати категорія B?","ru":"Какими транспортными средствами позволяет управлять категория B?"},"a":[{"uk":"Автомобілями з дозволеною максимальною масою до 3500 кг і не більше 8 сидячих місць, крім водійського (можна з причепом до 750 кг)","ru":"Автомобилями с разрешённой максимальной массой до 3500 кг и не более 8 сидячих мест, кроме водительского (можно с прицепом до 750 кг)"},{"uk":"Будь-якими автомобілями, крім автобусів","ru":"Любыми автомобилями, кроме автобусов","w":{"uk":"Ні: важкі вантажівки (понад 3,5 т) і автомобілі з понад 8 пасажирськими місцями потребують інших категорій.","ru":"Нет: тяжёлые грузовики (более 3,5 т) и автомобили с более чем 8 пассажирскими местами требуют других категорий."}},{"uk":"Автомобілями до 7500 кг","ru":"Автомобилями до 7500 кг","w":{"uk":"Автомобілі від 3,5 до 7,5 т — це категорія C1. Категорія B — до 3,5 т.","ru":"Автомобили от 3,5 до 7,5 т — это категория C1. Категория B — до 3,5 т."}}],"c":0,"e":{"uk":"Категорія B — автомобілі до 3500 кг з не більш ніж 8 місцями для сидіння, крім місця водія, а також состав з причепом повною масою до 750 кг. Важчий причіп потребує категорії BE.","ru":"Категория B — автомобили до 3500 кг с не более чем 8 местами для сидения, кроме места водителя, а также состав с прицепом полной массой до 750 кг. Более тяжёлый прицеп требует категории BE."},"ref":["2.13"],"id":"q9726f6a99"},{"t":"s2","q":{"uk":"Поліцейський зупинив ваш автомобіль. Що ви маєте право вимагати?","ru":"Полицейский остановил ваш автомобиль. Что вы вправе требовать?"},"a":[{"uk":"Нічого, ви зобов'язані лише виконувати вимоги","ru":"Ничего, вы обязаны только выполнять требования","w":{"uk":"У водія є права: знати причину зупинки, прізвище й посаду поліцейського, побачити його посвідчення.","ru":"У водителя есть права: знать причину остановки, фамилию и должность полицейского, увидеть его удостоверение."}},{"uk":"Дізнатися причину зупинки, прізвище і посаду поліцейського та побачити його посвідчення","ru":"Узнать причину остановки, фамилию и должность полицейского и увидеть его удостоверение"},{"uk":"Відео з нагрудної камери негайно на місці","ru":"Видео с нагрудной камеры немедленно на месте","w":{"uk":"Такого права Правила не передбачають. Ви можете дізнатися причину зупинки та посаду поліцейського і оскаржити його дії.","ru":"Такого права Правила не предусматривают. Вы можете узнать причину остановки и должность полицейского и обжаловать его действия."}}],"c":1,"e":{"uk":"Водій має право знати причину зупинки, перевірки та огляду, прізвище і посаду посадової особи та вимагати пред'явлення її посвідчення, а також оскаржити дії поліцейського.","ru":"Водитель имеет право знать причину остановки, проверки и осмотра, фамилию и должность должностного лица и требовать предъявления его удостоверения, а также обжаловать действия полицейского."},"ref":["2.14"],"id":"q24097ab56"},{"t":"s2","q":{"uk":"Чи можна керувати автомобілем у стані сильної втоми або під дією ліків, що знижують реакцію?","ru":"Можно ли управлять автомобилем в состоянии сильного утомления или под действием лекарств, снижающих реакцию?"},"a":[{"uk":"Так, якщо їхати повільно","ru":"Да, если ехать медленно","w":{"uk":"Низька швидкість не скасовує заборони: у стані втоми чи під дією таких ліків керувати не можна взагалі.","ru":"Низкая скорость не отменяет запрета: в состоянии утомления или под действием таких лекарств управлять нельзя вообще."}},{"uk":"Ні","ru":"Нет"},{"uk":"Так, на короткі відстані","ru":"Да, на короткие расстояния","w":{"uk":"Відстань не має значення: заборона діє на будь-яку поїздку.","ru":"Расстояние не имеет значения: запрет действует на любую поездку."}}],"c":1,"e":{"uk":"Заборонено керувати в стані будь-якого сп'яніння, у хворобливому стані, у стані стомлення та під впливом ліків, що знижують увагу і швидкість реакції.","ru":"Запрещено управлять в состоянии любого опьянения, в болезненном состоянии, в состоянии утомления и под влиянием лекарств, снижающих внимание и скорость реакции."},"ref":["2.9"],"id":"q648c60a6c"},{"t":"s2","q":{"uk":"З якої відстані мають чітко читатися символи номерного знака?","ru":"С какого расстояния должны чётко читаться символы номерного знака?"},"a":[{"uk":"10 м","ru":"10 м","w":{"uk":"Правила встановлюють більшу відстань: символи мають читатися з 20 м.","ru":"Правила устанавливают большее расстояние: символы должны читаться с 20 м."}},{"uk":"20 м","ru":"20 м"},{"uk":"50 м","ru":"50 м","w":{"uk":"Забагато: вимога — чіткість з відстані 20 м.","ru":"Слишком много: требование — чёткость с расстояния 20 м."}}],"c":1,"e":{"uk":"Заборонено керувати автомобілем, номерний знак якого закритий чи забруднений так, що символи не можна чітко визначити з відстані 20 м, а також неосвітленим у темряві чи перевернутим.","ru":"Запрещено управлять автомобилем, номерной знак которого закрыт или загрязнён так, что символы нельзя чётко определить с расстояния 20 м, а также не освещён в темноте или перевёрнут."},"ref":["2.9"],"id":"qe637309df"},{"t":"s2","q":{"uk":"Після ДТП водій чекає на поліцію. Чи можна йому випити заспокійливе на основі спирту?","ru":"После ДТП водитель ждёт полицию. Можно ли ему выпить успокоительное на основе спирта?"},"a":[{"uk":"Так, якщо він не керуватиме","ru":"Да, если он не будет управлять","w":{"uk":"Заборона діє до медичного огляду незалежно від того, чи збирається водій їхати далі.","ru":"Запрет действует до медицинского осмотра независимо от того, собирается ли водитель ехать дальше."}},{"uk":"Ні, до медичного огляду без призначення медика не можна вживати алкоголь і ліки на його основі (крім складу аптечки)","ru":"Нет, до медосмотра без назначения медика нельзя употреблять алкоголь и лекарства на его основе (кроме состава аптечки)"}],"c":1,"e":{"uk":"До проведення медичного огляду водієві заборонено без призначення медичного працівника вживати алкоголь, наркотики та ліки на їх основі, крім препаратів з офіційної аптечки.","ru":"До проведения медицинского осмотра водителю запрещено без назначения медицинского работника употреблять алкоголь, наркотики и лекарства на их основе, кроме препаратов из официальной аптечки."},"ref":["2.10"],"id":"q52b37e77b"},{"t":"s8","q":{"uk":"Сигнали регулювальника суперечать сигналам світлофора. Чим має керуватися водій?","ru":"Сигналы регулировщика противоречат сигналам светофора. Чем должен руководствоваться водитель?"},"a":[{"uk":"Сигналами регулювальника","ru":"Сигналами регулировщика"},{"uk":"Сигналами світлофора","ru":"Сигналами светофора","w":{"uk":"Регулювальник головніший за світлофор: його сигнали мають перевагу.","ru":"Регулировщик главнее светофора: его сигналы имеют преимущество."}},{"uk":"Знаками пріоритету","ru":"Знаками приоритета","w":{"uk":"Знаки пріоритету діють лише там, де немає регулювальника і світлофора. Регулювальник важливіший за все.","ru":"Знаки приоритета действуют только там, где нет регулировщика и светофора. Регулировщик важнее всего."}}],"c":0,"e":{"uk":"Сигнали регулювальника мають перевагу перед сигналами світлофорів і вимогами дорожніх знаків. Його додаткові вимоги виконують, навіть якщо вони суперечать світлофору, знакам і розмітці.","ru":"Сигналы регулировщика имеют преимущество перед сигналами светофоров и требованиями дорожных знаков. Его дополнительные требования выполняют, даже если они противоречат светофору, знакам и разметке."},"ref":["8.3"],"id":"q7e20fe99a"},{"t":"s8","q":{"uk":"Тимчасовий знак на жовтому щиті суперечить постійному знаку. Який знак виконувати?","ru":"Временный знак на жёлтом щите противоречит постоянному знаку. Какой знак выполнять?"},"a":[{"uk":"Постійний","ru":"Постоянный","w":{"uk":"Постійний знак поступається тимчасовому: тимчасові (на жовтому фоні) мають перевагу.","ru":"Постоянный знак уступает временному: временные (на жёлтом фоне) имеют преимущество."}},{"uk":"Тимчасовий","ru":"Временный"},{"uk":"Той, що встановлено ближче до проїзної частини","ru":"Тот, что установлен ближе к проезжей части","w":{"uk":"Місце встановлення не важливе: перевагу має тимчасовий знак на жовтому фоні.","ru":"Место установки не важно: преимущество имеет временный знак на жёлтом фоне."}}],"c":1,"e":{"uk":"Тимчасові дорожні знаки (на переносних пристроях або на щиті з жовтим фоном) мають перевагу перед постійними.","ru":"Временные дорожные знаки (на переносных устройствах или на щите с жёлтым фоном) имеют преимущество перед постоянными."},"ref":["8.2"],"id":"q044e692d8"},{"t":"s8","q":{"uk":"Вимоги дорожнього знака і горизонтальної розмітки суперечать одна одній. Чим керуватися?","ru":"Требования дорожного знака и горизонтальной разметки противоречат друг другу. Чем руководствоваться?"},"a":[{"uk":"Дорожнім знаком","ru":"Дорожным знаком"},{"uk":"Розміткою","ru":"Разметкой","w":{"uk":"Розмітка поступається знакам: якщо вони суперечать, виконують знак.","ru":"Разметка уступает знакам: если они противоречат, выполняют знак."}},{"uk":"На власний розсуд","ru":"На своё усмотрение","w":{"uk":"Ні, Правила чітко визначають: знак має перевагу перед розміткою.","ru":"Нет, Правила чётко определяют: знак имеет преимущество перед разметкой."}}],"c":0,"e":{"uk":"Дорожні знаки мають перевагу перед дорожньою розміткою.","ru":"Дорожные знаки имеют преимущество перед дорожной разметкой."},"ref":["8.2"],"id":"q7bf3536d3"},{"t":"s8","q":{"uk":"Що означає жовтий миготливий сигнал світлофора?","ru":"Что означает жёлтый мигающий сигнал светофора?"},"a":[{"uk":"Забороняє рух","ru":"Запрещает движение","w":{"uk":"Рух забороняє звичайний жовтий. Миготливий жовтий рух дозволяє.","ru":"Движение запрещает обычный жёлтый. Мигающий жёлтый движение разрешает."}},{"uk":"Дозволяє рух та інформує про небезпечне нерегульоване перехрестя або пішохідний перехід","ru":"Разрешает движение и информирует об опасном нерегулируемом перекрёстке или пешеходном переходе"},{"uk":"Попереджає, що зараз увімкнеться зелений","ru":"Предупреждает, что сейчас включится зелёный","w":{"uk":"Про наступне ввімкнення зеленого попереджає поєднання червоного і жовтого, а не миготливий жовтий.","ru":"О предстоящем включении зелёного предупреждает сочетание красного и жёлтого, а не мигающий жёлтый."}}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"straight","label":"1","color":"red","me":true}],"lights":[{"arm":"S","state":"flash"}]}},"c":1,"e":{"uk":"Жовтий миготливий сигнал дозволяє рух і попереджає про небезпечне нерегульоване перехрестя чи пішохідний перехід. Черговість проїзду в такому разі визначають знаки пріоритету.","ru":"Жёлтый мигающий сигнал разрешает движение и предупреждает об опасном нерегулируемом перекрёстке или пешеходном переходе. Очерёдность проезда в этом случае определяют знаки приоритета."},"ref":["8.7","16.1"],"id":"qe92cd8db2"},{"t":"s8","q":{"uk":"Під час наближення до перехрестя увімкнувся жовтий сигнал. Зупинитися перед стоп-лінією можна лише екстреним гальмуванням. Як діяти?","ru":"При приближении к перекрёстку включился жёлтый сигнал. Остановиться перед стоп-линией можно только экстренным торможением. Как поступить?"},"a":[{"uk":"Екстрено загальмувати","ru":"Экстренно затормозить","w":{"uk":"Екстрене гальмування небезпечне: в автомобіль може врізатися той, хто їде позаду. Правила дозволяють проїхати.","ru":"Экстренное торможение опасно: в автомобиль может врезаться едущий сзади. Правила разрешают проехать."}},{"uk":"Продовжити рух, забезпечивши безпеку","ru":"Продолжить движение, обеспечив безопасность"},{"uk":"Зупинитися за стоп-лінією посередині перехрестя","ru":"Остановиться за стоп-линией посередине перекрёстка","w":{"uk":"Зупинятися на перехресті не можна — це перешкода для інших. Якщо не встигаєте загальмувати, проїжджайте.","ru":"Останавливаться на перекрёстке нельзя — это помеха для других. Если не успеваете затормозить, проезжайте."}}],"c":1,"e":{"uk":"Водіям, які на жовтий сигнал або підняту вгору руку регулювальника не можуть зупинитися без екстреного гальмування, дозволено рухатися далі за умови безпеки руху.","ru":"Водителям, которые на жёлтый сигнал или поднятую вверх руку регулировщика не могут остановиться без экстренного торможения, разрешено двигаться дальше при условии безопасности движения."},"ref":["8.11"],"id":"q958fb265e"},{"t":"s8","q":{"uk":"Що означає поєднання червоного і жовтого сигналів світлофора?","ru":"Что означает сочетание красного и жёлтого сигналов светофора?"},"a":[{"uk":"Дозволяє рух з обережністю","ru":"Разрешает движение с осторожностью","w":{"uk":"Червоний з жовтим ще забороняє рух. Рушати можна лише на зелений.","ru":"Красный с жёлтым ещё запрещает движение. Трогаться можно только на зелёный."}},{"uk":"Дозволяє рух лише праворуч","ru":"Разрешает движение только направо","w":{"uk":"Таке значення має стрілка в додатковій секції, а не поєднання червоного і жовтого.","ru":"Такое значение имеет стрелка в дополнительной секции, а не сочетание красного и жёлтого."}},{"uk":"Забороняє рух і попереджає, що незабаром увімкнеться зелений","ru":"Запрещает движение и предупреждает, что скоро включится зелёный"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"straight","label":"1","color":"red","me":true}],"lights":[{"arm":"S","state":"redyellow"}]}},"c":2,"e":{"uk":"Поєднання червоного і жовтого забороняє рух і інформує про наступне вмикання зеленого сигналу.","ru":"Сочетание красного и жёлтого запрещает движение и информирует о предстоящем включении зелёного сигнала."},"ref":["8.7"],"id":"q661ce55a3"},{"t":"s8","q":{"uk":"Горить червоний сигнал і зелена стрілка в додатковій секції. Як можна рухатися в напрямку стрілки?","ru":"Горит красный сигнал и зелёная стрелка в дополнительной секции. Как можно двигаться в направлении стрелки?"},"a":[{"uk":"Рух заборонено, доки не ввімкнеться зелений","ru":"Движение запрещено, пока не включится зелёный","w":{"uk":"Зелена стрілка якраз дозволяє рух у своєму напрямку, навіть коли основний сигнал червоний.","ru":"Зелёная стрелка как раз разрешает движение в своём направлении, даже когда основной сигнал красный."}},{"uk":"Можна, пропустивши транспортні засоби, що рухаються з інших напрямків","ru":"Можно, пропустив транспортные средства, движущиеся с других направлений"},{"uk":"Можна, маючи перевагу перед усіма","ru":"Можно, имея преимущество перед всеми","w":{"uk":"Переваги немає: стрілка разом із червоним дозволяє рух лише за умови, що ви пропустите інших.","ru":"Преимущества нет: стрелка вместе с красным разрешает движение только при условии, что вы пропустите других."}}],"c":1,"e":{"uk":"Зелена стрілка в додатковій секції разом із жовтим або червоним сигналом дозволяє рух у напрямку стрілки за умови безперешкодного пропуску транспортних засобів з інших напрямків.","ru":"Зелёная стрелка в дополнительной секции вместе с жёлтым или красным сигналом разрешает движение в направлении стрелки при условии беспрепятственного пропуска транспортных средств с других направлений."},"ref":["8.7","16.9"],"id":"qc9c6cefb1"},{"t":"s8","q":{"uk":"На рівні червоного сигналу встановлено білу табличку із зеленою стрілкою праворуч. Звідки дозволено повертати праворуч на червоний?","ru":"На уровне красного сигнала установлена белая табличка с зелёной стрелкой направо. Откуда разрешено поворачивать направо на красный?"},"a":[{"uk":"Лише з крайньої правої смуги, пропустивши інших учасників руху","ru":"Только из крайней правой полосы, пропустив других участников движения"},{"uk":"З будь-якої смуги","ru":"Из любой полосы","w":{"uk":"Не з будь-якої: стрілка на табличці дозволяє поворот лише з крайньої правої смуги.","ru":"Не с любой: стрелка на табличке разрешает поворот только из крайней правой полосы."}},{"uk":"Повертати на червоний заборонено в будь-якому разі","ru":"Поворачивать на красный запрещено в любом случае","w":{"uk":"Табличка із зеленою стрілкою саме дозволяє повернути на червоний, але з крайньої правої смуги і пропустивши інших.","ru":"Табличка с зелёной стрелкой как раз разрешает повернуть на красный, но из крайней правой полосы и пропустив других."}}],"c":0,"e":{"uk":"Стрілка на табличці дозволяє рух на червоний з крайньої правої смуги (на дорогах з одностороннім рухом ліворуч — з крайньої лівої) за умови, що водій дасть дорогу всім, хто рухається з інших напрямків на дозвільний сигнал.","ru":"Стрелка на табличке разрешает движение на красный из крайней правой полосы (на дорогах с односторонним движением налево — из крайней левой) при условии, что водитель уступит дорогу всем, кто движется с других направлений на разрешающий сигнал."},"ref":["8.7","16.9"],"id":"qb5b013e3d"},{"t":"s8","q":{"uk":"Сигнал додаткової секції світлофора вимкнено. Що це означає?","ru":"Сигнал дополнительной секции светофора выключен. Что это значит?"},"a":[{"uk":"Рух у напрямку стрілки дозволено з обережністю","ru":"Движение в направлении стрелки разрешено с осторожностью","w":{"uk":"Вимкнена секція забороняє рух у напрямку стрілки, а не дозволяє його.","ru":"Выключенная секция запрещает движение в направлении стрелки, а не разрешает его."}},{"uk":"Рух у напрямку, вказаному стрілкою, заборонено","ru":"Движение в направлении, указанном стрелкой, запрещено"},{"uk":"Секція несправна, тож можна рухатися за основним сигналом","ru":"Секция неисправна, поэтому можно двигаться по основному сигналу","w":{"uk":"Правила трактують вимкнену секцію однозначно: рух у цьому напрямку заборонено.","ru":"Правила трактуют выключенную секцию однозначно: движение в этом направлении запрещено."}}],"c":1,"e":{"uk":"Вимкнений сигнал додаткової секції забороняє рух у напрямку, вказаному її стрілкою.","ru":"Выключенный сигнал дополнительной секции запрещает движение в направлении, указанном её стрелкой."},"ref":["8.7"],"id":"q0c0cbc4f9"},{"t":"s8","q":{"uk":"Сигнали реверсивного світлофора над смугою, позначеною з обох боків розміткою 1.9, вимкнені. Чи можна в'їжджати на цю смугу?","ru":"Сигналы реверсивного светофора над полосой, обозначенной с обеих сторон разметкой 1.9, выключены. Можно ли въезжать на эту полосу?"},"a":[{"uk":"Так, з обережністю","ru":"Да, с осторожностью","w":{"uk":"Обережність не допоможе: в'їзд на смугу з вимкненим реверсивним світлофором заборонено.","ru":"Осторожность не поможет: въезд на полосу с выключенным реверсивным светофором запрещён."}},{"uk":"Ні, в'їзд заборонено","ru":"Нет, въезд запрещён"},{"uk":"Так, якщо смуга вільна","ru":"Да, если полоса свободна","w":{"uk":"Навіть вільна, ця смуга може раптом стати зустрічною. При вимкнених сигналах в'їжджати заборонено.","ru":"Даже свободная, эта полоса может вдруг стать встречной. При выключенных сигналах въезжать запрещено."}}],"img":{"mark":"1.9"},"c":1,"e":{"uk":"При вимкнених сигналах реверсивного світлофора над смугою, позначеною з обох боків розміткою {m:1.9}, в'їзд на цю смугу заборонено.","ru":"При выключенных сигналах реверсивного светофора над полосой, обозначенной с обеих сторон разметкой {m:1.9}, въезд на эту полосу запрещён."},"ref":["8.7"],"id":"q67c391764"},{"t":"s8","q":{"uk":"Регулювальник стоїть до вас боком, руки витягнуті в сторони. Куди можна рухатися на легковому автомобілі?","ru":"Регулировщик стоит к вам боком, руки вытянуты в стороны. Куда можно двигаться на легковом автомобиле?"},"a":[{"uk":"Лише прямо","ru":"Только прямо","w":{"uk":"Не лише прямо: з боку регулювальника, коли руки в сторони, дозволено ще й поворот праворуч.","ru":"Не только прямо: со стороны регулировщика, когда руки в стороны, разрешён ещё и поворот направо."}},{"uk":"Прямо і праворуч","ru":"Прямо и направо"},{"uk":"У всіх напрямках","ru":"Во всех направлениях","w":{"uk":"Повертати ліворуч (і розвертатися) при такому сигналі не можна — лише прямо і праворуч.","ru":"Поворачивать налево (и разворачиваться) при таком сигнале нельзя — только прямо и направо."}},{"uk":"Рух заборонено","ru":"Движение запрещено","w":{"uk":"Заборонено лише з боку грудей і спини. Збоку (з лівого чи правого) рух прямо і праворуч дозволено.","ru":"Запрещено только со стороны груди и спины. Сбоку (слева или справа) движение прямо и направо разрешено."}}],"c":1,"e":{"uk":"Руки витягнуті в сторони або опущені: з лівого і правого боків дозволено рух трамвая прямо, нерейковим транспортним засобам — прямо і праворуч. З боку грудей і спини рух заборонено.","ru":"Руки вытянуты в стороны или опущены: с левой и правой сторон разрешено движение трамвая прямо, нерельсовым транспортным средствам — прямо и направо. Со стороны груди и спины движение запрещено."},"ref":["8.8"],"id":"q2eb013dad"},{"t":"s8","q":{"uk":"Регулювальник стоїть до вас грудьми, руки опущені. Що означає цей сигнал?","ru":"Регулировщик стоит к вам грудью, руки опущены. Что означает этот сигнал?"},"a":[{"uk":"Рух заборонено","ru":"Движение запрещено"},{"uk":"Дозволено рух прямо","ru":"Разрешено движение прямо","w":{"uk":"Рух прямо дозволено лише з боку лівого чи правого плеча регулювальника. З боку грудей — стоп.","ru":"Движение прямо разрешено только со стороны левого или правого плеча регулировщика. Со стороны груди — стоп."}},{"uk":"Дозволено рух лише праворуч","ru":"Разрешено движение только направо","w":{"uk":"Лише праворуч з боку грудей можна, коли права рука витягнута вперед. При опущених руках — стоп.","ru":"Только направо со стороны груди можно, когда правая рука вытянута вперёд. При опущенных руках — стоп."}}],"c":0,"e":{"uk":"Якщо руки витягнуті в сторони або опущені, з боку грудей і спини регулювальника рух усіх транспортних засобів і пішоходів заборонено.","ru":"Если руки вытянуты в стороны или опущены, со стороны груди и спины регулировщика движение всех транспортных средств и пешеходов запрещено."},"ref":["8.8"],"id":"qc85918764"},{"t":"s8","q":{"uk":"Регулювальник витягнув праву руку вперед, ви наближаєтеся з його лівого боку. Куди дозволено рух легковому автомобілю?","ru":"Регулировщик вытянул правую руку вперёд, вы приближаетесь с его левой стороны. Куда разрешено движение легковому автомобилю?"},"a":[{"uk":"Лише праворуч","ru":"Только направо","w":{"uk":"Лише праворуч дозволено тим, хто з боку грудей. З лівого боку регулювальника можна в усіх напрямках.","ru":"Только направо разрешено тем, кто со стороны груди. С левой стороны регулировщика можно во всех направлениях."}},{"uk":"Лише прямо","ru":"Только прямо","w":{"uk":"Обмеження лише прямо в цьому сигналі немає: з лівого боку дозволено всі напрямки.","ru":"Ограничения только прямо в этом сигнале нет: с левой стороны разрешены все направления."}},{"uk":"У всіх напрямках","ru":"Во всех направлениях"}],"c":2,"e":{"uk":"Права рука витягнута вперед: з лівого боку регулювальника нерейковим транспортним засобам дозволено рух у всіх напрямках, трамваю — ліворуч.","ru":"Правая рука вытянута вперёд: с левой стороны регулировщика нерельсовым транспортным средствам разрешено движение во всех направлениях, трамваю — налево."},"ref":["8.8"],"id":"q2dea8ff24"},{"t":"s8","q":{"uk":"Регулювальник витягнув праву руку вперед і стоїть до вас грудьми. Куди можна рухатися?","ru":"Регулировщик вытянул правую руку вперёд и стоит к вам грудью. Куда можно двигаться?"},"a":[{"uk":"Лише праворуч","ru":"Только направо"},{"uk":"Прямо і праворуч","ru":"Прямо и направо","w":{"uk":"Прямо з боку грудей не можна: дозволено лише праворуч.","ru":"Прямо со стороны груди нельзя: разрешено только направо."}},{"uk":"Рух заборонено","ru":"Движение запрещено","w":{"uk":"Заборонено з правого боку і зі спини. З боку грудей можна повернути праворуч.","ru":"Запрещено с правой стороны и со спины. Со стороны груди можно повернуть направо."}}],"c":0,"e":{"uk":"Коли права рука витягнута вперед, з боку грудей усім транспортним засобам дозволено рух лише праворуч. З правого боку і зі спини рух заборонено.","ru":"Когда правая рука вытянута вперёд, со стороны груди всем транспортным средствам разрешено движение только направо. С правой стороны и со спины движение запрещено."},"ref":["8.8"],"id":"qe58d73b8d"},{"t":"s8","q":{"uk":"Що означає піднята вгору рука регулювальника?","ru":"Что означает поднятая вверх рука регулировщика?"},"a":[{"uk":"Увага, зараз зміниться сигнал, можна продовжувати рух","ru":"Внимание, сейчас сменится сигнал, можно продолжать движение","w":{"uk":"Рука вгору — це не попередження, а заборона руху для всіх (рух далі — лише якщо зупинитися можна тільки екстреним гальмуванням).","ru":"Рука вверх — это не предупреждение, а запрет движения для всех (ехать дальше — только если остановиться можно лишь экстренным торможением)."}},{"uk":"Рух усіх транспортних засобів і пішоходів заборонено в усіх напрямках","ru":"Движение всех транспортных средств и пешеходов запрещено во всех направлениях"},{"uk":"Рух дозволено лише трамваям","ru":"Движение разрешено только трамваям","w":{"uk":"Трамваям при піднятій руці теж заборонено — рух зупиняють усім.","ru":"Трамваям при поднятой руке тоже запрещено — движение останавливают всем."}}],"c":1,"e":{"uk":"Рука, піднята вгору, забороняє рух усім в усіх напрямках. Хто вже не може зупинитися без екстреного гальмування, може проїхати далі.","ru":"Поднятая вверх рука запрещает движение всем во всех направлениях. Кто уже не может остановиться без экстренного торможения, может проехать дальше."},"ref":["8.8","8.11"],"id":"qb22313d65"},{"t":"s8","q":{"uk":"Перед залізничним переїздом горить заборонний сигнал, стоп-лінії та знака 5.69 немає. Де треба зупинитися?","ru":"Перед железнодорожным переездом горит запрещающий сигнал, стоп-линии и знака 5.69 нет. Где нужно остановиться?"},"a":[{"uk":"Безпосередньо перед рейками","ru":"Непосредственно перед рельсами","w":{"uk":"Під'їжджати впритул до рейок небезпечно: Правила вимагають зупинитися не ближче 10 м.","ru":"Подъезжать вплотную к рельсам опасно: Правила требуют остановиться не ближе 10 м."}},{"uk":"Не ближче 10 м до найближчої рейки","ru":"Не ближе 10 м до ближайшего рельса"},{"uk":"Не ближче 5 м до шлагбаума","ru":"Не ближе 5 м до шлагбаума","w":{"uk":"Відстань відміряють від найближчої рейки (10 м), а не від шлагбаума.","ru":"Расстояние отмеряют от ближайшего рельса (10 м), а не от шлагбаума."}}],"c":1,"e":{"uk":"На заборонний сигнал водій зупиняється перед стоп-лінією або знаком {s:5.69}, а якщо їх немає — не ближче 10 м до найближчої рейки.","ru":"На запрещающий сигнал водитель останавливается перед стоп-линией или знаком {s:5.69}, а если их нет — не ближе 10 м до ближайшего рельса."},"ref":["8.10"],"id":"qc6751ad4a"},{"t":"s8","q":{"uk":"Сигнали світлофора (крім жовтого миготливого) і знаки пріоритету суперечать одне одному. Чим керуватися?","ru":"Сигналы светофора (кроме жёлтого мигающего) и знаки приоритета противоречат друг другу. Чем руководствоваться?"},"a":[{"uk":"Знаками пріоритету","ru":"Знаками приоритета","w":{"uk":"Працюючий світлофор головніший за знаки пріоритету: на регульованому перехресті вони не діють.","ru":"Работающий светофор главнее знаков приоритета: на регулируемом перекрёстке они не действуют."}},{"uk":"Сигналами світлофора","ru":"Сигналами светофора"}],"c":1,"e":{"uk":"Сигнали світлофорів, крім жовтого миготливого, мають перевагу перед знаками пріоритету.","ru":"Сигналы светофоров, кроме жёлтого мигающего, имеют преимущество перед знаками приоритета."},"ref":["8.3"],"id":"q86f7b0f02"},{"t":"s8","q":{"uk":"Якого кольору світлоповертачі на напрямних стовпчиках праворуч від дороги?","ru":"Какого цвета световозвращатели на направляющих столбиках справа от дороги?"},"a":[{"uk":"Червоного","ru":"Красного"},{"uk":"Білого","ru":"Белого","w":{"uk":"Білі світлоповертачі ставлять на стовпчиках ліворуч від дороги.","ru":"Белые световозвращатели ставят на столбиках слева от дороги."}},{"uk":"Жовтого","ru":"Жёлтого","w":{"uk":"Жовтих світлоповертачів на напрямних стовпчиках Правила не передбачають: праворуч — червоні, ліворуч — білі.","ru":"Жёлтых световозвращателей на направляющих столбиках Правила не предусматривают: справа — красные, слева — белые."}}],"c":0,"e":{"uk":"Напрямні стовпчики обладнують світлоповертачами: праворуч — червоного кольору, ліворуч — білого.","ru":"Направляющие столбики оборудуют световозвращателями: справа — красного цвета, слева — белого."},"ref":["8.6"],"id":"q9ff604df9"},{"t":"s9","q":{"uk":"За яку відстань до маневру в населеному пункті треба вмикати покажчик повороту?","ru":"За какое расстояние до манёвра в населённом пункте нужно включать указатель поворота?"},"a":[{"uk":"Завчасно, але не менш як за 50–100 м","ru":"Заблаговременно, но не менее чем за 50–100 м"},{"uk":"За 10–20 м","ru":"За 10–20 м","w":{"uk":"Замало: інші не встигнуть зрозуміти ваш намір. У місті — не менш як за 50–100 м.","ru":"Слишком мало: другие не успеют понять ваш намерение. В городе — не менее чем за 50–100 м."}},{"uk":"За 150–200 м","ru":"За 150–200 м","w":{"uk":"150–200 м — це норма поза населеним пунктом. У місті — 50–100 м.","ru":"150–200 м — это норма вне населённого пункта. В городе — 50–100 м."}}],"c":0,"e":{"uk":"Сигнал подають завчасно з урахуванням швидкості: у населених пунктах не менш як за 50–100 м, поза ними — за 150–200 м. Вимикають одразу після маневру.","ru":"Сигнал подают заблаговременно с учётом скорости: в населённых пунктах не менее чем за 50–100 м, вне их — за 150–200 м. Выключают сразу после манёвра."},"ref":["9.4"],"id":"q01bbe5de0"},{"t":"s9","q":{"uk":"Чи дає увімкнений покажчик повороту перевагу в русі?","ru":"Даёт ли включённый указатель поворота преимущество в движении?"},"a":[{"uk":"Так, інші мають пропустити","ru":"Да, другие должны пропустить","w":{"uk":"Покажчик лише попереджає про намір. Він не зобов'язує інших вас пропускати.","ru":"Указатель только предупреждает о намерении. Он не обязывает других вас пропускать."}},{"uk":"Ні, він не дає переваги і не звільняє від запобіжних заходів","ru":"Нет, он не даёт преимущества и не освобождает от мер предосторожности"},{"uk":"Так, але лише в населеному пункті","ru":"Да, но только в населённом пункте","w":{"uk":"Ні в місті, ні за містом сигнал переваги не дає.","ru":"Ни в городе, ни за городом сигнал преимущества не даёт."}}],"c":1,"e":{"uk":"Подавання попереджувального сигналу не дає водієві переваги і не звільняє його від вжиття запобіжних заходів.","ru":"Подача предупредительного сигнала не даёт водителю преимущества и не освобождает его от принятия мер предосторожности."},"ref":["9.4"],"id":"qb35ea7989"},{"t":"s9","q":{"uk":"Покажчики повороту несправні. Як подати сигнал повороту ліворуч?","ru":"Указатели поворота неисправны. Как подать сигнал поворота налево?"},"a":[{"uk":"Лівою рукою, витягнутою вбік, або правою рукою, витягнутою вбік і зігнутою в лікті вгору","ru":"Левой рукой, вытянутой в сторону, или правой рукой, вытянутой в сторону и согнутой в локте вверх"},{"uk":"Рукою, піднятою вгору","ru":"Рукой, поднятой вверх","w":{"uk":"Піднята вгору рука — це сигнал гальмування, а не повороту.","ru":"Поднятая вверх рука — это сигнал торможения, а не поворота."}},{"uk":"Правою рукою, витягнутою вбік","ru":"Правой рукой, вытянутой в сторону","w":{"uk":"Права рука, витягнута вбік, означає поворот праворуч.","ru":"Правая рука, вытянутая в сторону, означает поворот направо."}}],"c":0,"e":{"uk":"Поворот ліворуч (а також розворот, перестроювання ліворуч, зупинка зліва) показують лівою рукою, витягнутою вбік, або правою, витягнутою вбік і зігнутою в лікті під прямим кутом угору. Рука, піднята вгору, — сигнал гальмування.","ru":"Поворот налево (а также разворот, перестроение налево, остановку слева) показывают левой рукой, вытянутой в сторону, или правой, вытянутой в сторону и согнутой в локте под прямым углом вверх. Рука, поднятая вверх, — сигнал торможения."},"ref":["9.3"],"id":"qd696f51a0"},{"t":"s9","q":{"uk":"Коли в населеному пункті можна подавати звуковий сигнал?","ru":"Когда в населённом пункте можно подавать звуковой сигнал?"},"a":[{"uk":"Для привернення уваги водія, якого обганяють","ru":"Для привлечения внимания обгоняемого водителя","w":{"uk":"Звуком попереджати того, кого обганяєте, можна лише поза населеним пунктом. У місті — перемиканням фар.","ru":"Звуком предупреждать обгоняемого можно только вне населённого пункта. В городе — переключением фар."}},{"uk":"Лише коли без цього неможливо запобігти ДТП","ru":"Только когда без этого невозможно предотвратить ДТП"},{"uk":"Перед кожним перехрестям","ru":"Перед каждым перекрёстком","w":{"uk":"Сигналити перед перехрестями в місті заборонено — лише для запобігання ДТП.","ru":"Сигналить перед перекрёстками в городе запрещено — только для предотвращения ДТП."}}],"c":1,"e":{"uk":"У населених пунктах звуковий сигнал заборонено, крім випадків, коли без нього неможливо запобігти ДТП. Поза населеними пунктами звуком можна попередити водія, якого обганяєте.","ru":"В населённых пунктах звуковой сигнал запрещён, кроме случаев, когда без него невозможно предотвратить ДТП. Вне населённых пунктов звуком можно предупредить обгоняемого водителя."},"ref":["9.5","9.6"],"id":"qfd3a3059d"},{"t":"s9","q":{"uk":"Що має бути ввімкнено на легковому автомобілі поза населеним пунктом удень?","ru":"Что должно быть включено на легковом автомобиле вне населённого пункта днём?"},"a":[{"uk":"Нічого","ru":"Ничего","w":{"uk":"Поза населеним пунктом удень обов'язково мають горіти денні ходові вогні або ближнє світло.","ru":"Вне населённого пункта днём обязательно должны гореть дневные ходовые огни или ближний свет."}},{"uk":"Денні ходові вогні, а якщо їх немає — ближнє світло","ru":"Дневные ходовые огни, а если их нет — ближний свет"},{"uk":"Протитуманні фари","ru":"Противотуманные фары","w":{"uk":"Протитуманні фари вмикають лише за недостатньої видимості, а не замість денних вогнів.","ru":"Противотуманные фары включают только при недостаточной видимости, а не вместо дневных огней."}},{"uk":"Габаритні вогні","ru":"Габаритные огни","w":{"uk":"Габаритні вогні не роблять автомобіль помітним удень. Потрібні денні ходові вогні або ближнє світло.","ru":"Габаритные огни не делают автомобиль заметным днём. Нужны дневные ходовые огни или ближний свет."}}],"c":1,"e":{"uk":"Поза населеними пунктами на всіх механічних транспортних засобах мають бути ввімкнені денні ходові вогні, а якщо їх немає в конструкції — ближнє світло фар.","ru":"Вне населённых пунктов на всех механических транспортных средствах должны быть включены дневные ходовые огни, а если их нет в конструкции — ближний свет фар."},"ref":["9.8"],"id":"q5a2e1f3ca"},{"t":"s9","q":{"uk":"У якому з випадків вмикати аварійну сигналізацію НЕ обов'язково?","ru":"В каком из случаев включать аварийную сигнализацию НЕ обязательно?"},"a":[{"uk":"Вимушена зупинка на дорозі","ru":"Вынужденная остановка на дороге","w":{"uk":"За вимушеної зупинки аварійна сигналізація обов'язкова.","ru":"При вынужденной остановке аварийная сигнализация обязательна."}},{"uk":"Зупинка через засліплення світлом фар","ru":"Остановка из-за ослепления светом фар","w":{"uk":"Обов'язкова: якщо вас засліпили і ви зупинилися, вмикайте аварійку.","ru":"Обязательна: если вас ослепили и вы остановились, включайте аварийку."}},{"uk":"Зупинка для посадки пасажира в дозволеному місці","ru":"Остановка для посадки пассажира в разрешённом месте"},{"uk":"Автомобіль буксирують","ru":"Автомобиль буксируют","w":{"uk":"На автомобілі, що буксирується, аварійна сигналізація обов'язкова.","ru":"На буксируемом автомобиле аварийная сигнализация обязательна."}}],"c":2,"e":{"uk":"Аварійну сигналізацію вмикають за вимушеної зупинки, зупинки на вимогу поліцейського чи через засліплення, під час руху з несправностями, на автомобілі, що буксирується, під час посадки дітей в автобус зі знаком «Діти», на зупинці колони та в разі ДТП.","ru":"Аварийную сигнализацию включают при вынужденной остановке, остановке по требованию полицейского или из-за ослепления, при движении с неисправностями, на буксируемом автомобиле, при посадке детей в автобус со знаком «Дети», на остановке колонны и при ДТП."},"ref":["9.9"],"id":"q2ff1de7b8"},{"t":"s9","q":{"uk":"На якій відстані від автомобіля треба виставити знак аварійної зупинки після ДТП у населеному пункті?","ru":"На каком расстоянии от автомобиля нужно выставить знак аварийной остановки после ДТП в населённом пункте?"},"a":[{"uk":"Не ближче 10 м","ru":"Не ближе 10 м","w":{"uk":"10 м — замало: інші водії не встигнуть зреагувати. У населеному пункті — не ближче 20 м.","ru":"10 м — мало: другие водители не успеют среагировать. В населённом пункте — не ближе 20 м."}},{"uk":"Не ближче 20 м","ru":"Не ближе 20 м"},{"uk":"Не ближче 40 м","ru":"Не ближе 40 м","w":{"uk":"40 м — норма поза населеним пунктом. У населеному пункті — не ближче 20 м.","ru":"40 м — норма вне населённого пункта. В населённом пункте — не ближе 20 м."}},{"uk":"Не ближче 50 м","ru":"Не ближе 50 м","w":{"uk":"Правила вимагають «не ближче 20 м» у місті. 50 м — не нормативне значення.","ru":"Правила требуют «не ближе 20 м» в городе. 50 м — не нормативное значение."}}],"c":1,"e":{"uk":"Знак аварійної зупинки (або миготливий червоний ліхтар) встановлюють не ближче 20 м від автомобіля в населеному пункті і 40 м — поза ним.","ru":"Знак аварийной остановки (или мигающий красный фонарь) устанавливают не ближе 20 м от автомобиля в населённом пункте и 40 м — вне его."},"ref":["9.10"],"id":"qb7e34f572"},{"t":"s9","q":{"uk":"Знак аварійної зупинки поза населеним пунктом встановлюють не ближче ніж...","ru":"Знак аварийной остановки вне населённого пункта устанавливают не ближе чем..."},"a":[{"uk":"20 м","ru":"20 м","w":{"uk":"20 м — норма для населеного пункту. Поза ним — не ближче 40 м.","ru":"20 м — норма для населённого пункта. Вне его — не ближе 40 м."}},{"uk":"30 м","ru":"30 м","w":{"uk":"Такої норми немає: поза населеним пунктом — не ближче 40 м.","ru":"Такой нормы нет: вне населённого пункта — не ближе 40 м."}},{"uk":"40 м","ru":"40 м"},{"uk":"100 м","ru":"100 м","w":{"uk":"Мінімальна відстань — 40 м. Виставити далі можна, але правильна відповідь — «не ближче 40 м».","ru":"Минимальное расстояние — 40 м. Выставить дальше можно, но правильный ответ — «не ближе 40 м»."}}],"c":2,"e":{"uk":"Поза населеними пунктами знак аварійної зупинки — не ближче 40 м від транспортного засобу.","ru":"Вне населённых пунктов знак аварийной остановки — не ближе 40 м от транспортного средства."},"ref":["9.10"],"id":"q3eacf129d"},{"t":"s9","q":{"uk":"Коли, крім ДТП, обов'язково виставляти знак аварійної зупинки?","ru":"Когда, кроме ДТП, обязательно выставлять знак аварийной остановки?"},"a":[{"uk":"За вимушеної зупинки там, де оглядовість хоча б в одному напрямку менше 100 м","ru":"При вынужденной остановке там, где обзорность хотя бы в одном направлении менее 100 м"},{"uk":"За будь-якої зупинки в темну пору доби","ru":"При любой остановке в тёмное время суток","w":{"uk":"Звичайна зупинка в темряві не вимагає знака: вмикають габарити. Знак — після ДТП або за вимушеної зупинки з поганою оглядовістю.","ru":"Обычная остановка в темноте не требует знака: включают габариты. Знак — после ДТП или при вынужденной остановке с плохой обзорностью."}},{"uk":"Під час стоянки понад 5 хвилин","ru":"Во время стоянки более 5 минут","w":{"uk":"Стоянка в дозволеному місці не вимагає знака аварійної зупинки.","ru":"Стоянка в разрешённом месте не требует знака аварийной остановки."}}],"c":0,"e":{"uk":"Разом з аварійкою знак виставляють у разі ДТП і вимушеної зупинки там, де оглядовість дороги хоча б в одному напрямку менше 100 м.","ru":"Вместе с аварийкой знак выставляют при ДТП и вынужденной остановке там, где обзорность дороги хотя бы в одном направлении менее 100 м."},"ref":["9.10"],"id":"qf1a5d8516"},{"t":"s9","q":{"uk":"Як попередити водія, якого обганяєте, у населеному пункті?","ru":"Как предупредить обгоняемого водителя в населённом пункте?"},"a":[{"uk":"Звуковим сигналом","ru":"Звуковым сигналом","w":{"uk":"У населеному пункті звуковий сигнал заборонено, крім випадків запобігання ДТП.","ru":"В населённом пункте звуковой сигнал запрещён, кроме случаев предотвращения ДТП."}},{"uk":"Перемиканням світла фар","ru":"Переключением света фар"},{"uk":"Аварійною сигналізацією","ru":"Аварийной сигнализацией","w":{"uk":"Аварійка не призначена для попередження про обгін. Для цього — перемикання фар.","ru":"Аварийка не предназначена для предупреждения об обгоне. Для этого — переключение фар."}}],"c":1,"e":{"uk":"Для привернення уваги водія, якого обганяють, можна перемикати світло фар, а поза населеними пунктами — ще й подати звуковий сигнал.","ru":"Для привлечения внимания обгоняемого водителя можно переключать свет фар, а вне населённых пунктов — ещё и подать звуковой сигнал."},"ref":["9.6","9.5"],"id":"q38a148288"},{"t":"s10","q":{"uk":"Водій виїжджає з території АЗС на дорогу. Кому він повинен дати дорогу?","ru":"Водитель выезжает с территории АЗС на дорогу. Кому он должен уступить дорогу?"},"a":[{"uk":"Лише транспортним засобам, що наближаються ліворуч","ru":"Только транспортным средствам, приближающимся слева","w":{"uk":"Не лише ліворуч: виїжджаючи з прилеглої території, ви пропускаєте всіх, хто рухається дорогою з обох боків, і пішоходів.","ru":"Не только слева: выезжая с прилегающей территории, вы пропускаете всех, кто едет по дороге с обеих сторон, и пешеходов."}},{"uk":"Нікому, якщо він увімкнув покажчик повороту","ru":"Никому, если он включил указатель поворота","w":{"uk":"Покажчик повороту лише попереджає і не дає переваги. Той, хто виїжджає з АЗС, пропускає всіх.","ru":"Указатель поворота только предупреждает и не даёт преимущества. Выезжающий с АЗС пропускает всех."}},{"uk":"Пішоходам і транспортним засобам, що рухаються дорогою","ru":"Пешеходам и транспортным средствам, движущимся по дороге"}],"c":2,"e":{"uk":"Виїжджаючи з прилеглої території (двори, стоянки, АЗС, житлова зона), водій дає дорогу пішоходам і транспортним засобам, що рухаються по дорозі чи тротуару, який він перетинає.","ru":"Выезжая с прилегающей территории (дворы, стоянки, АЗС, жилая зона), водитель уступает дорогу пешеходам и транспортным средствам, движущимся по дороге или тротуару, который он пересекает."},"ref":["10.2"],"id":"q26b0b546e"},{"t":"s10","q":{"uk":"Водій 1 перестроюється ліворуч. Хто має перевагу?","ru":"Водитель 1 перестраивается налево. У кого преимущество?"},"a":[{"uk":"Автомобіль 1, бо він увімкнув покажчик повороту","ru":"Автомобиль 1, так как он включил указатель поворота","w":{"uk":"Покажчик повороту не дає переваги. Перестроюючись, ви пропускаєте тих, хто вже їде цією смугою.","ru":"Указатель поворота не даёт преимущества. Перестраиваясь, вы пропускаете тех, кто уже едет по этой полосе."}},{"uk":"Автомобіль 2, що рухається смугою, на яку перестроюється водій 1","ru":"Автомобиль 2, движущийся по полосе, на которую перестраивается водитель 1"},{"uk":"Той, хто рухається швидше","ru":"Тот, кто движется быстрее","w":{"uk":"Швидкість не визначає черговість: перевагу має той, хто вже рухається смугою, на яку ви перестроюєтеся.","ru":"Скорость не определяет очерёдность: преимущество у того, кто уже движется по полосе, на которую вы перестраиваетесь."}}],"img":{"scene":{"road":"straight","lanes":2,"center":"solid","cars":[{"x":150,"dir":"E","lane":0,"move":"left","label":"1","color":"red","me":true},{"x":60,"dir":"E","lane":1,"move":"straight","label":"2","color":"blue"}]}},"c":1,"e":{"uk":"Перестроюючись, водій дає дорогу транспортним засобам, що рухаються в попутному напрямку смугою, на яку він має намір перестроїтися.","ru":"При перестроении водитель уступает дорогу транспортным средствам, движущимся в попутном направлении по полосе, на которую он намерен перестроиться."},"ref":["10.3"],"id":"q40e2cf663"},{"t":"s10","q":{"uk":"Водії 1 і 2 одночасно перестроюються на середню смугу. Хто має поступитися?","ru":"Водители 1 и 2 одновременно перестраиваются на среднюю полосу. Кто должен уступить?"},"a":[{"uk":"Водій 1, бо водій 2 знаходиться праворуч від нього","ru":"Водитель 1, так как водитель 2 находится справа от него"},{"uk":"Водій 2, бо водій 1 рухається лівішою смугою","ru":"Водитель 2, так как водитель 1 движется по более левой полосе","w":{"uk":"Навпаки: при одночасному перестроюванні поступається той, хто ліворуч, — тобто водій 1.","ru":"Наоборот: при одновременном перестроении уступает тот, кто слева, — то есть водитель 1."}},{"uk":"Той, хто першим увімкнув покажчик","ru":"Тот, кто первым включил указатель","w":{"uk":"Час увімкнення покажчика не важливий. Правило: лівий поступається правому.","ru":"Время включения указателя не важно. Правило: левый уступает правому."}}],"img":{"scene":{"road":"straight","lanes":3,"center":"double","cars":[{"x":120,"dir":"E","lane":2,"move":"right","label":"1","color":"red","me":true},{"x":120,"dir":"E","lane":0,"move":"left","label":"2","color":"blue"}]}},"c":0,"e":{"uk":"За одночасного перестроювання водій, який знаходиться ліворуч, дає дорогу транспортному засобу, що знаходиться праворуч.","ru":"При одновременном перестроении водитель, находящийся слева, уступает дорогу транспортному средству, находящемуся справа."},"ref":["10.3"],"id":"q87bf6c3da"},{"t":"s10","q":{"uk":"Як треба підготуватися до повороту ліворуч на дорозі з двома смугами в одному напрямку?","ru":"Как нужно подготовиться к повороту налево на дороге с двумя полосами в одном направлении?"},"a":[{"uk":"Повертати з будь-якої смуги, увімкнувши покажчик","ru":"Поворачивать с любой полосы, включив указатель","w":{"uk":"З правої смуги ліворуч повертати не можна: ви перетнете шлях тим, хто їде лівою смугою. Треба завчасно зайняти крайнє ліве положення.","ru":"С правой полосы налево поворачивать нельзя: вы пересечёте путь тем, кто едет по левой полосе. Нужно заранее занять крайнее левое положение."}},{"uk":"Завчасно зайняти крайнє ліве положення на проїзній частині цього напрямку","ru":"Заблаговременно занять крайнее левое положение на проезжей части этого направления"},{"uk":"Зупинитися на правому узбіччі й пропустити всіх","ru":"Остановиться на правой обочине и пропустить всех","w":{"uk":"Зупинка на узбіччі не є способом повороту ліворуч і створить перешкоди. Треба перестроїтися в ліву смугу.","ru":"Остановка на обочине не является способом поворота налево и создаст помехи. Нужно перестроиться в левую полосу."}}],"c":1,"e":{"uk":"Перед поворотом праворуч чи ліворуч або розворотом водій завчасно займає відповідне крайнє положення. Винятки — в'їзд на кільце та випадки, коли напрямок визначено знаками чи розміткою.","ru":"Перед поворотом направо или налево либо разворотом водитель заблаговременно занимает соответствующее крайнее положение. Исключения — въезд на кольцо и случаи, когда направление определено знаками или разметкой."},"ref":["10.4"],"id":"qfd0ca0d82"},{"t":"s10","q":{"uk":"У якому з перелічених місць розворот заборонено?","ru":"В каком из перечисленных мест разворот запрещён?"},"a":[{"uk":"На мосту","ru":"На мосту","w":{"uk":"Правильно, але неповно: розворот заборонено і на мосту, і в тунелі, і на переїзді.","ru":"Верно, но неполно: разворот запрещён и на мосту, и в тоннеле, и на переезде."}},{"uk":"У тунелі","ru":"В тоннеле","w":{"uk":"Правильно, але неповно: розворот заборонено в усіх трьох названих місцях.","ru":"Верно, но неполно: разворот запрещён во всех трёх названных местах."}},{"uk":"На залізничному переїзді","ru":"На железнодорожном переезде","w":{"uk":"Правильно, але неповно: на мосту й у тунелі розворот теж заборонено.","ru":"Верно, но неполно: на мосту и в тоннеле разворот тоже запрещён."}},{"uk":"У всіх перелічених місцях","ru":"Во всех перечисленных местах"}],"c":3,"e":{"uk":"Розворот заборонено на залізничних переїздах, на мостах, шляхопроводах, естакадах і під ними, у тунелях, за видимості менше 100 м хоча б в одному напрямку, на пішохідних переходах і ближче 10 м від них, на автомагістралях і дорогах для автомобілів (крім перехресть і місць {s:5.29}, {s:5.30}).","ru":"Разворот запрещён на железнодорожных переездах, на мостах, путепроводах, эстакадах и под ними, в тоннелях, при видимости менее 100 м хотя бы в одном направлении, на пешеходных переходах и ближе 10 м от них, на автомагистралях и дорогах для автомобилей (кроме перекрёстков и мест {s:5.29}, {s:5.30})."},"ref":["10.7"],"id":"qa7334e352"},{"t":"s10","q":{"uk":"За якої видимості дороги розворот заборонено?","ru":"При какой видимости дороги разворот запрещён?"},"a":[{"uk":"Менше 50 м в обох напрямках","ru":"Менее 50 м в обоих направлениях","w":{"uk":"Межа більша — 100 м, і достатньо поганої видимості хоча б в одному напрямку.","ru":"Порог больше — 100 м, и достаточно плохой видимости хотя бы в одном направлении."}},{"uk":"Менше 100 м хоча б в одному напрямку","ru":"Менее 100 м хотя бы в одном направлении"},{"uk":"Менше 300 м у напрямку руху","ru":"Менее 300 м в направлении движения","w":{"uk":"300 м — межа «недостатньої видимості» взагалі. Для заборони розвороту — менше 100 м.","ru":"300 м — порог «недостаточной видимости» вообще. Для запрета разворота — менее 100 м."}}],"c":1,"e":{"uk":"Розворот заборонено, якщо видимість дороги менше 100 м хоча б в одному напрямку.","ru":"Разворот запрещён, если видимость дороги менее 100 м хотя бы в одном направлении."},"ref":["10.7"],"id":"qb06af2fb4"},{"t":"s10","q":{"uk":"На якій найменшій відстані від пішохідного переходу дозволено розворот поза перехрестям?","ru":"На каком наименьшем расстоянии от пешеходного перехода разрешён разворот вне перекрёстка?"},"a":[{"uk":"5 м","ru":"5 м","w":{"uk":"5 м — замало: розворот заборонено ближче 10 м від переходу.","ru":"5 м — мало: разворот запрещён ближе 10 м от перехода."}},{"uk":"10 м","ru":"10 м"},{"uk":"15 м","ru":"15 м","w":{"uk":"Розворот дозволено вже з 10 м, тож 15 м — не найменша відстань.","ru":"Разворот разрешён уже с 10 м, поэтому 15 м — не наименьшее расстояние."}},{"uk":"20 м","ru":"20 м","w":{"uk":"20 м — не нормативне значення: найменша дозволена відстань — 10 м.","ru":"20 м — не нормативное значение: наименьшее разрешённое расстояние — 10 м."}}],"c":1,"e":{"uk":"Розворот заборонено на пішохідних переходах і ближче 10 м від них з обох боків (крім дозволеного розвороту на перехресті).","ru":"Разворот запрещён на пешеходных переходах и ближе 10 м от них с обеих сторон (кроме разрешённого разворота на перекрёстке)."},"ref":["10.7"],"id":"qeedd67e1e"},{"t":"s10","q":{"uk":"Де дозволено рух заднім ходом?","ru":"Где разрешено движение задним ходом?"},"a":[{"uk":"На перехресті, якщо немає інших транспортних засобів","ru":"На перекрёстке, если нет других транспортных средств","w":{"uk":"Задній хід на перехресті заборонено завжди, навіть коли воно порожнє.","ru":"Задний ход на перекрёстке запрещён всегда, даже когда он пустой."}},{"uk":"На мосту, якщо водій пропустив поворот","ru":"На мосту, если водитель пропустил поворот","w":{"uk":"На мостах задній хід заборонено. Пропустили поворот — їдьте до місця, де можна безпечно розвернутися.","ru":"На мостах задний ход запрещён. Пропустили поворот — езжайте до места, где можно безопасно развернуться."}},{"uk":"На дорозі з одностороннім рухом, якщо інакше під'їхати до об'єкта неможливо","ru":"На дороге с односторонним движением, если иначе подъехать к объекту невозможно"}],"c":2,"e":{"uk":"Рух заднім ходом заборонено на автомагістралях, дорогах для автомобілів, переїздах, пішохідних переходах, перехрестях, мостах, естакадах, у тунелях і на ділянках з обмеженою оглядовістю. На дорозі з одностороннім рухом він дозволений, якщо інакше під'їхати неможливо і це безпечно.","ru":"Движение задним ходом запрещено на автомагистралях, дорогах для автомобилей, переездах, пешеходных переходах, перекрёстках, мостах, эстакадах, в тоннелях и на участках с ограниченной обзорностью. На дороге с односторонним движением оно разрешено, если иначе подъехать невозможно и это безопасно."},"ref":["10.10"],"id":"q11098d50a"},{"t":"s10","q":{"uk":"Перед з'їздом з дороги є смуга гальмування. Де слід знижувати швидкість?","ru":"Перед съездом с дороги есть полоса торможения. Где следует снижать скорость?"},"a":[{"uk":"Лише на смузі гальмування, своєчасно на неї перестроївшись","ru":"Только на полосе торможения, своевременно на неё перестроившись"},{"uk":"На основній смузі перед смугою гальмування","ru":"На основной полосе перед полосой торможения","w":{"uk":"Гальмування на основній смузі створює перешкоду тим, хто їде позаду. Для цього й є смуга гальмування.","ru":"Торможение на основной полосе создаёт помеху едущим сзади. Для этого и есть полоса торможения."}},{"uk":"Байдуже, де саме","ru":"Неважно, где именно","w":{"uk":"Не байдуже: Правила прямо вимагають знижувати швидкість лише на смузі гальмування.","ru":"Не всё равно: Правила прямо требуют снижать скорость только на полосе торможения."}}],"c":0,"e":{"uk":"Якщо є смуга гальмування, водій своєчасно перестроюється на неї і знижує швидкість тільки на ній, щоб не заважати потоку.","ru":"Если есть полоса торможения, водитель своевременно перестраивается на неё и снижает скорость только на ней, чтобы не мешать потоку."},"ref":["10.8"],"id":"q9c3d0e51f"},{"t":"s10","q":{"uk":"Водій виїжджає на дорогу смугою розгону. Хто має перевагу?","ru":"Водитель выезжает на дорогу по полосе разгона. У кого преимущество?"},"a":[{"uk":"Водій на смузі розгону","ru":"Водитель на полосе разгона","w":{"uk":"Смуга розгону не дає переваги: з неї вливаються в потік, поступаючись тим, хто вже їде дорогою.","ru":"Полоса разгона не даёт преимущества: с неё вливаются в поток, уступая тем, кто уже едет по дороге."}},{"uk":"Транспортні засоби, що рухаються цією дорогою","ru":"Транспортные средства, движущиеся по этой дороге"}],"c":1,"e":{"uk":"Рухаючись смугою розгону, водій вливається в потік, даючи дорогу транспортним засобам, що рухаються дорогою.","ru":"Двигаясь по полосе разгона, водитель вливается в поток, уступая дорогу транспортным средствам, движущимся по дороге."},"ref":["10.8"],"id":"qb88e2c3c5"},{"t":"s10","q":{"uk":"Траєкторії руху двох автомобілів перетинаються, а черговість проїзду Правилами не обумовлена. Хто поступається?","ru":"Траектории движения двух автомобилей пересекаются, а очерёдность проезда Правилами не оговорена. Кто уступает?"},"a":[{"uk":"Водій, до якого інший автомобіль наближається з правого боку","ru":"Водитель, к которому другой автомобиль приближается справа"},{"uk":"Водій, до якого інший автомобіль наближається з лівого боку","ru":"Водитель, к которому другой автомобиль приближается слева","w":{"uk":"Навпаки: поступається той, до кого інший наближається справа (правило «перешкода праворуч»).","ru":"Наоборот: уступает тот, к кому другой приближается справа (правило «помеха справа»)."}},{"uk":"Водій, який рухається повільніше","ru":"Водитель, который движется медленнее","w":{"uk":"Швидкість не визначає черговість. Діє правило «перешкода праворуч».","ru":"Скорость не определяет очерёдность. Действует правило «помеха справа»."}}],"c":0,"e":{"uk":"Якщо траєкторії перетинаються, а черговість не визначено Правилами (наприклад, на парковці), діє правило «перешкода праворуч».","ru":"Если траектории пересекаются, а очерёдность не определена Правилами (например, на парковке), действует правило «помеха справа»."},"ref":["10.11"],"id":"q1597e588b"},{"t":"s10","q":{"uk":"Водій повертає ліворуч поза перехрестям, посередині дороги — трамвайна колія. Кому він дає дорогу?","ru":"Водитель поворачивает налево вне перекрёстка, посередине дороги — трамвайные пути. Кому он уступает дорогу?"},"a":[{"uk":"Лише зустрічним автомобілям","ru":"Только встречным автомобилям","w":{"uk":"Не лише: якщо посередині трамвайна колія, треба пропустити й трамвай.","ru":"Не только: если посередине трамвайные пути, нужно пропустить и трамвай."}},{"uk":"Зустрічним транспортним засобам і трамваю","ru":"Встречным транспортным средствам и трамваю"},{"uk":"Нікому, бо він на головній дорозі","ru":"Никому, так как он на главной дороге","w":{"uk":"Поворот ліворуч поза перехрестям вимагає пропустити зустрічних і трамвай незалежно від того, якою дорогою ви їдете.","ru":"Поворот налево вне перекрёстка требует пропустить встречных и трамвай независимо от того, по какой дороге вы едете."}}],"c":1,"e":{"uk":"Повертаючи ліворуч або розвертаючись поза перехрестям, водій дає дорогу зустрічним транспортним засобам, а за наявності трамвайної колії посередині — і трамваю.","ru":"Поворачивая налево или разворачиваясь вне перекрёстка, водитель уступает дорогу встречным транспортным средствам, а при наличии трамвайных путей посередине — и трамваю."},"ref":["10.4"],"id":"q4339e47ca"},{"t":"s10","q":{"uk":"З якої смуги можна виїхати з перехрестя з круговим рухом, якщо напрямок не визначено знаками чи розміткою?","ru":"С какой полосы можно выехать с перекрёстка с круговым движением, если направление не определено знаками или разметкой?"},"a":[{"uk":"Лише з крайньої правої","ru":"Только с крайней правой","w":{"uk":"Не обов'язково: з кільця можна виїхати з будь-якої смуги, якщо знаки не кажуть інакше і ви не заважаєте тим, хто праворуч.","ru":"Не обязательно: с кольца можно выехать с любой полосы, если знаки не говорят иное и вы не мешаете тем, кто справа."}},{"uk":"З будь-якої смуги, якщо це не заважає транспортним засобам праворуч","ru":"С любой полосы, если это не мешает транспортным средствам справа"},{"uk":"Лише з крайньої лівої","ru":"Только с крайней левой","w":{"uk":"Обмеження «лише з лівої» немає: виїхати можна з будь-якої смуги, не заважаючи тим, хто праворуч.","ru":"Ограничения «только с левой» нет: выехать можно с любой полосы, не мешая тем, кто справа."}}],"c":1,"e":{"uk":"Виїзд з кільця можливий з будь-якої смуги, якщо напрямок не визначено знаками чи розміткою і це не створить перешкод попутним транспортним засобам праворуч.","ru":"Выезд с кольца возможен с любой полосы, если направление не определено знаками или разметкой и это не создаст помех попутным транспортным средствам справа."},"ref":["10.5"],"id":"q589d49eae"},{"t":"s11","q":{"uk":"Якою смугою має рухатися легковий автомобіль на дорозі з двома смугами в одному напрямку, якщо обидві вільні?","ru":"По какой полосе должен двигаться легковой автомобиль на дороге с двумя полосами в одном направлении, если обе свободны?"},"a":[{"uk":"Якнайближче до правого краю, тобто правою смугою","ru":"Как можно ближе к правому краю, то есть по правой полосе"},{"uk":"Будь-якою на вибір водія","ru":"Любой по выбору водителя","w":{"uk":"Не на вибір: Правила вимагають триматися якнайближче до правого краю, ліва смуга — для випередження і поворотів.","ru":"Не на выбор: Правила требуют держаться как можно ближе к правому краю, левая полоса — для опережения и поворотов."}},{"uk":"Лівою, бо вона швидша","ru":"Левой, так как она быстрее","w":{"uk":"Ліва смуга — не «швидка» за Правилами. Нею користуються для випередження, повороту ліворуч чи розвороту.","ru":"Левая полоса — не «быстрая» по Правилам. Ею пользуются для опережения, поворота налево или разворота."}}],"c":0,"e":{"uk":"На дорогах з двома і більше смугами в одному напрямку нерейкові транспортні засоби рухаються якнайближче до правого краю. Ліву смугу використовують для випередження, об'їзду чи перестроювання перед поворотом ліворуч або розворотом, а також коли праві смуги зайняті.","ru":"На дорогах с двумя и более полосами в одном направлении нерельсовые транспортные средства движутся как можно ближе к правому краю. Левую полосу используют для опережения, объезда или перестроения перед поворотом налево либо разворотом, а также когда правые полосы заняты."},"ref":["11.2","11.5"],"id":"q541400072"},{"t":"s11","q":{"uk":"Дорога з двостороннім рухом має по дві смуги в кожному напрямку, розмітки немає. Чи можна виїхати на зустрічний бік для обгону?","ru":"Дорога с двусторонним движением имеет по две полосы в каждом направлении, разметки нет. Можно ли выехать на встречную сторону для обгона?"},"a":[{"uk":"Так, якщо зустрічна смуга вільна","ru":"Да, если встречная полоса свободна","w":{"uk":"Вільна зустрічна не дає права: на дорогах з двома і більше смугами в кожному напрямку виїжджати на зустрічний бік заборонено.","ru":"Свободная встречная не даёт права: на дорогах с двумя и более полосами в каждом направлении выезжать на встречную сторону запрещено."}},{"uk":"Ні, це заборонено","ru":"Нет, это запрещено"},{"uk":"Так, але лише поза населеним пунктом","ru":"Да, но только вне населённого пункта","w":{"uk":"Заборона діє і в місті, і за містом.","ru":"Запрет действует и в городе, и за городом."}}],"c":1,"e":{"uk":"На дорогах з двостороннім рухом, які мають щонайменше дві смуги для руху в одному напрямку, виїжджати на бік дороги, призначений для зустрічного руху, заборонено.","ru":"На дорогах с двусторонним движением, имеющих не менее двух полос для движения в одном направлении, выезжать на сторону дороги, предназначенную для встречного движения, запрещено."},"ref":["11.4"],"id":"qa7b23d917"},{"t":"s11","q":{"uk":"Для чого вантажному автомобілю масою понад 3,5 т дозволено займати крайню ліву смугу на дорозі з трьома смугами в одному напрямку?","ru":"Для чего грузовому автомобилю массой более 3,5 т разрешено занимать крайнюю левую полосу на дороге с тремя полосами в одном направлении?"},"a":[{"uk":"Для випередження","ru":"Для опережения","w":{"uk":"Ні: вантажівкам понад 3,5 т ліва смуга таких доріг дозволена лише для повороту ліворуч і розвороту, не для випередження.","ru":"Нет: грузовикам более 3,5 т левая полоса таких дорог разрешена только для поворота налево и разворота, не для опережения."}},{"uk":"Лише для повороту ліворуч і розвороту","ru":"Только для поворота налево и разворота"},{"uk":"У будь-якому разі, якщо праві смуги зайняті","ru":"В любом случае, если правые полосы заняты","w":{"uk":"Зайнятість правих смуг не має значення для вантажівок понад 3,5 т: ліворуч — лише для повороту чи розвороту.","ru":"Занятость правых полос не имеет значения для грузовиков более 3,5 т: налево — только для поворота или разворота."}}],"c":1,"e":{"uk":"На дорогах з трьома і більше смугами в одному напрямку вантажівки понад 3,5 т, трактори та самохідні машини виїжджають на крайню ліву смугу лише для повороту ліворуч і розвороту.","ru":"На дорогах с тремя и более полосами в одном направлении грузовики более 3,5 т, тракторы и самоходные машины выезжают на крайнюю левую полосу только для поворота налево и разворота."},"ref":["11.6"],"id":"q09a1d5e64"},{"t":"s11","q":{"uk":"Чи можна рухатися трамвайною колією зустрічного напрямку?","ru":"Можно ли двигаться по трамвайным путям встречного направления?"},"a":[{"uk":"Так, якщо немає трамвая","ru":"Да, если нет трамвая","w":{"uk":"Навіть без трамвая їзда зустрічною колією заборонена.","ru":"Даже без трамвая езда по встречным путям запрещена."}},{"uk":"Так, для об'їзду перешкоди","ru":"Да, для объезда препятствия","w":{"uk":"Об'їжджати перешкоду зустрічною колією теж заборонено.","ru":"Объезжать препятствие по встречным путям тоже запрещено."}},{"uk":"Ні, це заборонено","ru":"Нет, это запрещено"}],"c":2,"e":{"uk":"Виїжджати на трамвайну колію зустрічного напрямку, відокремлені від проїзної частини трамвайні колії та розділювальну смугу заборонено.","ru":"Выезжать на трамвайные пути встречного направления, обособленные от проезжей части трамвайные пути и разделительную полосу запрещено."},"ref":["11.9"],"id":"q7006d4e84"},{"t":"s11","q":{"uk":"Звідки треба виконувати поворот ліворуч, якщо посередині дороги на одному рівні з проїзною частиною проходить трамвайна колія попутного напрямку, а знаків і розмітки немає?","ru":"Откуда нужно выполнять поворот налево, если посередине дороги на одном уровне с проезжей частью проходят трамвайные пути попутного направления, а знаков и разметки нет?"},"a":[{"uk":"З трамвайної колії попутного напрямку, не заважаючи трамваю","ru":"С трамвайных путей попутного направления, не мешая трамваю"},{"uk":"З крайньої лівої смуги проїзної частини поруч із коліями","ru":"С крайней левой полосы проезжей части рядом с путями","w":{"uk":"Якщо посередині трамвайна колія попутного напрямку на рівні дороги, поворот ліворуч виконують саме з неї.","ru":"Если посередине трамвайные пути попутного направления на уровне дороги, поворот налево выполняют именно с них."}},{"uk":"З правої смуги","ru":"С правой полосы","w":{"uk":"З правої смуги ліворуч повертати не можна — ви перетнете шлях іншим. Займіть колію попутного напрямку.","ru":"С правой полосы налево поворачивать нельзя — вы пересечёте путь другим. Займите пути попутного направления."}}],"c":0,"e":{"uk":"Поворот ліворуч і розворот виконують з трамвайної колії попутного напрямку, розташованої на одному рівні з проїзною частиною, якщо знаки {s:5.16}, {s:5.18} або розмітка {m:1.18} не встановлюють іншого порядку. Трамваю заважати не можна.","ru":"Поворот налево и разворот выполняют с трамвайных путей попутного направления, расположенных на одном уровне с проезжей частью, если знаки {s:5.16}, {s:5.18} или разметка {m:1.18} не устанавливают иного порядка. Трамваю мешать нельзя."},"ref":["11.8"],"id":"q410e0f616"},{"t":"s11","q":{"uk":"Чи можна рухатися, займаючи одночасно дві смуги, розділені переривчастою лінією?","ru":"Можно ли двигаться, занимая одновременно две полосы, разделённые прерывистой линией?"},"a":[{"uk":"Так, якщо інших автомобілів немає","ru":"Да, если других автомобилей нет","w":{"uk":"Відсутність інших автомобілів не дає права займати дві смуги: це заборонено завжди.","ru":"Отсутствие других автомобилей не даёт права занимать две полосы: это запрещено всегда."}},{"uk":"Ні. Наїжджати на переривчасту лінію можна лише під час перестроювання","ru":"Нет. Наезжать на прерывистую линию можно только при перестроении"},{"uk":"Так, у темну пору доби","ru":"Да, в тёмное время суток","w":{"uk":"Темна пора нічого не змінює: їхати по двох смугах одночасно не можна.","ru":"Тёмное время ничего не меняет: ехать по двум полосам одновременно нельзя."}}],"c":1,"e":{"uk":"Рухатися, займаючи одночасно дві смуги, заборонено. Наїжджати на переривчасті лінії розмітки дозволено лише під час перестроювання.","ru":"Двигаться, занимая одновременно две полосы, запрещено. Наезжать на прерывистые линии разметки разрешено только при перестроении."},"ref":["11.10"],"id":"qe17e833b0"},{"t":"s11","q":{"uk":"Рух інтенсивний. У яких випадках можна змінювати смугу?","ru":"Движение интенсивное. В каких случаях можно менять полосу?"},"a":[{"uk":"У будь-яких, якщо увімкнено покажчик повороту","ru":"В любых, если включён указатель поворота","w":{"uk":"Покажчик не дає права на «шашки» в щільному потоці: смугу змінюють лише для об'їзду, повороту, розвороту чи зупинки.","ru":"Указатель не даёт права на «шашки» в плотном потоке: полосу меняют только для объезда, поворота, разворота или остановки."}},{"uk":"Лише для об'їзду перешкоди, повороту, розвороту або зупинки","ru":"Только для объезда препятствия, поворота, разворота или остановки"},{"uk":"Лише для обгону","ru":"Только для обгона","w":{"uk":"Обгону серед дозволених причин немає. Лише об'їзд, поворот, розворот чи зупинка.","ru":"Обгона среди разрешённых причин нет. Только объезд, поворот, разворот или остановка."}}],"c":1,"e":{"uk":"При інтенсивному русі змінювати смугу дозволено лише для об'їзду перешкоди, повороту, розвороту або зупинки.","ru":"При интенсивном движении менять полосу разрешено только для объезда препятствия, поворота, разворота или остановки."},"ref":["11.11"],"id":"q593379c9e"},{"t":"s11","q":{"uk":"Як мають рухатися велосипедисти по проїзній частині?","ru":"Как должны двигаться велосипедисты по проезжей части?"},"a":[{"uk":"Не більше ніж у два ряди","ru":"Не более чем в два ряда","w":{"uk":"У два ряди велосипеди можна лише ставити на стоянку. Рухатися — лише в один ряд.","ru":"В два ряда велосипеды можно только ставить на стоянку. Двигаться — только в один ряд."}},{"uk":"В один ряд по крайній правій смузі якомога правіше","ru":"В один ряд по крайней правой полосе как можно правее"},{"uk":"Будь-якою смугою","ru":"По любой полосе","w":{"uk":"Велосипедисти рухаються лише крайньою правою смугою, якомога правіше.","ru":"Велосипедисты движутся только по крайней правой полосе, как можно правее."}}],"c":1,"e":{"uk":"Велосипеди, мопеди, гужові вози та вершники рухаються проїзною частиною лише в один ряд по крайній правій смузі якомога правіше. Рух узбіччям дозволено, якщо це не заважає пішоходам.","ru":"Велосипеды, мопеды, гужевые повозки и всадники движутся по проезжей части только в один ряд по крайней правой полосе как можно правее. Движение по обочине разрешено, если это не мешает пешеходам."},"ref":["11.14"],"id":"q8f647d731"},{"t":"s11","q":{"uk":"На дорозі з однією смугою в кожному напрямку немає суцільної розмітки. Для чого можна виїхати на смугу зустрічного руху?","ru":"На дороге с одной полосой в каждом направлении нет сплошной разметки. Для чего можно выехать на полосу встречного движения?"},"a":[{"uk":"Для обгону, об'їзду перешкоди, а в населених пунктах — для зупинки чи стоянки біля лівого краю в дозволених випадках","ru":"Для обгона, объезда препятствия, а в населённых пунктах — для остановки или стоянки у левого края в разрешённых случаях"},{"uk":"Для руху в заторі","ru":"Для движения в заторе","w":{"uk":"Затор не є підставою виїжджати на зустрічну. Дозволено лише для обгону, об'їзду і зупинки біля лівого краю в місті.","ru":"Затор не является основанием выезжать на встречную. Разрешено только для обгона, объезда и остановки у левого края в городе."}},{"uk":"Лише для розвороту","ru":"Только для разворота","w":{"uk":"Не лише: на зустрічну можна виїхати також для обгону, об'їзду перешкоди чи зупинки біля лівого краю в місті.","ru":"Не только: на встречную можно выехать также для обгона, объезда препятствия или остановки у левого края в городе."}}],"c":0,"e":{"uk":"Виїзд на смугу зустрічного руху можливий лише для обгону, об'їзду перешкоди або зупинки чи стоянки біля лівого краю в населених пунктах у дозволених випадках. Зустрічні водії мають перевагу.","ru":"Выезд на полосу встречного движения возможен только для обгона, объезда препятствия или остановки либо стоянки у левого края в населённых пунктах в разрешённых случаях. Встречные водители имеют преимущество."},"ref":["11.3"],"id":"q085ad07c4"},{"t":"s12","q":{"uk":"З якою максимальною швидкістю дозволено рух легкового автомобіля в населеному пункті, якщо знаки не встановлюють інших обмежень?","ru":"С какой максимальной скоростью разрешено движение легкового автомобиля в населённом пункте, если знаки не устанавливают иных ограничений?"},"a":[{"uk":"40 км/год","ru":"40 км/ч","w":{"uk":"40 км/год — не загальне обмеження. У населеному пункті дозволено до 50 км/год.","ru":"40 км/ч — не общее ограничение. В населённом пункте разрешено до 50 км/ч."}},{"uk":"50 км/год","ru":"50 км/ч"},{"uk":"60 км/год","ru":"60 км/ч","w":{"uk":"60 км/год — порушення: у населеному пункті максимум 50 км/год, якщо знаки не дозволяють більше.","ru":"60 км/ч — нарушение: в населённом пункте максимум 50 км/ч, если знаки не разрешают больше."}},{"uk":"70 км/год","ru":"70 км/ч","w":{"uk":"70 км/год — це обмеження для новачків за містом. У місті — 50 км/год.","ru":"70 км/ч — это ограничение для новичков за городом. В городе — 50 км/ч."}}],"c":1,"e":{"uk":"У населених пунктах рух транспортних засобів дозволено зі швидкістю не більше 50 км/год.","ru":"В населённых пунктах движение транспортных средств разрешено со скоростью не более 50 км/ч."},"ref":["12.4"],"id":"q7777014f1"},{"t":"s12","q":{"uk":"Яка максимальна швидкість у житловій та пішохідній зоні?","ru":"Какая максимальная скорость в жилой и пешеходной зоне?"},"a":[{"uk":"20 км/год","ru":"20 км/ч"},{"uk":"10 км/год","ru":"10 км/ч","w":{"uk":"Правила дозволяють у житловій зоні до 20 км/год, а не до 10.","ru":"Правила разрешают в жилой зоне до 20 км/ч, а не до 10."}},{"uk":"30 км/год","ru":"30 км/ч","w":{"uk":"30 км/год — забагато для житлової зони: там до 20 км/год.","ru":"30 км/ч — слишком много для жилой зоны: там до 20 км/ч."}},{"uk":"50 км/год","ru":"50 км/ч","w":{"uk":"50 км/год — загальне обмеження в місті. Для житлової та пішохідної зони — 20 км/год.","ru":"50 км/ч — общее ограничение в городе. Для жилой и пешеходной зоны — 20 км/ч."}}],"img":{"sign":"5.34"},"c":0,"e":{"uk":"У житлових і пішохідних зонах швидкість не повинна перевищувати 20 км/год.","ru":"В жилых и пешеходных зонах скорость не должна превышать 20 км/ч."},"ref":["12.5"],"id":"qd625e7bed"},{"t":"s12","q":{"uk":"З якою максимальною швидкістю може рухатися легковий автомобіль поза населеним пунктом на звичайній дорозі без розділювальної смуги? Стаж водія — понад 2 роки.","ru":"С какой максимальной скоростью может двигаться легковой автомобиль вне населённого пункта на обычной дороге без разделительной полосы? Стаж водителя — более 2 лет."},"a":[{"uk":"70 км/год","ru":"70 км/ч","w":{"uk":"70 км/год — обмеження для водіїв зі стажем до 2 років. Досвідчений водій може їхати до 90.","ru":"70 км/ч — ограничение для водителей со стажем до 2 лет. Опытный водитель может ехать до 90."}},{"uk":"90 км/год","ru":"90 км/ч"},{"uk":"110 км/год","ru":"110 км/ч","w":{"uk":"110 км/год дозволено лише на дорозі з розділювальною смугою. На звичайній — 90.","ru":"110 км/ч разрешено только на дороге с разделительной полосой. На обычной — 90."}},{"uk":"130 км/год","ru":"130 км/ч","w":{"uk":"130 км/год — лише на автомагістралі (знак 5.1).","ru":"130 км/ч — только на автомагистрали (знак 5.1)."}}],"c":1,"e":{"uk":"Поза населеними пунктами: на автомагістралі ({s:5.1}) — до 130 км/год, на дорозі з розділювальною смугою — до 110 км/год, на інших дорогах — до 90 км/год.","ru":"Вне населённых пунктов: на автомагистрали ({s:5.1}) — до 130 км/ч, на дороге с разделительной полосой — до 110 км/ч, на остальных дорогах — до 90 км/ч."},"ref":["12.6"],"id":"qf4e283c2d"},{"t":"s12","q":{"uk":"Яка максимальна швидкість легкового автомобіля на автомагістралі?","ru":"Какая максимальная скорость легкового автомобиля на автомагистрали?"},"a":[{"uk":"110 км/год","ru":"110 км/ч","w":{"uk":"110 км/год — для доріг з розділювальною смугою. На автомагістралі — до 130.","ru":"110 км/ч — для дорог с разделительной полосой. На автомагистрали — до 130."}},{"uk":"120 км/год","ru":"120 км/ч","w":{"uk":"Такої норми в Правилах немає: на автомагістралі — до 130 км/год.","ru":"Такой нормы в Правилах нет: на автомагистрали — до 130 км/ч."}},{"uk":"130 км/год","ru":"130 км/ч"},{"uk":"150 км/год","ru":"150 км/ч","w":{"uk":"150 км/год — порушення: максимум на автомагістралі 130 км/год.","ru":"150 км/ч — нарушение: максимум на автомагистрали 130 км/ч."}}],"img":{"sign":"5.1"},"c":2,"e":{"uk":"На автомобільній дорозі, позначеній знаком {s:5.1} «Автомагістраль», — не більше 130 км/год (для водіїв зі стажем до 2 років — не більше 70 км/год).","ru":"На автомобильной дороге, обозначенной знаком {s:5.1} «Автомагистраль», — не более 130 км/ч (для водителей со стажем до 2 лет — не более 70 км/ч)."},"ref":["12.6"],"id":"q07377be82"},{"t":"s12","q":{"uk":"Яка максимальна швидкість легкового автомобіля поза населеним пунктом на дорозі з окремими проїзними частинами, розділеними розділювальною смугою?","ru":"Какая максимальная скорость легкового автомобиля вне населённого пункта на дороге с отдельными проезжими частями, разделёнными разделительной полосой?"},"a":[{"uk":"90 км/год","ru":"90 км/ч","w":{"uk":"90 км/год — для звичайних доріг. Якщо є розділювальна смуга — до 110.","ru":"90 км/ч — для обычных дорог. Если есть разделительная полоса — до 110."}},{"uk":"110 км/год","ru":"110 км/ч"},{"uk":"130 км/год","ru":"130 км/ч","w":{"uk":"130 км/год — лише на автомагістралі. На дорозі з розділювальною смугою — 110.","ru":"130 км/ч — только на автомагистрали. На дороге с разделительной полосой — 110."}}],"c":1,"e":{"uk":"На дорозі з окремими проїзними частинами, відокремленими розділювальною смугою, дозволено до 110 км/год.","ru":"На дороге с отдельными проезжими частями, отделёнными разделительной полосой, разрешено до 110 км/ч."},"ref":["12.6"],"id":"q414b9311c"},{"t":"s12","q":{"uk":"З якою максимальною швидкістю поза населеним пунктом може рухатися водій зі стажем менше 2 років?","ru":"С какой максимальной скоростью вне населённого пункта может двигаться водитель со стажем менее 2 лет?"},"a":[{"uk":"50 км/год","ru":"50 км/ч","w":{"uk":"50 км/год — це міське обмеження. Новачкам поза містом — до 70.","ru":"50 км/ч — это городское ограничение. Новичкам за городом — до 70."}},{"uk":"60 км/год","ru":"60 км/ч","w":{"uk":"60 км/год — обмеження для мопедів і вантажівок з людьми в кузові. Новачкам — 70.","ru":"60 км/ч — ограничение для мопедов и грузовиков с людьми в кузове. Новичкам — 70."}},{"uk":"70 км/год","ru":"70 км/ч"},{"uk":"90 км/год","ru":"90 км/ч","w":{"uk":"90 км/год дозволено лише водіям зі стажем понад 2 роки.","ru":"90 км/ч разрешено только водителям со стажем более 2 лет."}}],"c":2,"e":{"uk":"Транспортним засобам, якими керують водії зі стажем до 2 років, поза населеними пунктами дозволено не більше 70 км/год на будь-якій дорозі.","ru":"Транспортным средствам, которыми управляют водители со стажем до 2 лет, вне населённых пунктов разрешено не более 70 км/ч на любой дороге."},"ref":["12.6"],"id":"qf4f6ec38a"},{"t":"s12","q":{"uk":"Яка максимальна швидкість легкового автомобіля з причепом поза населеним пунктом?","ru":"Какая максимальная скорость легкового автомобиля с прицепом вне населённого пункта?"},"a":[{"uk":"80 км/год","ru":"80 км/ч"},{"uk":"70 км/год","ru":"70 км/ч","w":{"uk":"70 км/год — обмеження для новачків. З причепом — до 80.","ru":"70 км/ч — ограничение для новичков. С прицепом — до 80."}},{"uk":"90 км/год","ru":"90 км/ч","w":{"uk":"90 км/год — для легкових без причепа. З причепом — до 80.","ru":"90 км/ч — для легковых без прицепа. С прицепом — до 80."}}],"c":0,"e":{"uk":"Легковим автомобілям з причепом, мотоциклам і автобусам з організованими групами дітей поза населеними пунктами дозволено не більше 80 км/год.","ru":"Легковым автомобилям с прицепом, мотоциклам и автобусам с организованными группами детей вне населённых пунктов разрешено не более 80 км/ч."},"ref":["12.6"],"id":"q84772d6d8"},{"t":"s12","q":{"uk":"Яка максимальна швидкість під час буксирування?","ru":"Какая максимальная скорость при буксировке?"},"a":[{"uk":"40 км/год","ru":"40 км/ч","w":{"uk":"Правила дозволяють під час буксирування до 50 км/год.","ru":"Правила разрешают при буксировке до 50 км/ч."}},{"uk":"50 км/год","ru":"50 км/ч"},{"uk":"60 км/год","ru":"60 км/ч","w":{"uk":"60 км/год — забагато: буксирувати можна не швидше 50 км/год.","ru":"60 км/ч — слишком много: буксировать можно не быстрее 50 км/ч."}},{"uk":"70 км/год","ru":"70 км/ч","w":{"uk":"70 км/год — порушення: під час буксирування максимум 50 км/год.","ru":"70 км/ч — нарушение: при буксировке максимум 50 км/ч."}}],"c":1,"e":{"uk":"Під час буксирування швидкість не повинна перевищувати 50 км/год.","ru":"При буксировке скорость не должна превышать 50 км/ч."},"ref":["12.7"],"id":"q0b6307c33"},{"t":"s12","q":{"uk":"Як вибирати швидкість у темну пору доби та за недостатньої видимості?","ru":"Как выбирать скорость в тёмное время суток и при недостаточной видимости?"},"a":[{"uk":"Не більше 40 км/год","ru":"Не более 40 км/ч","w":{"uk":"Правила не задають числа: швидкість залежить від видимості — треба встигнути зупинитися в її межах.","ru":"Правила не задают числа: скорость зависит от видимости — нужно успеть остановиться в её пределах."}},{"uk":"Так, щоб можна було зупинитися в межах видимості дороги","ru":"Так, чтобы можно было остановиться в пределах видимости дороги"},{"uk":"На 20 км/год менше від дозволеної","ru":"На 20 км/ч меньше разрешённой","w":{"uk":"Фіксованої знижки немає: вирішує видимість дороги.","ru":"Фиксированной скидки нет: решает видимость дороги."}}],"c":1,"e":{"uk":"У темряві та за недостатньої видимості швидкість має бути такою, щоб водій міг зупинити транспортний засіб у межах видимості дороги.","ru":"В темноте и при недостаточной видимости скорость должна быть такой, чтобы водитель мог остановить транспортное средство в пределах видимости дороги."},"ref":["12.2"],"id":"qd5edef0a6"},{"t":"s12","q":{"uk":"Водій помітив перешкоду на своїй смузі. Що він зобов'язаний зробити?","ru":"Водитель заметил препятствие на своей полосе. Что он обязан сделать?"},"a":[{"uk":"Подати звуковий сигнал і продовжувати рух","ru":"Подать звуковой сигнал и продолжать движение","w":{"uk":"Сигнал не прибирає перешкоду. Водій зобов'язаний гальмувати аж до зупинки або безпечно об'їхати.","ru":"Сигнал не убирает препятствие. Водитель обязан тормозить вплоть до остановки или безопасно объехать."}},{"uk":"Негайно знизити швидкість аж до зупинки або безпечно об'їхати перешкоду","ru":"Немедленно снизить скорость вплоть до остановки или безопасно объехать препятствие"},{"uk":"Обов'язково перестроїтися на іншу смугу","ru":"Обязательно перестроиться на другую полосу","w":{"uk":"Не обов'язково: якщо об'їзд небезпечний, треба гальмувати аж до зупинки.","ru":"Не обязательно: если объезд опасен, нужно тормозить вплоть до остановки."}}],"c":1,"e":{"uk":"Виявивши небезпеку чи перешкоду, водій негайно вживає заходів для зменшення швидкості аж до зупинки або для безпечного для інших об'їзду перешкоди.","ru":"Обнаружив опасность или препятствие, водитель немедленно принимает меры для снижения скорости вплоть до остановки или для безопасного для других объезда препятствия."},"ref":["12.3"],"id":"q8b02e87d5"},{"t":"s12","q":{"uk":"Коли дозволено різко гальмувати?","ru":"Когда разрешено резко тормозить?"},"a":[{"uk":"Коли за вами немає інших транспортних засобів","ru":"Когда за вами нет других транспортных средств","w":{"uk":"Навіть без машин позаду різке гальмування дозволене лише для запобігання ДТП.","ru":"Даже без машин сзади резкое торможение разрешено только для предотвращения ДТП."}},{"uk":"Лише коли без цього неможливо запобігти ДТП","ru":"Только когда без этого невозможно предотвратить ДТП"},{"uk":"Перед кожним пішохідним переходом","ru":"Перед каждым пешеходным переходом","w":{"uk":"Перед переходом знижують швидкість завчасно і плавно, а не гальмують різко.","ru":"Перед переходом снижают скорость заранее и плавно, а не тормозят резко."}}],"c":1,"e":{"uk":"Водієві заборонено різко гальмувати, крім випадків, коли без цього неможливо запобігти дорожньо-транспортній пригоді.","ru":"Водителю запрещено резко тормозить, кроме случаев, когда без этого невозможно предотвратить дорожно-транспортное происшествие."},"ref":["12.9"],"id":"q4b7343641"},{"t":"s12","q":{"uk":"Ви проїжджаєте населений пункт, позначений цим знаком (синій фон). З якою швидкістю можна рухатися легковим автомобілем?","ru":"Вы проезжаете населённый пункт, обозначенный этим знаком (синий фон). С какой скоростью можно двигаться на легковом автомобиле?"},"a":[{"uk":"Не більше 50 км/год, як у будь-якому населеному пункті","ru":"Не более 50 км/ч, как в любом населённом пункте","w":{"uk":"Знак 5.51 (синій) лише вказує назву: правила для населених пунктів, зокрема 50 км/год, тут не діють.","ru":"Знак 5.51 (синий) только указывает название: правила для населённых пунктов, в том числе 50 км/ч, здесь не действуют."}},{"uk":"Як поза населеним пунктом (на звичайній дорозі — до 90 км/год)","ru":"Как вне населённого пункта (на обычной дороге — до 90 км/ч)"},{"uk":"Не більше 60 км/год","ru":"Не более 60 км/ч","w":{"uk":"Такого обмеження немає: у населеному пункті зі знаком 5.51 діють швидкості як за містом.","ru":"Такого ограничения нет: в населённом пункте со знаком 5.51 действуют скорости как за городом."}}],"img":{"sign":"5.51"},"c":1,"e":{"uk":"На дорогах, що проходять через населені пункти, позначені знаком {s:5.51}, діють обмеження швидкості як поза населеними пунктами.","ru":"На дорогах, проходящих через населённые пункты, обозначенные знаком {s:5.51}, действуют ограничения скорости как вне населённых пунктов."},"ref":["12.6"],"id":"qa8427bd4e"},{"t":"s12","q":{"uk":"Що водієві заборонено робити зі швидкістю?","ru":"Что водителю запрещено делать со скоростью?"},"a":[{"uk":"Рухатися повільніше за потік","ru":"Двигаться медленнее потока","w":{"uk":"Їхати трохи повільніше за потік не заборонено. Заборонено без потреби плентатися, заважаючи іншим.","ru":"Ехать немного медленнее потока не запрещено. Запрещено без необходимости плестись, мешая другим."}},{"uk":"Без потреби рухатися з дуже малою швидкістю, заважаючи іншим","ru":"Без необходимости двигаться с очень малой скоростью, мешая другим"},{"uk":"Рухатися з максимально дозволеною швидкістю","ru":"Двигаться с максимально разрешённой скоростью","w":{"uk":"Їхати з максимальною дозволеною швидкістю можна, якщо це безпечно за умовами руху.","ru":"Ехать с максимальной разрешённой скоростью можно, если это безопасно по условиям движения."}}],"c":1,"e":{"uk":"Водієві заборонено перешкоджати іншим транспортним засобам, рухаючись без потреби з дуже малою швидкістю, а також перевищувати максимальну швидкість, визначену технічною характеристикою транспортного засобу.","ru":"Водителю запрещено мешать другим транспортным средствам, двигаясь без необходимости с очень малой скоростью, а также превышать максимальную скорость, определённую технической характеристикой транспортного средства."},"ref":["12.9"],"id":"q0c8ecfd24"},{"t":"s13","q":{"uk":"Зустрічний роз'їзд утруднений, на вашій смузі стоїть перешкода. Хто повинен дати дорогу?","ru":"Встречный разъезд затруднён, на вашей полосе стоит препятствие. Кто должен уступить дорогу?"},"a":[{"uk":"Ви, бо перешкода на вашій смузі","ru":"Вы, так как препятствие на вашей полосе"},{"uk":"Зустрічний водій","ru":"Встречный водитель","w":{"uk":"Зустрічний водій перешкоди не має. Поступається той, на чиїй смузі перешкода, тобто ви.","ru":"У встречного водителя препятствия нет. Уступает тот, на чьей полосе препятствие, то есть вы."}},{"uk":"Той, хто рухається швидше","ru":"Тот, кто движется быстрее","w":{"uk":"Швидкість не має значення: поступається той, на чиїй смузі перешкода.","ru":"Скорость не имеет значения: уступает тот, на чьей полосе препятствие."}}],"c":0,"e":{"uk":"Якщо зустрічний роз'їзд утруднений, дорогу дає водій, на смузі якого є перешкода або габарити транспортного засобу якого заважають зустрічному руху.","ru":"Если встречный разъезд затруднён, дорогу уступает водитель, на полосе которого есть препятствие или габариты транспортного средства которого мешают встречному движению."},"ref":["13.4"],"id":"q2fa7201c2"},{"t":"s13","q":{"uk":"На крутому спуску, позначеному цим знаком, зустрічний роз'їзд утруднений через перешкоду. Хто має дати дорогу?","ru":"На крутом спуске, обозначенном этим знаком, встречный разъезд затруднён из-за препятствия. Кто должен уступить дорогу?"},"a":[{"uk":"Водій, який рухається на підйом","ru":"Водитель, движущийся на подъём","w":{"uk":"Навпаки: на крутому спуску поступається той, хто їде вниз, бо на підйомі важче рушити з місця.","ru":"Наоборот: на крутом спуске уступает тот, кто едет вниз, так как на подъёме тяжелее тронуться с места."}},{"uk":"Водій, який рухається на спуск","ru":"Водитель, движущийся на спуск"},{"uk":"Той, на чиїй смузі перешкода, навіть якщо він їде вгору","ru":"Тот, на чьей полосе препятствие, даже если он едет вверх","w":{"uk":"На ділянках зі знаками 1.6 і 1.7 діє спеціальне правило: поступається той, хто їде на спуск.","ru":"На участках со знаками 1.6 и 1.7 действует специальное правило: уступает тот, кто едет на спуск."}}],"img":{"sign":"1.7"},"c":1,"e":{"uk":"На ділянках, позначених знаками {s:1.6} і {s:1.7}, за наявності перешкоди дорогу дає водій, що рухається на спуск: на підйомі важче рушити з місця.","ru":"На участках, обозначенных знаками {s:1.6} и {s:1.7}, при наличии препятствия дорогу уступает водитель, движущийся на спуск: на подъёме труднее тронуться с места."},"ref":["13.4"],"id":"q07aa54599"},{"t":"s13","q":{"uk":"Яку дистанцію мають тримати поза населеним пунктом транспортні засоби, швидкість яких не перевищує 40 км/год?","ru":"Какую дистанцию должны соблюдать вне населённого пункта транспортные средства, скорость которых не превышает 40 км/ч?"},"a":[{"uk":"Не менше 50 м","ru":"Не менее 50 м","w":{"uk":"Правила не називають конкретного числа: дистанція має дати змогу обганяючим повернутися на свою смугу.","ru":"Правила не называют конкретного числа: дистанция должна позволять обгоняющим вернуться на свою полосу."}},{"uk":"Таку, щоб ті, хто обганяє, могли безперешкодно повернутися на свою смугу","ru":"Такую, чтобы обгоняющие могли беспрепятственно вернуться на свою полосу"},{"uk":"Не менше 100 м","ru":"Не менее 100 м","w":{"uk":"Фіксованих 100 м немає: дистанція залежить від того, чи встигне обганяючий повернутися на смугу.","ru":"Фиксированных 100 м нет: дистанция зависит от того, успеет ли обгоняющий вернуться на полосу."}}],"c":1,"e":{"uk":"Тихохідні транспортні засоби (до 40 км/год) поза населеними пунктами тримають таку дистанцію, щоб автомобілі, які їх обганяють, могли безперешкодно повернутися на свою смугу. Вимога не діє, якщо тихохідний водій сам подає сигнал про обгін чи об'їзд.","ru":"Тихоходные транспортные средства (до 40 км/ч) вне населённых пунктов соблюдают такую дистанцию, чтобы обгоняющие их автомобили могли беспрепятственно вернуться на свою полосу. Требование не действует, если водитель тихоходного средства сам подаёт сигнал об обгоне или объезде."},"ref":["13.2"],"id":"q9c4a2e6ab"},{"t":"s13","q":{"uk":"Яку дистанцію вважають безпечною?","ru":"Какую дистанцию считают безопасной?"},"a":[{"uk":"Не менше 10 м за будь-якої швидкості","ru":"Не менее 10 м при любой скорости","w":{"uk":"10 м на швидкості не досить. Безпечна дистанція залежить від швидкості й умов руху.","ru":"10 м на скорости недостаточно. Безопасная дистанция зависит от скорости и условий движения."}},{"uk":"Таку, за якої в разі раптового гальмування переднього автомобіля можна уникнути зіткнення без маневру","ru":"Такую, при которой в случае внезапного торможения переднего автомобиля можно избежать столкновения без манёвра"},{"uk":"Рівну половині показника спідометра в метрах","ru":"Равную половине показания спидометра в метрах","w":{"uk":"Це лише народне правило, у ПДР його немає. Визначення — можливість уникнути зіткнення без маневру.","ru":"Это лишь народное правило, в ПДД его нет. Определение — возможность избежать столкновения без манёвра."}}],"c":1,"e":{"uk":"Безпечна дистанція — відстань до транспортного засобу попереду, яка в разі його раптового гальмування дає змогу уникнути зіткнення без будь-якого маневру. Її вибирають з урахуванням швидкості, дорожньої обстановки, вантажу і стану автомобіля.","ru":"Безопасная дистанция — расстояние до транспортного средства впереди, которое при его внезапном торможении позволяет избежать столкновения без какого-либо манёвра. Её выбирают с учётом скорости, дорожной обстановки, груза и состояния автомобиля."},"ref":["13.1","1.10"],"id":"q21e6491b1"},{"t":"s14","q":{"uk":"Чи дозволено обгін на перехресті?","ru":"Разрешён ли обгон на перекрёстке?"},"a":[{"uk":"Так, на нерегульованому перехресті","ru":"Да, на нерегулируемом перекрёстке","w":{"uk":"Обгін на перехресті заборонено незалежно від того, регульоване воно чи ні.","ru":"Обгон на перекрёстке запрещён независимо от того, регулируемый он или нет."}},{"uk":"Так, якщо рухаєтеся головною дорогою","ru":"Да, если движетесь по главной дороге","w":{"uk":"Навіть на головній дорозі обганяти на перехресті не можна.","ru":"Даже на главной дороге обгонять на перекрёстке нельзя."}},{"uk":"Ні, на перехресті обгін заборонено","ru":"Нет, на перекрёстке обгон запрещён"}],"c":2,"e":{"uk":"Обгін заборонено на перехресті, на залізничних переїздах і ближче 100 м перед ними, перед пішохідними переходами, у тунелях, на мостах, у кінці підйому та на інших ділянках з обмеженою оглядовістю.","ru":"Обгон запрещён на перекрёстке, на железнодорожных переездах и ближе 100 м перед ними, перед пешеходными переходами, в тоннелях, на мостах, в конце подъёма и на других участках с ограниченной обзорностью."},"ref":["14.6"],"id":"qa9b5c7264"},{"t":"s14","q":{"uk":"На якій відстані перед залізничним переїздом заборонено обгін?","ru":"На каком расстоянии перед железнодорожным переездом запрещён обгон?"},"a":[{"uk":"Ближче 50 м","ru":"Ближе 50 м","w":{"uk":"50 м — норма перед пішохідним переходом у місті. Перед залізничним переїздом — 100 м.","ru":"50 м — норма перед пешеходным переходом в городе. Перед железнодорожным переездом — 100 м."}},{"uk":"Ближче 100 м","ru":"Ближе 100 м"},{"uk":"Ближче 150 м","ru":"Ближе 150 м","w":{"uk":"Заборона починається раніше: вже ближче 100 м до переїзду.","ru":"Запрет начинается раньше: уже ближе 100 м до переезда."}}],"c":1,"e":{"uk":"Обгін заборонено на залізничних переїздах і ближче ніж за 100 м перед ними.","ru":"Обгон запрещён на железнодорожных переездах и ближе чем за 100 м перед ними."},"ref":["14.6"],"id":"q47179a89d"},{"t":"s14","q":{"uk":"Ближче якої відстані до пішохідного переходу в населеному пункті заборонено обгін?","ru":"Ближе какого расстояния до пешеходного перехода в населённом пункте запрещён обгон?"},"a":[{"uk":"50 м","ru":"50 м"},{"uk":"10 м","ru":"10 м","w":{"uk":"10 м — це заборона зупинки біля переходу. Обгін заборонено ближче 50 м у місті.","ru":"10 м — это запрет остановки у перехода. Обгон запрещён ближе 50 м в городе."}},{"uk":"100 м","ru":"100 м","w":{"uk":"100 м — норма поза населеним пунктом. У місті — 50 м.","ru":"100 м — норма вне населённого пункта. В городе — 50 м."}}],"c":0,"e":{"uk":"Обгін заборонено ближче 50 м перед пішохідним переходом у населеному пункті та ближче 100 м — поза населеним пунктом.","ru":"Обгон запрещён ближе 50 м перед пешеходным переходом в населённом пункте и ближе 100 м — вне населённого пункта."},"ref":["14.6"],"id":"q80283c964"},{"t":"s14","q":{"uk":"Водій 1 хоче обігнати автомобіль 2, який уже обганяє автомобіль 3. Чи дозволено це?","ru":"Водитель 1 хочет обогнать автомобиль 2, который уже обгоняет автомобиль 3. Разрешено ли это?"},"a":[{"uk":"Так, якщо зустрічна смуга вільна","ru":"Да, если встречная полоса свободна","w":{"uk":"Вільна зустрічна не допомагає: обганяти того, хто сам обганяє, заборонено завжди.","ru":"Свободная встречная не помогает: обгонять того, кто сам обгоняет, запрещено всегда."}},{"uk":"Ні, обганяти транспортний засіб, що сам виконує обгін, заборонено","ru":"Нет, обгонять транспортное средство, которое само выполняет обгон, запрещено"},{"uk":"Так, якщо автомобіль 2 рухається повільно","ru":"Да, если автомобиль 2 движется медленно","w":{"uk":"Швидкість автомобіля 2 не важлива: він виконує обгін, і обганяти його не можна.","ru":"Скорость автомобиля 2 не важна: он выполняет обгон, и обгонять его нельзя."}}],"img":{"scene":{"road":"straight","lanes":1,"center":"dashed","cars":[{"x":245,"dir":"E","lane":0,"label":"3","color":"green","type":"truck"},{"x":160,"dir":"E","lane":0,"move":"overtake","label":"2","color":"blue"},{"x":60,"dir":"E","lane":0,"move":"overtake","label":"1","color":"red","me":true}]}},"c":1,"e":{"uk":"Обгін транспортного засобу, який сам здійснює обгін або об'їзд, заборонено. Крім того, перед обгоном треба переконатися, що ніхто попереду не почав обгону і зустрічна смуга вільна.","ru":"Обгон транспортного средства, которое само выполняет обгон или объезд, запрещён. Кроме того, перед обгоном нужно убедиться, что никто впереди не начал обгона и встречная полоса свободна."},"ref":["14.6","14.2"],"id":"q64a839530"},{"t":"s14","q":{"uk":"Чи можна обганяти на дорозі, що має дві смуги для руху в одному напрямку?","ru":"Можно ли обгонять на дороге, имеющей две полосы для движения в одном направлении?"},"a":[{"uk":"Так, якщо немає суцільної розмітки","ru":"Да, если нет сплошной разметки","w":{"uk":"Розмітка тут ні до чого: на дорогах з двома смугами в одному напрямку обгін з виїздом на зустрічну заборонено.","ru":"Разметка здесь ни при чём: на дорогах с двумя полосами в одном направлении обгон с выездом на встречную запрещён."}},{"uk":"Ні, обгін на таких дорогах заборонено","ru":"Нет, обгон на таких дорогах запрещён"},{"uk":"Так, лише поза населеним пунктом","ru":"Да, только вне населённого пункта","w":{"uk":"Заборона діє і в місті, і за містом. Випереджати можна сусідньою смугою свого напрямку.","ru":"Запрет действует и в городе, и за городом. Опережать можно по соседней полосе своего направления."}}],"c":1,"e":{"uk":"На дорогах з двома і більше смугами в одному напрямку обгін (з виїздом на зустрічну смугу) заборонено. Випереджати можна сусідньою смугою свого напрямку.","ru":"На дорогах с двумя и более полосами в одном направлении обгон (с выездом на встречную полосу) запрещён. Опережать можно по соседней полосе своего направления."},"ref":["14.6","11.4"],"id":"qa101f1d5c"},{"t":"s14","q":{"uk":"Вас обганяють. Що вам заборонено?","ru":"Вас обгоняют. Что вам запрещено?"},"a":[{"uk":"Перешкоджати обгону, підвищуючи швидкість або іншими діями","ru":"Препятствовать обгону, повышая скорость или иными действиями"},{"uk":"Знижувати швидкість","ru":"Снижать скорость","w":{"uk":"Знижувати швидкість не заборонено — навпаки, це допомагає тому, хто обганяє.","ru":"Снижать скорость не запрещено — наоборот, это помогает обгоняющему."}},{"uk":"Рухатися ближче до правого краю","ru":"Двигаться ближе к правому краю","w":{"uk":"Рухатися ближче до правого краю правильно — це полегшує обгін.","ru":"Двигаться ближе к правому краю правильно — это облегчает обгон."}}],"c":0,"e":{"uk":"Водієві транспортного засобу, якого обганяють, заборонено перешкоджати обгону підвищенням швидкості або іншими діями.","ru":"Водителю обгоняемого транспортного средства запрещено препятствовать обгону повышением скорости или иными действиями."},"ref":["14.3"],"id":"q7819aaf94"},{"t":"s14","q":{"uk":"У чому має переконатися водій перед початком обгону?","ru":"В чём должен убедиться водитель перед началом обгона?"},"a":[{"uk":"Що ніхто позаду не почав обгону","ru":"Что никто сзади не начал обгона","w":{"uk":"Це лише одна з умов. Переконатися треба в усіх: позаду, попереду і на зустрічній.","ru":"Это лишь одно из условий. Убедиться нужно во всех: сзади, впереди и на встречной."}},{"uk":"Що водій попереду не подав сигналу повороту ліворуч","ru":"Что водитель впереди не подал сигнала поворота налево","w":{"uk":"Це лише одна з умов. Треба також перевірити, що позаду ніхто не обганяє і зустрічна вільна.","ru":"Это лишь одно из условий. Нужно также проверить, что сзади никто не обгоняет и встречная свободна."}},{"uk":"Що зустрічна смуга вільна на достатній відстані і він зможе повернутися на свою смугу","ru":"Что встречная полоса свободна на достаточном расстоянии и он сможет вернуться на свою полосу","w":{"uk":"Це лише частина умов. Ще треба переконатися, що позаду ніхто не почав обгону, а передній не сигналить ліворуч.","ru":"Это лишь часть условий. Ещё нужно убедиться, что сзади никто не начал обгон, а передний не сигналит налево."}},{"uk":"У всьому переліченому","ru":"Во всём перечисленном"}],"c":3,"e":{"uk":"Перед обгоном водій переконується, що ніхто позаду не почав обгону, водій попереду не сигналить про поворот ліворуч, зустрічна смуга вільна на достатній відстані і він зможе повернутися, не заважаючи тому, кого обганяє.","ru":"Перед обгоном водитель убеждается, что никто сзади не начал обгона, водитель впереди не сигналит о повороте налево, встречная полоса свободна на достаточном расстоянии и он сможет вернуться, не мешая обгоняемому."},"ref":["14.2"],"id":"q707903757"},{"t":"s14","q":{"uk":"Позаду колони автомобілів рухається автомобіль з увімкненим синім проблисковим маячком. Чи можна обганяти цю колону?","ru":"Позади колонны автомобилей движется автомобиль с включённым синим проблесковым маячком. Можно ли обгонять эту колонну?"},"a":[{"uk":"Так, якщо зустрічна смуга вільна","ru":"Да, если встречная полоса свободна","w":{"uk":"Вільна зустрічна нічого не змінює: колону з маячком позаду обганяти заборонено.","ru":"Свободная встречная ничего не меняет: колонну с маячком сзади обгонять запрещено."}},{"uk":"Ні, заборонено","ru":"Нет, запрещено"},{"uk":"Так, але лише з дозволу поліцейського","ru":"Да, но только с разрешения полицейского","w":{"uk":"Такого порядку Правила не передбачають: обгін такої колони просто заборонено.","ru":"Такого порядка Правила не предусматривают: обгон такой колонны просто запрещён."}}],"c":1,"e":{"uk":"Заборонено обганяти колону транспортних засобів, позаду якої рухається транспортний засіб з увімкненим проблисковим маячком (крім оранжевого).","ru":"Запрещено обгонять колонну транспортных средств, позади которой движется транспортное средство с включённым проблесковым маячком (кроме оранжевого)."},"ref":["14.6"],"id":"qd403f7d74"},{"t":"s14","q":{"uk":"Поза населеним пунктом обігнати тихохідну сільгосптехніку шириною понад 2,6 м неможливо через дорожню обстановку. Що повинен зробити її водій?","ru":"Вне населённого пункта обогнать тихоходную сельхозтехнику шириной более 2,6 м невозможно из-за дорожной обстановки. Что должен сделать её водитель?"},"a":[{"uk":"Збільшити швидкість","ru":"Увеличить скорость","w":{"uk":"Тихохідна техніка не може суттєво прискоритися. Правила вимагають триматися правіше й пропускати інших.","ru":"Тихоходная техника не может существенно ускориться. Правила требуют держаться правее и пропускать других."}},{"uk":"Рухатися якомога правіше, а за потреби зупинитися на узбіччі й пропустити транспорт позаду","ru":"Двигаться как можно правее, а при необходимости остановиться на обочине и пропустить транспорт сзади"},{"uk":"Нічого, це проблема тих, хто позаду","ru":"Ничего, это проблема тех, кто сзади","w":{"uk":"Ні: водій такої техніки зобов'язаний допомогти обгону — триматися правіше і за потреби зупинитися.","ru":"Нет: водитель такой техники обязан помочь обгону — держаться правее и при необходимости остановиться."}}],"c":1,"e":{"uk":"Водій тихохідного, великогабаритного транспортного засобу або сільгосптехніки шириною понад 2,6 м, якщо обгін неможливий, рухається якомога правіше, а за потреби зупиняється на узбіччі, щоб пропустити транспорт.","ru":"Водитель тихоходного, крупногабаритного транспортного средства или сельхозтехники шириной более 2,6 м, если обгон невозможен, движется как можно правее, а при необходимости останавливается на обочине, чтобы пропустить транспорт."},"ref":["14.4"],"id":"qc32529dd0"},{"t":"s14","q":{"uk":"Знак 3.25 «Обгін заборонено». Кого все ж можна обганяти в зоні його дії?","ru":"Знак 3.25 «Обгон запрещён». Кого всё же можно обгонять в зоне его действия?"},"a":[{"uk":"Нікого","ru":"Никого","w":{"uk":"Є виняток: поодинокі транспортні засоби, що їдуть повільніше 30 км/год, обганяти можна.","ru":"Есть исключение: одиночные транспортные средства, едущие медленнее 30 км/ч, обгонять можно."}},{"uk":"Поодинокі транспортні засоби, що рухаються зі швидкістю менше 30 км/год","ru":"Одиночные транспортные средства, движущиеся со скоростью менее 30 км/ч"},{"uk":"Будь-які транспортні засоби, якщо зустрічна смуга вільна","ru":"Любые транспортные средства, если встречная полоса свободна","w":{"uk":"Знак забороняє обгін незалежно від того, чи вільна зустрічна. Виняток — лише поодинокі ТЗ до 30 км/год.","ru":"Знак запрещает обгон независимо от того, свободна ли встречная. Исключение — только одиночные ТС до 30 км/ч."}}],"img":{"sign":"3.25"},"c":1,"e":{"uk":"Знак {s:3.25} забороняє обгін усіх транспортних засобів, крім поодиноких, що рухаються зі швидкістю менше 30 км/год.","ru":"Знак {s:3.25} запрещает обгон всех транспортных средств, кроме одиночных, движущихся со скоростью менее 30 км/ч."},"ref":["33.3"],"id":"qdac9640a9"},{"t":"s14","q":{"uk":"Чи можна обганяти в кінці підйому або на мосту?","ru":"Можно ли обгонять в конце подъёма или на мосту?"},"a":[{"uk":"Ні","ru":"Нет"},{"uk":"Так, якщо немає знаків, що забороняють обгін","ru":"Да, если нет знаков, запрещающих обгон","w":{"uk":"Знаки не потрібні: у кінці підйому й на мостах обгін заборонений самими Правилами.","ru":"Знаки не нужны: в конце подъёма и на мостах обгон запрещён самими Правилами."}},{"uk":"На мосту можна, у кінці підйому — ні","ru":"На мосту можно, в конце подъёма — нет","w":{"uk":"Ні, обгін заборонено в обох місцях — і на мосту, і в кінці підйому.","ru":"Нет, обгон запрещён в обоих местах — и на мосту, и в конце подъёма."}}],"c":0,"e":{"uk":"Обгін заборонено в кінці підйому, на мостах, естакадах, шляхопроводах, крутих поворотах і на ділянках з обмеженою оглядовістю чи за недостатньої видимості.","ru":"Обгон запрещён в конце подъёма, на мостах, эстакадах, путепроводах, крутых поворотах и на участках с ограниченной обзорностью или при недостаточной видимости."},"ref":["14.6"],"id":"q5efe35744"},{"t":"s15","q":{"uk":"Чим зупинка відрізняється від стоянки?","ru":"Чем остановка отличается от стоянки?"},"a":[{"uk":"Зупинка — припинення руху до 5 хвилин (або довше для посадки чи вантаження); стоянка — понад 5 хвилин з інших причин","ru":"Остановка — прекращение движения до 5 минут (или дольше для посадки или погрузки); стоянка — более 5 минут по другим причинам"},{"uk":"Зупинка — до 10 хвилин, стоянка — понад 10 хвилин","ru":"Остановка — до 10 минут, стоянка — более 10 минут","w":{"uk":"Межа між зупинкою і стоянкою — 5 хвилин, а не 10.","ru":"Граница между остановкой и стоянкой — 5 минут, а не 10."}},{"uk":"Під час зупинки водій не виходить з автомобіля","ru":"При остановке водитель не выходит из автомобиля","w":{"uk":"Різниця не в тому, чи виходить водій, а в часі (до 5 хвилин) і причині припинення руху.","ru":"Разница не в том, выходит ли водитель, а во времени (до 5 минут) и причине прекращения движения."}}],"c":0,"e":{"uk":"Зупинка — припинення руху на час до 5 хвилин або більше, якщо це потрібно для посадки (висадки) пасажирів, вантаження чи виконання вимог Правил. Стоянка — понад 5 хвилин з інших причин.","ru":"Остановка — прекращение движения на время до 5 минут или более, если это нужно для посадки (высадки) пассажиров, погрузки или выполнения требований Правил. Стоянка — более 5 минут по другим причинам."},"ref":["1.10"],"id":"q026d68119"},{"t":"s15","q":{"uk":"Ближче якої відстані до пішохідного переходу заборонено зупинку?","ru":"Ближе какого расстояния до пешеходного перехода запрещена остановка?"},"a":[{"uk":"5 м","ru":"5 м","w":{"uk":"5 м — замало: зупинку заборонено ближче 10 м від переходу з обох боків.","ru":"5 м — мало: остановка запрещена ближе 10 м от перехода с обеих сторон."}},{"uk":"10 м","ru":"10 м"},{"uk":"15 м","ru":"15 м","w":{"uk":"Зупинятися можна вже з 10 м, тож 15 м — не межа.","ru":"Останавливаться можно уже с 10 м, поэтому 15 м — не граница."}},{"uk":"30 м","ru":"30 м","w":{"uk":"30 м — норма біля зупинок маршрутного транспорту, а не біля переходу.","ru":"30 м — норма у остановок маршрутного транспорта, а не у перехода."}}],"c":1,"e":{"uk":"Зупинку заборонено на пішохідних переходах і ближче 10 м від них з обох боків, крім зупинки для надання переваги в русі.","ru":"Остановка запрещена на пешеходных переходах и ближе 10 м от них с обеих сторон, кроме остановки для предоставления преимущества в движении."},"ref":["15.9"],"id":"q4d28eccb0"},{"t":"s15","q":{"uk":"Ближче якої відстані до зупинки маршрутного транспорту заборонено зупиняти автомобіль?","ru":"Ближе какого расстояния к остановке маршрутного транспорта запрещено останавливать автомобиль?"},"a":[{"uk":"10 м","ru":"10 м","w":{"uk":"10 м — відстань для переходів і перехресть. Біля зупинок транспорту — 30 м.","ru":"10 м — расстояние для переходов и перекрёстков. У остановок транспорта — 30 м."}},{"uk":"20 м","ru":"20 м","w":{"uk":"Такої норми немає: зупинку заборонено ближче 30 м до зупинки маршрутного транспорту.","ru":"Такой нормы нет: остановка запрещена ближе 30 м к остановке маршрутного транспорта."}},{"uk":"30 м","ru":"30 м"},{"uk":"50 м","ru":"50 м","w":{"uk":"50 м — норма для стоянки біля переїзду. Біля зупинок транспорту — 30 м.","ru":"50 м — норма для стоянки у переезда. У остановок транспорта — 30 м."}}],"c":2,"e":{"uk":"Зупинку заборонено ближче 30 м від посадкових майданчиків маршрутного транспорту, а якщо їх немає — ближче 30 м від знака зупинки з обох боків.","ru":"Остановка запрещена ближе 30 м от посадочных площадок маршрутного транспорта, а если их нет — ближе 30 м от знака остановки с обеих сторон."},"ref":["15.9"],"id":"qd09116827"},{"t":"s15","q":{"uk":"Чи можна зупинитися на мосту?","ru":"Можно ли остановиться на мосту?"},"a":[{"uk":"Так, біля правого краю","ru":"Да, у правого края","w":{"uk":"Біля правого краю на мосту зупинятися теж не можна: заборона діє на всьому мосту.","ru":"У правого края на мосту останавливаться тоже нельзя: запрет действует на всём мосту."}},{"uk":"Ні, зупинку на мостах, естакадах, шляхопроводах, під ними і в тунелях заборонено","ru":"Нет, остановка на мостах, эстакадах, путепроводах, под ними и в тоннелях запрещена"},{"uk":"Так, на час до 5 хвилин","ru":"Да, на время до 5 минут","w":{"uk":"Тривалість не важлива: на мосту заборонена навіть коротка зупинка.","ru":"Длительность не важна: на мосту запрещена даже короткая остановка."}}],"c":1,"e":{"uk":"Зупинка заборонена на естакадах, мостах, шляхопроводах і під ними, а також у тунелях.","ru":"Остановка запрещена на эстакадах, мостах, путепроводах и под ними, а также в тоннелях."},"ref":["15.9"],"id":"q0b93c5b86"},{"t":"s15","q":{"uk":"Яку найменшу відстань має бути між автомобілем, що зупинився, і суцільною лінією розмітки?","ru":"Какое наименьшее расстояние должно быть между остановившимся автомобилем и сплошной линией разметки?"},"a":[{"uk":"3 м","ru":"3 м"},{"uk":"1 м","ru":"1 м","w":{"uk":"1 м — замало: інші не зможуть безпечно проїхати. Правила вимагають щонайменше 3 м.","ru":"1 м — мало: другие не смогут безопасно проехать. Правила требуют не менее 3 м."}},{"uk":"2 м","ru":"2 м","w":{"uk":"2 м — замало: мінімум 3 м до суцільної лінії.","ru":"2 м — мало: минимум 3 м до сплошной линии."}},{"uk":"5 м","ru":"5 м","w":{"uk":"5 м — більше, ніж потрібно. Найменша відстань — 3 м.","ru":"5 м — больше, чем нужно. Наименьшее расстояние — 3 м."}}],"c":0,"e":{"uk":"Зупинку заборонено там, де між суцільною лінією розмітки, розділювальною смугою або протилежним краєм проїзної частини і транспортним засобом залишається менше 3 м.","ru":"Остановка запрещена там, где между сплошной линией разметки, разделительной полосой или противоположным краем проезжей части и транспортным средством остаётся менее 3 м."},"ref":["15.9"],"id":"qe621244cf"},{"t":"s15","q":{"uk":"На якій відстані від залізничного переїзду заборонено стоянку?","ru":"На каком расстоянии от железнодорожного переезда запрещена стоянка?"},"a":[{"uk":"Ближче 10 м","ru":"Ближе 10 м","w":{"uk":"10 м — норма для зупинки перед переїздом (якщо немає знаків). Стоянку заборонено ближче 50 м.","ru":"10 м — норма для остановки перед переездом (если нет знаков). Стоянка запрещена ближе 50 м."}},{"uk":"Ближче 30 м","ru":"Ближе 30 м","w":{"uk":"Такої норми немає: стоянку заборонено ближче 50 м від переїзду.","ru":"Такой нормы нет: стоянка запрещена ближе 50 м от переезда."}},{"uk":"Ближче 50 м","ru":"Ближе 50 м"},{"uk":"Ближче 100 м","ru":"Ближе 100 м","w":{"uk":"100 м — це заборона обгону перед переїздом. Стоянку заборонено ближче 50 м.","ru":"100 м — это запрет обгона перед переездом. Стоянка запрещена ближе 50 м."}}],"c":2,"e":{"uk":"Стоянку заборонено ближче 50 м від залізничних переїздів. Зупинку на самому переїзді заборонено.","ru":"Стоянка запрещена ближе 50 м от железнодорожных переездов. Остановка на самом переезде запрещена."},"ref":["15.10"],"id":"q4799d646c"},{"t":"s15","q":{"uk":"За якої умови легковий автомобіль можна поставити на краю тротуару?","ru":"При каком условии легковой автомобиль можно поставить на краю тротуара?"},"a":[{"uk":"Якщо пішоходам залишається щонайменше 1 м","ru":"Если пешеходам остаётся не менее 1 м","w":{"uk":"1 м — замало для пішоходів. Правила вимагають залишити щонайменше 2 м.","ru":"1 м — мало для пешеходов. Правила требуют оставить не менее 2 м."}},{"uk":"Якщо пішоходам залишається щонайменше 2 м","ru":"Если пешеходам остаётся не менее 2 м"},{"uk":"Ставити на тротуар заборонено завжди","ru":"Ставить на тротуар запрещено всегда","w":{"uk":"Не завжди: легковий автомобіль можна поставити на краю тротуару, якщо пішоходам лишається 2 м і знаки не забороняють.","ru":"Не всегда: легковой автомобиль можно поставить на краю тротуара, если пешеходам остаётся 2 м и знаки не запрещают."}}],"c":1,"e":{"uk":"Легкові автомобілі та мотоцикли можна ставити на краю тротуару, якщо для руху пішоходів залишається щонайменше 2 м (і якщо це не заборонено знаками).","ru":"Легковые автомобили и мотоциклы можно ставить на краю тротуара, если для движения пешеходов остаётся не менее 2 м (и если это не запрещено знаками)."},"ref":["15.10"],"id":"q7d89f6da3"},{"t":"s15","q":{"uk":"Де в населеному пункті можна зупинитися на лівому боці дороги?","ru":"Где в населённом пункте можно остановиться на левой стороне дороги?"},"a":[{"uk":"На дорозі з однією смугою в кожному напрямку без трамвайних колій посередині і без розмітки 1.1, а також на дорозі з одностороннім рухом","ru":"На дороге с одной полосой в каждом направлении без трамвайных путей посередине и без разметки 1.1, а также на дороге с односторонним движением"},{"uk":"На будь-якій дорозі, якщо немає знаків заборони","ru":"На любой дороге, если нет запрещающих знаков","w":{"uk":"Не на будь-якій: ліворуч можна лише на дорогах з однією смугою в кожному напрямку (без трамвая й розмітки 1.1) або на односторонніх.","ru":"Не на любой: слева можно только на дорогах с одной полосой в каждом направлении (без трамвая и разметки 1.1) или на односторонних."}},{"uk":"Лише на дорозі з двома смугами в кожному напрямку","ru":"Только на дороге с двумя полосами в каждом направлении","w":{"uk":"Навпаки: на дорогах з двома смугами в кожному напрямку зупинятися зліва не можна.","ru":"Наоборот: на дорогах с двумя полосами в каждом направлении останавливаться слева нельзя."}}],"c":0,"e":{"uk":"У населених пунктах зупинку і стоянку зліва дозволено на дорогах з однією смугою в кожному напрямку (без трамвая посередині і без розмітки {m:1.1}), а також на дорогах з одностороннім рухом. Біля бульвару чи розділювальної смуги зупинятися не можна.","ru":"В населённых пунктах остановка и стоянка слева разрешены на дорогах с одной полосой в каждом направлении (без трамвая посередине и без разметки {m:1.1}), а также на дорогах с односторонним движением. У бульвара или разделительной полосы останавливаться нельзя."},"ref":["15.3"],"id":"q033551304"},{"t":"s15","q":{"uk":"Як поставити автомобіль під кутом до тротуару на рівній дорозі?","ru":"Как поставить автомобиль под углом к тротуару на ровной дороге?"},"a":[{"uk":"Лише передньою частиною до тротуару","ru":"Только передней частью к тротуару"},{"uk":"Лише задньою частиною до тротуару","ru":"Только задней частью к тротуару","w":{"uk":"Задньою частиною до тротуару ставлять лише на підйомах. На рівній дорозі — передньою.","ru":"Задней частью к тротуару ставят только на подъёмах. На ровной дороге — передней."}},{"uk":"Будь-якою частиною","ru":"Любой частью","w":{"uk":"Не будь-якою: на рівній дорозі — передом, на підйомі — задом.","ru":"Не любой: на ровной дороге — передом, на подъёме — задом."}}],"c":0,"e":{"uk":"Біля тротуарів під кутом ставлять лише передньою частиною, а на підйомах — тільки задньою, щоб автомобіль не міг самовільно скотитися.","ru":"У тротуаров под углом ставят только передней частью, а на подъёмах — только задней, чтобы автомобиль не мог самопроизвольно скатиться."},"ref":["15.5"],"id":"qb6ca144a4"},{"t":"s15","q":{"uk":"Чи можна зупинитися ближче 10 м від виїзду з прилеглої території?","ru":"Можно ли остановиться ближе 10 м от выезда с прилегающей территории?"},"a":[{"uk":"Так, якщо водій не виходить з автомобіля","ru":"Да, если водитель не выходит из автомобиля","w":{"uk":"Те, що водій лишається в машині, не скасовує заборони: зупинятися ближче 10 м від виїзду не можна.","ru":"То, что водитель остаётся в машине, не отменяет запрета: останавливаться ближе 10 м от выезда нельзя."}},{"uk":"Ні","ru":"Нет"},{"uk":"Так, у світлу пору доби","ru":"Да, в светлое время суток","w":{"uk":"Пора доби не має значення: заборона діє завжди.","ru":"Время суток не имеет значения: запрет действует всегда."}}],"c":1,"e":{"uk":"Зупинку заборонено ближче 10 м від виїздів з прилеглих територій і безпосередньо в місці виїзду.","ru":"Остановка запрещена ближе 10 м от выездов с прилегающих территорий и непосредственно в месте выезда."},"ref":["15.9"],"id":"q9c9a44908"},{"t":"s15","q":{"uk":"Де можна стояти поза населеним пунктом у темну пору доби?","ru":"Где можно стоять вне населённого пункта в тёмное время суток?"},"a":[{"uk":"На узбіччі з увімкненими габаритними вогнями","ru":"На обочине с включёнными габаритными огнями","w":{"uk":"Габарити не роблять узбіччя безпечним: уночі поза містом стояти можна лише на майданчиках або за межами дороги.","ru":"Габариты не делают обочину безопасной: ночью за городом стоять можно только на площадках или за пределами дороги."}},{"uk":"Лише на майданчиках для стоянки або за межами дороги","ru":"Только на площадках для стоянки или за пределами дороги"},{"uk":"Біля правого краю проїзної частини з аварійною сигналізацією","ru":"У правого края проезжей части с аварийной сигнализацией","w":{"uk":"Аварійка — для вимушеної зупинки, а не для стоянки. Стояти уночі за містом можна лише на майданчиках чи поза дорогою.","ru":"Аварийка — для вынужденной остановки, а не для стоянки. Стоять ночью за городом можно только на площадках или вне дороги."}}],"c":1,"e":{"uk":"У темну пору доби і за недостатньої видимості стоянка поза населеними пунктами дозволена лише на майданчиках для стоянки або за межами дороги.","ru":"В тёмное время суток и при недостаточной видимости стоянка вне населённых пунктов разрешена только на площадках для стоянки или за пределами дороги."},"ref":["15.11"],"id":"qd2eb408fe"},{"t":"s15","q":{"uk":"Автомобіль 1 зупинився на перехресті, поруч немає пішохідного переходу. Чи порушив водій Правила?","ru":"Автомобиль 1 остановился на перекрёстке, рядом нет пешеходного перехода. Нарушил ли водитель Правила?"},"a":[{"uk":"Ні, якщо зупинка триває менше 5 хвилин","ru":"Нет, если остановка длится менее 5 минут","w":{"uk":"Тривалість не важлива: будь-яка зупинка на перехресті заборонена (крім надання переваги).","ru":"Длительность не важна: любая остановка на перекрёстке запрещена (кроме предоставления преимущества)."}},{"uk":"Так. Зупинка на перехресті і ближче 10 м від краю перехрещуваної проїзної частини заборонена (крім надання переваги)","ru":"Да. Остановка на перекрёстке и ближе 10 м от края пересекаемой проезжей части запрещена (кроме предоставления преимущества)"},{"uk":"Ні, якщо він увімкнув аварійну сигналізацію","ru":"Нет, если он включил аварийную сигнализацию","w":{"uk":"Аварійка не дає права зупинятися там, де це заборонено.","ru":"Аварийка не даёт права останавливаться там, где это запрещено."}}],"c":1,"e":{"uk":"Зупинку заборонено на перехрестях і ближче 10 м від краю перехрещуваної проїзної частини. Винятки — зупинка для надання переваги та зупинка навпроти бокового проїзду на Т-подібному перехресті з суцільною лінією або розділювальною смугою.","ru":"Остановка запрещена на перекрёстках и ближе 10 м от края пересекаемой проезжей части. Исключения — остановка для предоставления преимущества и остановка напротив бокового проезда на Т-образном перекрёстке со сплошной линией или разделительной полосой."},"ref":["15.9"],"id":"q2b628c82f"},{"t":"s15","q":{"uk":"Чи можна ставити легкові автомобілі на проїзній частині у два ряди?","ru":"Можно ли ставить легковые автомобили на проезжей части в два ряда?"},"a":[{"uk":"Так, на короткий час","ru":"Да, на короткое время","w":{"uk":"Навіть на короткий час ставити автомобілі у два ряди не можна.","ru":"Даже на короткое время ставить автомобили в два ряда нельзя."}},{"uk":"Ні. У два ряди можна ставити лише велосипеди, мопеди та мотоцикли без бокового причепа","ru":"Нет. В два ряда можно ставить только велосипеды, мопеды и мотоциклы без бокового прицепа"},{"uk":"Так, якщо ширина проїзної частини дозволяє","ru":"Да, если ширина проезжей части позволяет","w":{"uk":"Ширина дороги не має значення: заборона діє завжди. У два ряди — лише двоколісні.","ru":"Ширина дороги не имеет значения: запрет действует всегда. В два ряда — только двухколёсные."}}],"c":1,"e":{"uk":"Транспортні засоби не можна ставити на проїзній частині у два і більше ряди. Велосипеди, мопеди та мотоцикли без бокового причепа — не більше ніж у два ряди.","ru":"Транспортные средства нельзя ставить на проезжей части в два и более ряда. Велосипеды, мопеды и мотоциклы без бокового прицепа — не более чем в два ряда."},"ref":["15.4"],"id":"q26ef5dc0c"},{"t":"s15","q":{"uk":"Чи можна відчинити двері автомобіля з боку проїзної частини, якщо це заважає іншим?","ru":"Можно ли открыть дверь автомобиля со стороны проезжей части, если это мешает другим?"},"a":[{"uk":"Так, на короткий час","ru":"Да, на короткое время","w":{"uk":"Навіть на секунду відчиняти двері, якщо це загрожує безпеці чи заважає іншим, заборонено.","ru":"Даже на секунду открывать дверь, если это угрожает безопасности или мешает другим, запрещено."}},{"uk":"Ні, якщо це загрожує безпеці чи створює перешкоди","ru":"Нет, если это угрожает безопасности или создаёт помехи"},{"uk":"Так, якщо автомобіль стоїть на стоянці","ru":"Да, если автомобиль стоит на стоянке","w":{"uk":"Стоянка не скасовує вимоги: якщо відчинені двері заважають руху, відчиняти їх не можна.","ru":"Стоянка не отменяет требования: если открытая дверь мешает движению, открывать её нельзя."}}],"c":1,"e":{"uk":"Заборонено відчиняти двері, залишати їх відчиненими і виходити з автомобіля, якщо це загрожує безпеці або створює перешкоди іншим учасникам руху.","ru":"Запрещено открывать двери, оставлять их открытыми и выходить из автомобиля, если это угрожает безопасности или создаёт помехи другим участникам движения."},"ref":["15.13"],"id":"q2e113f8a7"},{"t":"s16","q":{"uk":"Хто з водіїв першим проїде перехрестя рівнозначних доріг?","ru":"Кто из водителей первым проедет перекрёсток равнозначных дорог?"},"a":[{"uk":"Водій автомобіля 1","ru":"Водитель автомобиля 1","w":{"uk":"На рівнозначних дорогах діє «перешкода праворуч»: автомобіль 2 праворуч від водія 1, тож водій 1 поступається.","ru":"На равнозначных дорогах действует «помеха справа»: автомобиль 2 справа от водителя 1, поэтому водитель 1 уступает."}},{"uk":"Водій автомобіля 2","ru":"Водитель автомобиля 2"},{"uk":"Вони роз'їжджаються за взаємною домовленістю","ru":"Они разъезжаются по взаимной договорённости","w":{"uk":"Домовленості Правила не передбачають: черговість чітко визначає правило «перешкода праворуч».","ru":"Договорённости Правила не предусматривают: очерёдность чётко определяет правило «помеха справа»."}}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"straight","label":"1","color":"red","me":true},{"arm":"E","move":"straight","label":"2","color":"blue"}]}},"c":1,"e":{"uk":"На перехресті рівнозначних доріг діє правило «перешкода праворуч»: автомобіль 2 наближається праворуч від автомобіля 1, тому водій 1 дає йому дорогу.","ru":"На перекрёстке равнозначных дорог действует правило «помеха справа»: автомобиль 2 приближается справа от автомобиля 1, поэтому водитель 1 уступает ему дорогу."},"ref":["16.12"],"id":"q6ecd3b18e"},{"t":"s16","q":{"uk":"Хто першим проїде перехрестя?","ru":"Кто первым проедет перекрёсток?"},"a":[{"uk":"Автомобіль 2","ru":"Автомобиль 2"},{"uk":"Автомобіль 1","ru":"Автомобиль 1","w":{"uk":"Автомобіль 1 стоїть перед знаком «Дати дорогу» — він на другорядній дорозі і проїжджає останнім.","ru":"Автомобиль 1 стоит перед знаком «Уступить дорогу» — он на второстепенной дороге и проезжает последним."}},{"uk":"Автомобіль 1, бо автомобіль 2 наближається ліворуч","ru":"Автомобиль 1, так как автомобиль 2 приближается слева","w":{"uk":"Правило «перешкода праворуч» діє лише на рівнозначних дорогах. Тут автомобіль 2 на головній, і бік не важливий.","ru":"Правило «помеха справа» действует только на равнозначных дорогах. Здесь автомобиль 2 на главной, и сторона не важна."}}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"straight","label":"1","color":"red","me":true},{"arm":"W","move":"straight","label":"2","color":"blue"}],"signs":[{"arm":"S","code":"2.1"},{"arm":"W","code":"2.3"}]}},"c":0,"e":{"uk":"Автомобіль 1 стоїть перед знаком {s:2.1} «Дати дорогу» — він на другорядній дорозі. Автомобіль 2 рухається головною ({s:2.3}), тому має перевагу незалежно від того, з якого боку наближається.","ru":"Автомобиль 1 стоит перед знаком {s:2.1} «Уступить дорогу» — он на второстепенной дороге. Автомобиль 2 едет по главной ({s:2.3}), поэтому имеет преимущество независимо от того, с какой стороны приближается."},"ref":["16.11"],"id":"qe30de3907"},{"t":"s16","q":{"uk":"Водій автомобіля 1 повертає ліворуч на перехресті рівнозначних доріг. Хто проїде першим?","ru":"Водитель автомобиля 1 поворачивает налево на перекрёстке равнозначных дорог. Кто проедет первым?"},"a":[{"uk":"Автомобіль 1","ru":"Автомобиль 1","w":{"uk":"Повертаючи ліворуч, водій 1 зобов'язаний пропустити зустрічний автомобіль 2, що їде прямо.","ru":"Поворачивая налево, водитель 1 обязан пропустить встречный автомобиль 2, едущий прямо."}},{"uk":"Автомобіль 2","ru":"Автомобиль 2"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"left","label":"1","color":"red","me":true},{"arm":"N","move":"straight","label":"2","color":"blue"}]}},"c":1,"e":{"uk":"Перед поворотом ліворуч водій зобов'язаний дати дорогу зустрічним транспортним засобам, що рухаються прямо або праворуч.","ru":"Перед поворотом налево водитель обязан уступить дорогу встречным транспортным средствам, движущимся прямо или направо."},"ref":["16.13"],"id":"qcbcf355cd"},{"t":"s16","q":{"uk":"Хто має перевагу на цьому нерегульованому перехресті рівнозначних доріг?","ru":"У кого преимущество на этом нерегулируемом перекрёстке равнозначных дорог?"},"a":[{"uk":"Автомобіль 1, бо трамвай наближається ліворуч","ru":"Автомобиль 1, так как трамвай приближается слева","w":{"uk":"Правило «перешкода праворуч» не стосується трамвая: на рівнозначному перехресті він має перевагу з будь-якого боку.","ru":"Правило «помеха справа» не касается трамвая: на равнозначном перекрёстке у него преимущество с любой стороны."}},{"uk":"Трамвай 2","ru":"Трамвай 2"},{"uk":"Той, хто першим під'їхав до перехрестя","ru":"Тот, кто первым подъехал к перекрёстку","w":{"uk":"Хто першим під'їхав — не критерій. На рівнозначному перехресті трамвай завжди має перевагу.","ru":"Кто первым подъехал — не критерий. На равнозначном перекрёстке у трамвая всегда преимущество."}}],"img":{"scene":{"road":"cross","tram":true,"cars":[{"arm":"E","move":"straight","label":"1","color":"red","me":true},{"arm":"S","move":"straight","label":"2","type":"tram"}]}},"c":1,"e":{"uk":"На нерегульованому перехресті рівнозначних доріг трамвай має перевагу перед нерейковими транспортними засобами незалежно від напрямку руху. Правило «перешкода праворуч» тут не застосовується.","ru":"На нерегулируемом перекрёстке равнозначных дорог трамвай имеет преимущество перед нерельсовыми транспортными средствами независимо от направления движения. Правило «помеха справа» здесь не применяется."},"ref":["16.12"],"id":"q22740d9f8"},{"t":"s16","q":{"uk":"Обом водіям горить зелений сигнал. Автомобіль 1 повертає ліворуч. Хто проїде першим?","ru":"Обоим водителям горит зелёный сигнал. Автомобиль 1 поворачивает налево. Кто проедет первым?"},"a":[{"uk":"Автомобіль 1","ru":"Автомобиль 1","w":{"uk":"Зелений сигнал не дає переваги тому, хто повертає ліворуч: він пропускає зустрічних, що їдуть прямо.","ru":"Зелёный сигнал не даёт преимущества поворачивающему налево: он пропускает встречных, едущих прямо."}},{"uk":"Автомобіль 2","ru":"Автомобиль 2"},{"uk":"Хто першим в'їхав на перехрестя","ru":"Тот, кто первым въехал на перекрёсток","w":{"uk":"Порядок в'їзду не важливий: той, хто повертає ліворуч, поступається зустрічним, що їдуть прямо чи праворуч.","ru":"Порядок въезда не важен: поворачивающий налево уступает встречным, едущим прямо или направо."}}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"left","label":"1","color":"red","me":true},{"arm":"N","move":"straight","label":"2","color":"green"}],"lights":[{"arm":"S","state":"green"},{"arm":"N","state":"green"}]}},"c":1,"e":{"uk":"Повертаючи ліворуч на зелений сигнал, водій дає дорогу зустрічним транспортним засобам, що рухаються прямо або праворуч, і трамваю попутного напрямку.","ru":"Поворачивая налево на зелёный сигнал, водитель уступает дорогу встречным транспортным средствам, движущимся прямо или направо, и трамваю попутного направления."},"ref":["16.6"],"id":"qc2565fad2"},{"t":"s16","q":{"uk":"Світлофор працює в режимі миготіння жовтого сигналу. Хто проїде перехрестя першим?","ru":"Светофор работает в режиме мигающего жёлтого сигнала. Кто проедет перекрёсток первым?"},"a":[{"uk":"Автомобіль 1","ru":"Автомобиль 1"},{"uk":"Автомобіль 2, бо він праворуч","ru":"Автомобиль 2, так как он справа","w":{"uk":"«Перешкода праворуч» діє лише між рівнозначними дорогами. Тут є знаки пріоритету, і автомобіль 2 стоїть перед «Дати дорогу».","ru":"«Помеха справа» действует только между равнозначными дорогами. Здесь есть знаки приоритета, и автомобиль 2 стоит перед «Уступить дорогу»."}}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"straight","label":"1","color":"red","me":true},{"arm":"E","move":"straight","label":"2","color":"blue"}],"lights":[{"arm":"S","state":"flash"},{"arm":"E","state":"flash"}],"signs":[{"arm":"S","code":"2.3"},{"arm":"E","code":"2.1"}]}},"c":0,"e":{"uk":"Миготливий жовтий означає, що перехрестя нерегульоване, тож діють знаки пріоритету. Автомобіль 1 на головній дорозі ({s:2.3}), автомобіль 2 — перед знаком {s:2.1}.","ru":"Мигающий жёлтый означает, что перекрёсток нерегулируемый, поэтому действуют знаки приоритета. Автомобиль 1 на главной дороге ({s:2.3}), автомобиль 2 — перед знаком {s:2.1}."},"ref":["16.1","16.11"],"id":"qa2200bfd6"},{"t":"s16","q":{"uk":"Чи діють знаки пріоритету на перехресті, де рух регулює працюючий світлофор?","ru":"Действуют ли знаки приоритета на перекрёстке, где движение регулирует работающий светофор?"},"a":[{"uk":"Так, вони мають перевагу над світлофором","ru":"Да, они имеют приоритет над светофором","w":{"uk":"Навпаки: світлофор має перевагу перед знаками пріоритету, і поки він працює, знаки не діють.","ru":"Наоборот: светофор имеет преимущество перед знаками приоритета, и пока он работает, знаки не действуют."}},{"uk":"Діють лише для поворотів ліворуч","ru":"Действуют только для поворотов налево","w":{"uk":"Таких винятків немає: на регульованому перехресті знаки пріоритету не діють зовсім.","ru":"Таких исключений нет: на регулируемом перекрёстке знаки приоритета не действуют вовсе."}},{"uk":"Ні, не діють","ru":"Нет, не действуют"}],"c":2,"e":{"uk":"Перехрестя, де черговість визначають світлофор або регулювальник, — регульоване. На ньому знаки пріоритету не діють. Вони потрібні, якщо світлофор вимкнеться або перейде на миготливий жовтий.","ru":"Перекрёсток, где очерёдность определяют светофор или регулировщик, — регулируемый. На нём знаки приоритета не действуют. Они нужны, если светофор выключится или перейдёт на мигающий жёлтый."},"ref":["16.1"],"id":"qd8ed205ae"},{"t":"s16","q":{"uk":"Кому надається перевага на перехресті з круговим рухом, позначеному цим знаком?","ru":"Кому предоставляется преимущество на перекрёстке с круговым движением, обозначенном этим знаком?"},"a":[{"uk":"Транспортним засобам, що в'їжджають на коло","ru":"Транспортным средствам, въезжающим на круг","w":{"uk":"На кільці зі знаком 4.10 навпаки: ті, хто в'їжджає, поступаються тим, хто вже рухається по колу.","ru":"На кольце со знаком 4.10 наоборот: въезжающие уступают тем, кто уже движется по кругу."}},{"uk":"Транспортним засобам, які вже рухаються по колу","ru":"Транспортным средствам, которые уже движутся по кругу"},{"uk":"Тим, хто наближається праворуч","ru":"Тем, кто приближается справа","w":{"uk":"«Перешкода праворуч» на кільці зі знаком 4.10 не діє: перевага в тих, хто вже на колі.","ru":"«Помеха справа» на кольце со знаком 4.10 не действует: преимущество у тех, кто уже на круге."}}],"img":{"sign":"4.10"},"c":1,"e":{"uk":"На перехрестях з круговим рухом, позначених знаком {s:4.10}, перевагу мають ті, хто вже рухається по колу. Правило «перешкода праворуч» тут не діє.","ru":"На перекрёстках с круговым движением, обозначенных знаком {s:4.10}, преимущество у тех, кто уже движется по кругу. Правило «помеха справа» здесь не действует."},"ref":["16.12"],"id":"q046aa3b33"},{"t":"s16","q":{"uk":"Головна дорога на перехресті змінює напрямок. Як мають роз'їжджатися між собою водії, що рухаються головною дорогою?","ru":"Главная дорога на перекрёстке меняет направление. Как должны разъезжаться между собой водители, движущиеся по главной дороге?"},"a":[{"uk":"Перевагу має той, хто їде прямо","ru":"Преимущество у того, кто едет прямо","w":{"uk":"Ні: між водіями на головній дорозі діють правила рівнозначних доріг, а не «хто прямо».","ru":"Нет: между водителями на главной дороге действуют правила равнозначных дорог, а не «кто прямо»."}},{"uk":"За правилами проїзду перехресть рівнозначних доріг","ru":"По правилам проезда перекрёстков равнозначных дорог"},{"uk":"Перевагу має той, хто повертає за головною дорогою","ru":"Преимущество у того, кто поворачивает по главной дороге","w":{"uk":"Ні: усі водії на головній між собою роз'їжджаються як на рівнозначних дорогах.","ru":"Нет: все водители на главной между собой разъезжаются как на равнозначных дорогах."}}],"img":{"signs":["2.3","7.8"]},"c":1,"e":{"uk":"Табличка {s:7.8} показує напрямок головної дороги. Водії на головній дорозі між собою керуються правилами для рівнозначних доріг («перешкода праворуч», поворот ліворуч поступається зустрічним). Так само між собою роз'їжджаються водії на другорядних дорогах.","ru":"Табличка {s:7.8} показывает направление главной дороги. Водители на главной дороге между собой руководствуются правилами для равнозначных дорог («помеха справа», поворот налево уступает встречным). Так же между собой разъезжаются водители на второстепенных дорогах."},"ref":["16.14"],"id":"qa78b2fde3"},{"t":"s16","q":{"uk":"Вночі на засніженій дорозі неможливо визначити, чи є покриття, а знаків пріоритету немає. Як має діяти водій на перехресті?","ru":"Ночью на заснеженной дороге невозможно определить наличие покрытия, а знаков приоритета нет. Как должен действовать водитель на перекрёстке?"},"a":[{"uk":"Вважати, що він на другорядній дорозі","ru":"Считать, что он на второстепенной дороге"},{"uk":"Вважати, що він на головній дорозі","ru":"Считать, что он на главной дороге","w":{"uk":"Навпаки: коли неможливо визначити покриття і знаків немає, безпечніше вважати себе на другорядній.","ru":"Наоборот: когда невозможно определить покрытие и знаков нет, безопаснее считать себя на второстепенной."}},{"uk":"Керуватися правилом «перешкода праворуч»","ru":"Руководствоваться правилом «помеха справа»","w":{"uk":"Правила вимагають вважати себе на другорядній дорозі, тобто пропускати всіх, а не лише тих, хто праворуч.","ru":"Правила требуют считать себя на второстепенной дороге, то есть пропускать всех, а не только тех, кто справа."}}],"c":0,"e":{"uk":"Якщо неможливо визначити наявність покриття (темрява, бруд, сніг), а знаків пріоритету немає, водій повинен вважати, що перебуває на другорядній дорозі, і пропускати всіх.","ru":"Если невозможно определить наличие покрытия (темнота, грязь, снег), а знаков приоритета нет, водитель должен считать, что находится на второстепенной дороге, и пропускать всех."},"ref":["16.15"],"id":"qec01abfe4"},{"t":"s16","q":{"uk":"Горить зелений сигнал, але за перехрестям утворився затор. Що має зробити водій?","ru":"Горит зелёный сигнал, но за перекрёстком образовался затор. Что должен сделать водитель?"},"a":[{"uk":"Виїхати на перехрестя, бо зелений сигнал дозволяє рух","ru":"Выехать на перекрёсток, так как зелёный сигнал разрешает движение","w":{"uk":"Зелений не дає права застрягти на перехресті й заблокувати рух. При заторі виїжджати заборонено.","ru":"Зелёный не даёт права застрять на перекрёстке и заблокировать движение. При заторе выезжать запрещено."}},{"uk":"Не виїжджати на перехрестя, якщо доведеться на ньому зупинитися й заважати іншим","ru":"Не выезжать на перекрёсток, если придётся на нём остановиться и мешать другим"},{"uk":"Виїхати й зупинитися в центрі перехрестя з аварійною сигналізацією","ru":"Выехать и остановиться в центре перекрёстка с аварийной сигнализацией","w":{"uk":"Зупинка на перехресті з аварійкою — пряме порушення: вона заблокує рух.","ru":"Остановка на перекрёстке с аварийкой — прямое нарушение: она заблокирует движение."}}],"c":1,"e":{"uk":"Заборонено виїжджати на будь-яке перехрестя, навіть на дозвільний сигнал, якщо через затор доведеться зупинитися на ньому і створити перешкоду іншим транспортним засобам та пішоходам.","ru":"Запрещено выезжать на любой перекрёсток, даже на разрешающий сигнал, если из-за затора придётся остановиться на нём и создать помеху другим транспортным средствам и пешеходам."},"ref":["16.4"],"id":"q0a6d7df88"},{"t":"s16","q":{"uk":"Водій повертає праворуч. Кому він зобов'язаний дати дорогу?","ru":"Водитель поворачивает направо. Кому он обязан уступить дорогу?"},"a":[{"uk":"Нікому, бо перехрестя нерегульоване","ru":"Никому, так как перекрёсток нерегулируемый","w":{"uk":"Пішоходів на дорозі, куди повертаєте, треба пропускати на будь-якому перехресті, регульованому чи ні.","ru":"Пешеходов на дороге, куда поворачиваете, нужно пропускать на любом перекрёстке, регулируемом или нет."}},{"uk":"Пішоходу, який переходить проїзну частину, на яку він повертає","ru":"Пешеходу, переходящему проезжую часть, на которую он поворачивает"},{"uk":"Пішоходу — лише якщо є розмітка «зебра»","ru":"Пешеходу — только если есть разметка «зебра»","w":{"uk":"Розмітка не потрібна: на перехресті межі переходу визначає ширина тротуарів. Пішохода треба пропустити.","ru":"Разметка не нужна: на перекрёстке границы перехода определяет ширина тротуаров. Пешехода нужно пропустить."}}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"right","label":"1","color":"red","me":true}],"peds":[{"arm":"E"}]}},"c":1,"e":{"uk":"Повертаючи праворуч або ліворуч, водій дає дорогу пішоходам, які переходять проїзну частину, на яку він повертає, а також велосипедистам, що рухаються прямо в попутному напрямку. На перехресті межі переходу без розмітки визначаються шириною тротуарів чи узбіч.","ru":"Поворачивая направо или налево, водитель уступает дорогу пешеходам, переходящим проезжую часть, на которую он поворачивает, а также велосипедистам, движущимся прямо в попутном направлении. На перекрёстке границы перехода без разметки определяются шириной тротуаров или обочин."},"ref":["16.2"],"id":"q8d6f43406"},{"t":"s16","q":{"uk":"Увімкнувся зелений сигнал. Що повинен зробити водій перед початком руху?","ru":"Включился зелёный сигнал. Что должен сделать водитель перед началом движения?"},"a":[{"uk":"Негайно рушити — він має перевагу","ru":"Немедленно начать движение — у него преимущество","w":{"uk":"Зелений не дає права наїхати на тих, хто ще завершує проїзд чи перехід. Їх треба пропустити.","ru":"Зелёный не даёт права наехать на тех, кто ещё завершает проезд или переход. Их нужно пропустить."}},{"uk":"Дати дорогу транспортним засобам, що завершують проїзд перехрестя, і пішоходам, які закінчують перехід","ru":"Уступить дорогу транспортным средствам, завершающим проезд перекрёстка, и пешеходам, заканчивающим переход"},{"uk":"Подати звуковий сигнал і рушати","ru":"Подать звуковой сигнал и начинать движение","w":{"uk":"Сигналити не можна: треба дочекатися, доки транспорт і пішоходи завершать рух.","ru":"Сигналить нельзя: нужно дождаться, пока транспорт и пешеходы завершат движение."}}],"c":1,"e":{"uk":"Дозвільний сигнал не скасовує обов'язку пропустити тих, хто ще завершує рух через перехрестя або перехід.","ru":"Разрешающий сигнал не отменяет обязанности пропустить тех, кто ещё завершает движение через перекрёсток или переход."},"ref":["16.5"],"id":"qcfba1f559"},{"t":"s16","q":{"uk":"Водій 1 повертає праворуч у напрямку зеленої стрілки додаткової секції, коли основний сигнал червоний. Хто проїде першим?","ru":"Водитель 1 поворачивает направо по зелёной стрелке дополнительной секции, когда основной сигнал красный. Кто проедет первым?"},"a":[{"uk":"Автомобіль 1, бо для нього горить стрілка","ru":"Автомобиль 1, так как для него горит стрелка","w":{"uk":"Стрілка разом із червоним дозволяє рух лише за умови, що ви пропустите тих, хто їде з інших напрямків.","ru":"Стрелка вместе с красным разрешает движение только при условии, что вы пропустите едущих с других направлений."}},{"uk":"Автомобіль 2","ru":"Автомобиль 2"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"right","label":"1","color":"red","me":true},{"arm":"W","move":"straight","label":"2","color":"blue"}],"lights":[{"arm":"S","state":"red","arrow":"right"},{"arm":"W","state":"green"}]}},"c":1,"e":{"uk":"Рухаючись у напрямку стрілки додаткової секції, увімкненої разом із червоним чи жовтим сигналом, водій дає дорогу транспортним засобам, що рухаються з інших напрямків.","ru":"Двигаясь по стрелке дополнительной секции, включённой вместе с красным или жёлтым сигналом, водитель уступает дорогу транспортным средствам, движущимся с других направлений."},"ref":["16.9"],"id":"q28a75804c"},{"t":"s16","q":{"uk":"Де повинен зупинитися водій, який надає перевагу транспортним засобам на перехрещуваній дорозі, якщо стоп-лінії немає?","ru":"Где должен остановиться водитель, предоставляющий преимущество транспортным средствам на пересекаемой дороге, если стоп-линии нет?"},"a":[{"uk":"Посередині перехрестя","ru":"Посередине перекрёстка","w":{"uk":"Зупинитися посеред перехрестя означає перекрити рух тим, кому ви поступаєтеся.","ru":"Остановиться посреди перекрёстка — значит перекрыть движение тем, кому вы уступаете."}},{"uk":"Біля знака «Дати дорогу», навіть якщо він за 50 м до перехрестя","ru":"У знака «Уступить дорогу», даже если он в 50 м до перекрёстка","w":{"uk":"Знак може стояти далеко від перехрестя. Зупинятися треба перед краєм перехрещуваної проїзної частини.","ru":"Знак может стоять далеко от перекрёстка. Останавливаться нужно перед краем пересекаемой проезжей части."}},{"uk":"Перед краєм перехрещуваної проїзної частини, не заважаючи пішоходам","ru":"Перед краем пересекаемой проезжей части, не мешая пешеходам"}],"c":2,"e":{"uk":"Водій зупиняється перед розміткою {m:1.12} (стоп-лінія) або {m:1.13}, перед світлофором так, щоб бачити його сигнали. Якщо їх немає — перед краєм перехрещуваної проїзної частини, не створюючи перешкод пішоходам.","ru":"Водитель останавливается перед разметкой {m:1.12} (стоп-линия) или {m:1.13}, перед светофором так, чтобы видеть его сигналы. Если их нет — перед краем пересекаемой проезжей части, не создавая помех пешеходам."},"ref":["16.3"],"id":"q04078e10d"},{"t":"s16","q":{"uk":"Водій виїхав на перехрестя на зелений сигнал. На виїзді з перехрестя для нього горить червоний, стоп-лінії та знака 5.69 немає. Як діяти?","ru":"Водитель выехал на перекрёсток на зелёный сигнал. На выезде с перекрёстка для него горит красный, стоп-линии и знака 5.69 нет. Как поступить?"},"a":[{"uk":"Виїхати з перехрестя в наміченому напрямку","ru":"Выехать с перекрёстка в намеченном направлении"},{"uk":"Зупинитися перед світлофором на виїзді","ru":"Остановиться перед светофором на выезде","w":{"uk":"Світлофор на виїзді не стосується того, хто вже в'їхав на перехрестя на зелений (якщо немає стоп-лінії чи знака 5.69).","ru":"Светофор на выезде не касается того, кто уже въехал на перекрёсток на зелёный (если нет стоп-линии или знака 5.69)."}},{"uk":"Зупинитися й увімкнути аварійну сигналізацію","ru":"Остановиться и включить аварийную сигнализацию","w":{"uk":"Зупинка посеред перехрестя створить затор і небезпеку. Треба виїхати в наміченому напрямку.","ru":"Остановка посреди перекрёстка создаст затор и опасность. Нужно выехать в намеченном направлении."}}],"c":0,"e":{"uk":"Водій, який виїхав на перехрестя на дозвільний сигнал, повинен виїхати в наміченому напрямку незалежно від сигналів світлофора на виїзді. Виняток — коли перед світлофором є стоп-лінія {m:1.12} або знак {s:5.69}.","ru":"Водитель, выехавший на перекрёсток на разрешающий сигнал, должен выехать в намеченном направлении независимо от сигналов светофора на выезде. Исключение — когда перед светофором есть стоп-линия {m:1.12} или знак {s:5.69}."},"ref":["16.8"],"id":"q0792f1411"},{"t":"s16","q":{"uk":"Хто першим проїде перехрестя?","ru":"Кто первым проедет перекрёсток?"},"a":[{"uk":"Автомобіль 1, потім 2 і 3","ru":"Автомобиль 1, затем 2 и 3","w":{"uk":"Автомобіль 1 стоїть перед «Дати дорогу» — він на другорядній і поступається обом.","ru":"Автомобиль 1 стоит перед «Уступить дорогу» — он на второстепенной и уступает обоим."}},{"uk":"Автомобілі 2 і 3 одночасно, потім автомобіль 1","ru":"Автомобили 2 и 3 одновременно, затем автомобиль 1"},{"uk":"Автомобіль 3, потім 1, потім 2","ru":"Автомобиль 3, затем 1, затем 2","w":{"uk":"Автомобіль 1 на другорядній має проїхати останнім. Автомобілі 2 і 3 їдуть головною прямо і один одному не заважають.","ru":"Автомобиль 1 на второстепенной должен проехать последним. Автомобили 2 и 3 едут по главной прямо и друг другу не мешают."}}],"img":{"scene":{"road":"T","cars":[{"arm":"S","move":"left","label":"1","color":"red","me":true},{"arm":"E","move":"straight","label":"2","color":"blue"},{"arm":"W","move":"straight","label":"3","color":"green"}],"signs":[{"arm":"S","code":"2.1"},{"arm":"E","code":"2.3"},{"arm":"W","code":"2.3"}]}},"c":1,"e":{"uk":"Автомобілі 2 і 3 рухаються головною дорогою назустріч один одному прямо — їхні траєкторії не перетинаються. Автомобіль 1 на другорядній дорозі ({s:2.1}) пропускає обох.","ru":"Автомобили 2 и 3 движутся по главной дороге навстречу друг другу прямо — их траектории не пересекаются. Автомобиль 1 на второстепенной дороге ({s:2.1}) пропускает обоих."},"ref":["16.11"],"id":"q3c18c2713"},{"t":"s16","q":{"uk":"Водій 1 повертає праворуч, водій 2 — ліворуч. Перехрестя рівнозначних доріг. Хто проїде першим?","ru":"Водитель 1 поворачивает направо, водитель 2 — налево. Перекрёсток равнозначных дорог. Кто проедет первым?"},"a":[{"uk":"Автомобіль 1","ru":"Автомобиль 1"},{"uk":"Автомобіль 2","ru":"Автомобиль 2","w":{"uk":"Водій 2 повертає ліворуч і зобов'язаний пропустити зустрічного, що повертає праворуч, тобто автомобіль 1.","ru":"Водитель 2 поворачивает налево и обязан пропустить встречного, поворачивающего направо, то есть автомобиль 1."}},{"uk":"Одночасно","ru":"Одновременно","w":{"uk":"Обидва виїжджають на одну дорогу, тож одночасно не вийде. Поворот ліворуч поступається повороту праворуч.","ru":"Оба выезжают на одну дорогу, поэтому одновременно не получится. Поворот налево уступает повороту направо."}}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"right","label":"1","color":"red","me":true},{"arm":"N","move":"left","label":"2","color":"blue"}]}},"c":0,"e":{"uk":"Обидва виїжджають на одну дорогу. Водій 2, повертаючи ліворуч, дає дорогу зустрічному транспорту, що рухається прямо або праворуч, тобто автомобілю 1.","ru":"Оба выезжают на одну дорогу. Водитель 2, поворачивая налево, уступает дорогу встречному транспорту, движущемуся прямо или направо, то есть автомобилю 1."},"ref":["16.13"],"id":"q87a13e0a6"},{"t":"s16","q":{"uk":"У якій послідовності автомобілі проїдуть перехрестя?","ru":"В какой последовательности автомобили проедут перекрёсток?"},"a":[{"uk":"1, 2, 3","ru":"1, 2, 3","w":{"uk":"Автомобіль 1 повертає ліворуч і має пропустити зустрічний автомобіль 2, який їде прямо головною.","ru":"Автомобиль 1 поворачивает налево и должен пропустить встречный автомобиль 2, который едет прямо по главной."}},{"uk":"2, 1, 3","ru":"2, 1, 3"},{"uk":"2, 3, 1","ru":"2, 3, 1","w":{"uk":"Автомобіль 3 на другорядній ({s:2.1}) пропускає всіх, хто на головній, тож проїжджає останнім.","ru":"Автомобиль 3 на второстепенной ({s:2.1}) пропускает всех, кто на главной, поэтому проезжает последним."}},{"uk":"3, 2, 1","ru":"3, 2, 1","w":{"uk":"Автомобіль 3 стоїть перед знаком «Дати дорогу» і не може їхати першим.","ru":"Автомобиль 3 стоит перед знаком «Уступить дорогу» и не может ехать первым."}}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"left","label":"1","color":"red","me":true},{"arm":"N","move":"straight","label":"2","color":"blue"},{"arm":"E","move":"straight","label":"3","color":"green"}],"signs":[{"arm":"S","code":"2.3"},{"arm":"N","code":"2.3"},{"arm":"E","code":"2.1"}]}},"c":1,"e":{"uk":"Автомобілі 1 і 2 — на головній дорозі, між собою вони роз'їжджаються як на рівнозначній: водій 1, повертаючи ліворуч, пропускає зустрічний автомобіль 2. Автомобіль 3 стоїть перед знаком {s:2.1} і пропускає обох.","ru":"Автомобили 1 и 2 — на главной дороге, между собой они разъезжаются как на равнозначной: водитель 1, поворачивая налево, пропускает встречный автомобиль 2. Автомобиль 3 стоит перед знаком {s:2.1} и пропускает обоих."},"ref":["16.11","16.13"],"id":"q25b862bbf"},{"t":"s16","q":{"uk":"Водіям 1 і 2 горить зелений, водію 3 — червоний. Хто проїде першим?","ru":"Водителям 1 и 2 горит зелёный, водителю 3 — красный. Кто проедет первым?"},"a":[{"uk":"Автомобіль 1","ru":"Автомобиль 1"},{"uk":"Автомобіль 2","ru":"Автомобиль 2","w":{"uk":"Водій 2 повертає ліворуч і пропускає зустрічний автомобіль 1, що їде прямо.","ru":"Водитель 2 поворачивает налево и пропускает встречный автомобиль 1, едущий прямо."}},{"uk":"Автомобіль 3, бо він праворуч","ru":"Автомобиль 3, так как он справа","w":{"uk":"Для автомобіля 3 горить червоний — він стоїть. «Перешкода праворуч» на регульованому перехресті не діє.","ru":"Для автомобиля 3 горит красный — он стоит. «Помеха справа» на регулируемом перекрёстке не действует."}}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"straight","label":"1","color":"red","me":true},{"arm":"N","move":"left","label":"2","color":"blue"},{"arm":"E","move":"straight","label":"3","color":"green"}],"lights":[{"arm":"S","state":"green"},{"arm":"N","state":"green"},{"arm":"E","state":"red"}]}},"c":0,"e":{"uk":"Автомобіль 3 стоїть на червоний. Водій 2 повертає ліворуч на зелений і пропускає зустрічний автомобіль 1, що їде прямо.","ru":"Автомобиль 3 стоит на красный. Водитель 2 поворачивает налево на зелёный и пропускает встречный автомобиль 1, едущий прямо."},"ref":["16.6"],"id":"q7490be4a4"},{"t":"s17","q":{"uk":"Кому, крім маршрутного транспорту, дозволено рухатися смугою, позначеною знаком 5.11?","ru":"Кому, кроме маршрутного транспорта, разрешено двигаться по полосе, обозначенной знаком 5.11?"},"a":[{"uk":"Нікому","ru":"Никому","w":{"uk":"Не лише маршрутним: смугою можуть їхати також таксі, мотоцикли без бокового причепа, мопеди й велосипеди.","ru":"Не только маршрутным: по полосе могут ехать также такси, мотоциклы без бокового прицепа, мопеды и велосипеды."}},{"uk":"Таксі, мотоциклам без бокового причепа, мопедам і велосипедистам","ru":"Такси, мотоциклам без бокового прицепа, мопедам и велосипедистам"},{"uk":"Усім легковим автомобілям","ru":"Всем легковым автомобилям","w":{"uk":"Звичайним легковим автомобілям рух і зупинка на цій смузі заборонені (крім таксі).","ru":"Обычным легковым автомобилям движение и остановка на этой полосе запрещены (кроме такси)."}}],"img":{"sign":"5.11"},"c":1,"e":{"uk":"На смузі для маршрутних транспортних засобів ({s:5.8}, {s:5.11}) заборонено рух і зупинку інших транспортних засобів, крім таксі, мопедів, мотоциклів без бокового причепа та велосипедистів.","ru":"На полосе для маршрутных транспортных средств ({s:5.8}, {s:5.11}) запрещены движение и остановка других транспортных средств, кроме такси, мопедов, мотоциклов без бокового прицепа и велосипедистов."},"ref":["17.1"],"id":"q70dd5452f"},{"t":"s17","q":{"uk":"Смуга для маршрутного транспорту відокремлена переривчастою лінією. Чи можна з неї повернути праворуч на легковому автомобілі?","ru":"Полоса для маршрутного транспорта отделена прерывистой линией. Можно ли с неё повернуть направо на легковом автомобиле?"},"a":[{"uk":"Так","ru":"Да"},{"uk":"Ні, поворот праворуч дозволено лише з сусідньої смуги","ru":"Нет, поворот направо разрешён только с соседней полосы","w":{"uk":"Якщо смуга відокремлена переривчастою лінією, Правила прямо дозволяють повертати праворуч з неї.","ru":"Если полоса отделена прерывистой линией, Правила прямо разрешают поворачивать направо с неё."}}],"c":0,"e":{"uk":"Якщо смуга для маршрутних транспортних засобів відокремлена переривчастою лінією, водій, який повертає праворуч, може виконувати поворот із цієї смуги. Так само на неї можна заїжджати під час виїзду на дорогу та для посадки чи висадки пасажирів біля правого краю.","ru":"Если полоса для маршрутных транспортных средств отделена прерывистой линией, водитель, поворачивающий направо, может выполнять поворот с этой полосы. Так же на неё можно заезжать при выезде на дорогу и для посадки или высадки пассажиров у правого края."},"ref":["17.2"],"id":"qb6175032c"},{"t":"s17","q":{"uk":"У населеному пункті автобус починає рух від зупинки в заїзному «кармані». Що має зробити водій легкового автомобіля?","ru":"В населённом пункте автобус начинает движение от остановки в заездном «кармане». Что должен сделать водитель легкового автомобиля?"},"a":[{"uk":"Продовжити рух, бо автобус виїжджає з прилеглої території","ru":"Продолжить движение, так как автобус выезжает с прилегающей территории","w":{"uk":"Зупинка в «кармані» — не прилегла територія. У місті автобусу треба дати можливість рушити.","ru":"Остановка в «кармане» — не прилегающая территория. В городе автобусу нужно дать возможность тронуться."}},{"uk":"Зменшити швидкість, а за потреби зупинитися, щоб автобус міг рушити","ru":"Снизить скорость, а при необходимости остановиться, чтобы автобус мог начать движение"},{"uk":"Подати звуковий сигнал","ru":"Подать звуковой сигнал","w":{"uk":"Сигнал нічого не дає: Правила вимагають пригальмувати і пропустити автобус.","ru":"Сигнал ничего не даёт: Правила требуют притормозить и пропустить автобус."}}],"c":1,"e":{"uk":"У населених пунктах водії зобов'язані дати можливість автобусу, мікроавтобусу чи тролейбусу рушити від позначеної зупинки в «кармані»: зменшити швидкість, а за потреби зупинитися.","ru":"В населённых пунктах водители обязаны дать возможность автобусу, микроавтобусу или троллейбусу начать движение от обозначенной остановки в «кармане»: снизить скорость, а при необходимости остановиться."},"ref":["17.4"],"id":"q8a6ecea13"},{"t":"s17","q":{"uk":"Поза перехрестям трамвайна колія перетинає смугу руху автомобілів. Хто має перевагу?","ru":"Вне перекрёстка трамвайные пути пересекают полосу движения автомобилей. У кого преимущество?"},"a":[{"uk":"Трамвай, крім випадків його виїзду з депо","ru":"Трамвай, кроме случаев его выезда из депо"},{"uk":"Автомобіль, що наближається праворуч","ru":"Автомобиль, приближающийся справа","w":{"uk":"«Перешкода праворуч» тут не діє: поза перехрестям трамвай, що перетинає вашу смугу, має перевагу.","ru":"«Помеха справа» здесь не действует: вне перекрёстка трамвай, пересекающий вашу полосу, имеет преимущество."}},{"uk":"Той, хто першим під'їхав","ru":"Тот, кто первым подъехал","w":{"uk":"Порядок під'їзду не важливий: перевага в трамвая (крім виїзду з депо).","ru":"Порядок подъезда не важен: преимущество у трамвая (кроме выезда из депо)."}}],"c":0,"e":{"uk":"Поза перехрестями, де трамвайні колії перетинають смугу нерейкових транспортних засобів, перевагу має трамвай (крім виїзду з депо).","ru":"Вне перекрёстков, где трамвайные пути пересекают полосу нерельсовых транспортных средств, преимущество имеет трамвай (кроме выезда из депо)."},"ref":["17.3"],"id":"qd3bcfd514"},{"t":"s18","q":{"uk":"Водій наближається до нерегульованого пішохідного переходу, на якому є пішохід. Як він повинен діяти?","ru":"Водитель приближается к нерегулируемому пешеходному переходу, на котором есть пешеход. Как он должен действовать?"},"a":[{"uk":"Подати звуковий сигнал і проїхати перед пішоходом","ru":"Подать звуковой сигнал и проехать перед пешеходом","w":{"uk":"На нерегульованому переході пішохід має перевагу. Сигналити й проїжджати перед ним не можна.","ru":"На нерегулируемом переходе у пешехода преимущество. Сигналить и проезжать перед ним нельзя."}},{"uk":"Зменшити швидкість, а за потреби зупинитися, щоб дати дорогу пішоходу","ru":"Снизить скорость, а при необходимости остановиться, чтобы уступить дорогу пешеходу"},{"uk":"Проїхати, якщо пішохід ще не дійшов до його смуги","ru":"Проехать, если пешеход ещё не дошёл до его полосы","w":{"uk":"Навіть якщо пішохід ще далеко від вашої смуги, водій зобов'язаний пригальмувати і за потреби зупинитися.","ru":"Даже если пешеход ещё далеко от вашей полосы, водитель обязан притормозить и при необходимости остановиться."}}],"img":{"scene":{"road":"straight","lanes":1,"center":"dashed","zebra":200,"cars":[{"x":90,"dir":"E","lane":0,"move":"straight","label":"1","color":"red","me":true}],"peds":[{"x":200,"y":140}]}},"c":1,"e":{"uk":"Наближаючись до нерегульованого переходу з пішоходами, водій зменшує швидкість, а за потреби зупиняється, щоб дати дорогу пішоходам, яким може бути створено перешкоду чи небезпеку.","ru":"Приближаясь к нерегулируемому переходу с пешеходами, водитель снижает скорость, а при необходимости останавливается, чтобы уступить дорогу пешеходам, которым может быть создана помеха или опасность."},"ref":["18.1"],"id":"q0ced9bd7e"},{"t":"s18","q":{"uk":"Перед нерегульованим пішохідним переходом на сусідній смузі зупинився автомобіль. Що робити водію 1?","ru":"Перед нерегулируемым пешеходным переходом на соседней полосе остановился автомобиль. Что делать водителю 1?"},"a":[{"uk":"Продовжити рух, бо його смуга вільна","ru":"Продолжить движение, так как его полоса свободна","w":{"uk":"Сусідній автомобіль міг зупинитися через пішохода, якого ви не бачите. Їхати можна, лише переконавшись, що переход вільний.","ru":"Соседний автомобиль мог остановиться из-за пешехода, которого вы не видите. Ехать можно, только убедившись, что переход свободен."}},{"uk":"Зменшити швидкість, а за потреби зупинитися і рушати, лише переконавшись, що на переході немає пішоходів","ru":"Снизить скорость, а при необходимости остановиться и ехать, только убедившись, что на переходе нет пешеходов"},{"uk":"Об'їхати автомобіль 2 і подати звуковий сигнал","ru":"Объехать автомобиль 2 и подать звуковой сигнал","w":{"uk":"Об'їжджати автомобіль, що зупинився перед переходом, небезпечно: за ним може бути пішохід.","ru":"Объезжать автомобиль, остановившийся перед переходом, опасно: за ним может быть пешеход."}}],"img":{"scene":{"road":"straight","lanes":2,"center":"solid","zebra":215,"cars":[{"x":180,"dir":"E","lane":0,"label":"2","color":"blue"},{"x":90,"dir":"E","lane":1,"move":"straight","label":"1","color":"red","me":true}]}},"c":1,"e":{"uk":"Якщо перед нерегульованим переходом зупинився або гальмує транспортний засіб, водії на сусідніх смугах зменшують швидкість, за потреби зупиняються і продовжують рух, лише переконавшись, що на переході немає пішоходів.","ru":"Если перед нерегулируемым переходом остановилось или тормозит транспортное средство, водители на соседних полосах снижают скорость, при необходимости останавливаются и продолжают движение, только убедившись, что на переходе нет пешеходов."},"ref":["18.4"],"id":"q788ab9952"},{"t":"s18","q":{"uk":"Кого водій зобов'язаний пропустити в будь-якому місці, навіть поза переходом?","ru":"Кого водитель обязан пропустить в любом месте, даже вне перехода?"},"a":[{"uk":"Дітей","ru":"Детей","w":{"uk":"До дітей водій має бути особливо уважним, але обов'язок пропустити будь-де стосується людей із білою тростиною.","ru":"К детям водитель должен быть особенно внимателен, но обязанность пропустить где угодно касается людей с белой тростью."}},{"uk":"Пішоходів з порушенням зору, які подають сигнал білою тростиною, спрямованою вперед","ru":"Пешеходов с нарушением зрения, подающих сигнал белой тростью, направленной вперёд"},{"uk":"Людей похилого віку","ru":"Пожилых людей","w":{"uk":"До людей похилого віку теж треба бути уважним, але безумовно пропускати будь-де — людей з білою тростиною.","ru":"К пожилым тоже нужно быть внимательным, но безусловно пропускать где угодно — людей с белой тростью."}}],"c":1,"e":{"uk":"У будь-якому місці водій повинен пропустити пішоходів з порушенням зору, які подають сигнал тростиною білого кольору, спрямованою вперед.","ru":"В любом месте водитель должен пропустить пешеходов с нарушением зрения, подающих сигнал тростью белого цвета, направленной вперёд."},"ref":["18.5"],"id":"q7983c8105"},{"t":"s18","q":{"uk":"Трамвай стоїть на зупинці без посадкового майданчика, двері відчинені, люди йдуть до нього проїзною частиною. Що повинен зробити водій?","ru":"Трамвай стоит на остановке без посадочной площадки, двери открыты, люди идут к нему по проезжей части. Что должен сделать водитель?"},"a":[{"uk":"Зупинитися й продовжити рух, коли пішоходи залишать проїзну частину і двері трамвая зачиняться","ru":"Остановиться и продолжить движение, когда пешеходы покинут проезжую часть и двери трамвая закроются"},{"uk":"Об'їхати трамвай ліворуч","ru":"Объехать трамвай слева","w":{"uk":"Об'їжджати трамвай ліворуч не можна — це виїзд на зустрічну колію, до того ж там можуть бути пасажири.","ru":"Объезжать трамвай слева нельзя — это выезд на встречные пути, к тому же там могут быть пассажиры."}},{"uk":"Проїхати з мінімальною швидкістю","ru":"Проехать с минимальной скоростью","w":{"uk":"Повільна швидкість не замінює зупинки: треба стояти, доки люди не залишать проїзну частину.","ru":"Малая скорость не заменяет остановки: нужно стоять, пока люди не покинут проезжую часть."}}],"c":0,"e":{"uk":"Водій зупиняється, щоб дати дорогу пішоходам, що йдуть до трамвая або від нього з боку відчинених дверей. Рушати можна лише коли пішоходи залишать проїзну частину і двері трамвая зачиняться.","ru":"Водитель останавливается, чтобы уступить дорогу пешеходам, идущим к трамваю или от него со стороны открытых дверей. Ехать можно только когда пешеходы покинут проезжую часть и двери трамвая закроются."},"ref":["18.8"],"id":"qaea3ab77b"},{"t":"s18","q":{"uk":"За пішохідним переходом утворився затор. Чи можна в'їхати на перехід?","ru":"За пешеходным переходом образовался затор. Можно ли въехать на переход?"},"a":[{"uk":"Так, якщо на переході немає пішоходів","ru":"Да, если на переходе нет пешеходов","w":{"uk":"Навіть без пішоходів зупинятися на переході заборонено: ви заблокуєте його для інших.","ru":"Даже без пешеходов останавливаться на переходе запрещено: вы заблокируете его для других."}},{"uk":"Ні, якщо доведеться зупинитися на переході","ru":"Нет, если придётся остановиться на переходе"},{"uk":"Так, на зелений сигнал світлофора","ru":"Да, на зелёный сигнал светофора","w":{"uk":"Зелений не дає права залишитися на переході. Якщо попереду затор, чекайте перед переходом.","ru":"Зелёный не даёт права остаться на переходе. Если впереди затор, ждите перед переходом."}}],"c":1,"e":{"uk":"Заборонено в'їжджати на пішохідний перехід, якщо за ним затор, через який доведеться зупинитися на переході.","ru":"Запрещено въезжать на пешеходный переход, если за ним затор, из-за которого придётся остановиться на переходе."},"ref":["18.6"],"id":"q07b6d0846"},{"t":"s18","q":{"uk":"Автобус зі знаком «Діти» зупинився з увімкненими оранжевими маячками. Що повинен зробити водій на сусідній смузі?","ru":"Автобус со знаком «Дети» остановился с включёнными оранжевыми маячками. Что должен сделать водитель на соседней полосе?"},"a":[{"uk":"Продовжити рух з тією ж швидкістю","ru":"Продолжить движение с той же скоростью","w":{"uk":"З автобуса можуть вибігти діти. Треба знизити швидкість, а за потреби зупинитися.","ru":"Из автобуса могут выбежать дети. Нужно снизить скорость, а при необходимости остановиться."}},{"uk":"Зменшити швидкість, а за потреби зупинитися, щоб не наїхати на дітей","ru":"Снизить скорость, а при необходимости остановиться, чтобы не наехать на детей"},{"uk":"Обов'язково зупинитися і чекати, доки автобус рушить","ru":"Обязательно остановиться и ждать, пока автобус начнёт движение","w":{"uk":"Чекати, доки автобус рушить, не обов'язково: вимога — знизити швидкість і зупинитися, якщо є небезпека.","ru":"Ждать, пока автобус тронется, не обязательно: требование — снизить скорость и остановиться, если есть опасность."}}],"c":1,"e":{"uk":"Наближаючись до транспортного засобу зі знаком «Діти», що зупинився з оранжевими маячками або аварійною сигналізацією, водії на суміжній смузі зменшують швидкість, а за потреби зупиняються.","ru":"Приближаясь к транспортному средству со знаком «Дети», остановившемуся с оранжевыми маячками или аварийной сигнализацией, водители на смежной полосе снижают скорость, а при необходимости останавливаются."},"ref":["18.9"],"id":"q053cad3c1"},{"t":"s18","q":{"uk":"На регульованому переході для автомобілів увімкнувся зелений, але пішохід ще не закінчив перехід. Як діяти?","ru":"На регулируемом переходе для автомобилей включился зелёный, но пешеход ещё не закончил переход. Как поступить?"},"a":[{"uk":"Дати дорогу пішоходу, який закінчує перехід","ru":"Уступить дорогу пешеходу, который заканчивает переход"},{"uk":"Рушати, бо зелений дає перевагу","ru":"Начинать движение, так как зелёный даёт преимущество","w":{"uk":"Зелений не дає переваги над пішоходом, що закінчує перехід. Його треба пропустити.","ru":"Зелёный не даёт преимущества перед пешеходом, заканчивающим переход. Его нужно пропустить."}},{"uk":"Подати звуковий сигнал, щоб пішохід поквапився","ru":"Подать звуковой сигнал, чтобы пешеход поторопился","w":{"uk":"Підганяти пішохода сигналом заборонено. Треба дочекатися, доки він завершить перехід.","ru":"Подгонять пешехода сигналом запрещено. Нужно дождаться, пока он завершит переход."}}],"c":0,"e":{"uk":"На дозвільний сигнал водій дає дорогу пішоходам, які закінчують перехід проїзної частини відповідного напрямку.","ru":"На разрешающий сигнал водитель уступает дорогу пешеходам, которые заканчивают переход проезжей части соответствующего направления."},"ref":["18.2"],"id":"q8b7824f5d"},{"t":"s19","q":{"uk":"На якій відстані до зустрічного транспортного засобу слід перемкнути дальнє світло на ближнє?","ru":"На каком расстоянии до встречного транспортного средства следует переключить дальний свет на ближний?"},"a":[{"uk":"Не менш як за 100 м","ru":"Не менее чем за 100 м","w":{"uk":"100 м — замало: зустрічного водія вже засліпить. Перемикайте не менш як за 250 м.","ru":"100 м — мало: встречного водителя уже ослепит. Переключайте не менее чем за 250 м."}},{"uk":"Не менш як за 150 м","ru":"Не менее чем за 150 м","w":{"uk":"150 м — замало: Правила вимагають не менш як 250 м.","ru":"150 м — мало: Правила требуют не менее 250 м."}},{"uk":"Не менш як за 250 м","ru":"Не менее чем за 250 м"},{"uk":"Не менш як за 500 м","ru":"Не менее чем за 500 м","w":{"uk":"Перемкнути за 500 м можна, але мінімальна норма — 250 м.","ru":"Переключить за 500 м можно, но минимальная норма — 250 м."}}],"c":2,"e":{"uk":"Дальнє світло перемикають на ближнє не менш як за 250 м до зустрічного транспортного засобу, а також коли воно може засліпити водіїв попутного напрямку. Якщо зустрічний водій блимає фарами — перемкніть раніше.","ru":"Дальний свет переключают на ближний не менее чем за 250 м до встречного транспортного средства, а также когда он может ослепить водителей попутного направления. Если встречный водитель мигает фарами — переключите раньше."},"ref":["19.2"],"id":"q32e5889b2"},{"t":"s19","q":{"uk":"Вас засліпили фари зустрічного автомобіля. Що треба зробити?","ru":"Вас ослепили фары встречного автомобиля. Что нужно сделать?"},"a":[{"uk":"Увімкнути дальнє світло у відповідь","ru":"Включить дальний свет в ответ","w":{"uk":"Засліплювати у відповідь небезпечно й заборонено. Треба зупинитися у своїй смузі.","ru":"Ослеплять в ответ опасно и запрещено. Нужно остановиться в своей полосе."}},{"uk":"Перестроїтися на праве узбіччя і продовжити рух","ru":"Перестроиться на правую обочину и продолжить движение","w":{"uk":"Засліплений водій не бачить узбіччя: перестроюватися заборонено. Треба зупинитися, не змінюючи смуги.","ru":"Ослеплённый водитель не видит обочину: перестраиваться запрещено. Нужно остановиться, не меняя полосы."}},{"uk":"Не змінюючи смуги, зупинитися і увімкнути аварійну сигналізацію","ru":"Не меняя полосы, остановиться и включить аварийную сигнализацию"}],"c":2,"e":{"uk":"У разі засліплення водій зупиняється, не змінюючи смуги руху, і вмикає аварійну сигналізацію. Рушати можна, коли мине дія засліплення.","ru":"При ослеплении водитель останавливается, не меняя полосы движения, и включает аварийную сигнализацию. Начинать движение можно, когда пройдёт действие ослепления."},"ref":["19.3"],"id":"qe246a629b"},{"t":"s19","q":{"uk":"Які світлові прилади мають бути ввімкнені на легковому автомобілі під час руху в тунелі вдень?","ru":"Какие световые приборы должны быть включены на легковом автомобиле при движении в тоннеле днём?"},"a":[{"uk":"Жодні, якщо тунель освітлений","ru":"Никакие, если тоннель освещён","w":{"uk":"У тунелі фари обов'язкові незалежно від освітлення.","ru":"В тоннеле фары обязательны независимо от освещения."}},{"uk":"Фари ближнього (дальнього) світла","ru":"Фары ближнего (дальнего) света"},{"uk":"Лише габаритні вогні","ru":"Только габаритные огни","w":{"uk":"Габарити не замінюють фар: у тунелі мають горіти ближнє або дальнє світло.","ru":"Габариты не заменяют фар: в тоннеле должен гореть ближний или дальний свет."}}],"c":1,"e":{"uk":"У темну пору доби, за недостатньої видимості та в тунелях (незалежно від освітлення) на механічних транспортних засобах мають бути ввімкнені фари ближнього або дальнього світла.","ru":"В тёмное время суток, при недостаточной видимости и в тоннелях (независимо от освещения) на механических транспортных средствах должны быть включены фары ближнего или дальнего света."},"ref":["19.1"],"id":"q800a036e6"},{"t":"s19","q":{"uk":"Чи можна в темну пору доби на неосвітленій дорозі їхати лише з протитуманними фарами?","ru":"Можно ли в тёмное время суток на неосвещённой дороге ехать только с противотуманными фарами?"},"a":[{"uk":"Ні, лише разом із ближнім або дальнім світлом","ru":"Нет, только вместе с ближним или дальним светом"},{"uk":"Так","ru":"Да","w":{"uk":"На неосвітленій дорозі вночі протитуманні фари дозволено лише разом із ближнім чи дальнім світлом.","ru":"На неосвещённой дороге ночью противотуманные фары разрешены только вместе с ближним или дальним светом."}},{"uk":"Так, якщо швидкість не перевищує 50 км/год","ru":"Да, если скорость не превышает 50 км/ч","w":{"uk":"Швидкість не має значення: вночі на неосвітленій дорозі протитуманні — лише разом із фарами.","ru":"Скорость не имеет значения: ночью на неосвещённой дороге противотуманные — только вместе с фарами."}}],"c":0,"e":{"uk":"Протитуманні фари використовують за недостатньої видимості окремо або разом із ближнім чи дальнім світлом, а в темну пору на неосвітлених ділянках — лише разом із ближнім або дальнім.","ru":"Противотуманные фары используют при недостаточной видимости отдельно или вместе с ближним либо дальним светом, а в тёмное время на неосвещённых участках — только вместе с ближним или дальним."},"ref":["19.5"],"id":"q52c47dae3"},{"t":"s19","q":{"uk":"Коли можна вмикати задній протитуманний ліхтар?","ru":"Когда можно включать задний противотуманный фонарь?"},"a":[{"uk":"У темну пору доби завжди","ru":"В тёмное время суток всегда","w":{"uk":"Задній протитуманний сліпить тих, хто позаду. Його вмикають лише за поганої видимості, а не будь-якої ночі.","ru":"Задний противотуманный слепит едущих сзади. Его включают только при плохой видимости, а не любой ночью."}},{"uk":"Лише в умовах недостатньої видимості, вдень і вночі","ru":"Только в условиях недостаточной видимости, днём и ночью"},{"uk":"Під час буксирування","ru":"При буксировке","w":{"uk":"Буксирування не є підставою: задній протитуманний — лише за недостатньої видимості.","ru":"Буксировка не является основанием: задний противотуманный — только при недостаточной видимости."}}],"c":1,"e":{"uk":"Задній протитуманний ліхтар дозволено використовувати виключно в умовах недостатньої видимості (туман, сильний дощ, снігопад) — як удень, так і вночі.","ru":"Задний противотуманный фонарь разрешено использовать исключительно в условиях недостаточной видимости (туман, сильный дождь, снегопад) — как днём, так и ночью."},"ref":["19.9"],"id":"q16a208821"},{"t":"s19","q":{"uk":"Які світлові прилади повинні бути ввімкнені під час зупинки на дорозі в темну пору доби?","ru":"Какие световые приборы должны быть включены во время остановки на дороге в тёмное время суток?"},"a":[{"uk":"Габаритні або стоянкові ліхтарі, а за вимушеної зупинки — ще й аварійна сигналізація","ru":"Габаритные или стояночные огни, а при вынужденной остановке — ещё и аварийная сигнализация"},{"uk":"Лише аварійна сигналізація","ru":"Только аварийная сигнализация","w":{"uk":"За звичайної зупинки вмикають габарити. Аварійку додають лише за вимушеної зупинки.","ru":"При обычной остановке включают габариты. Аварийку добавляют только при вынужденной остановке."}},{"uk":"Ближнє світло фар","ru":"Ближний свет фар","w":{"uk":"Ближнє світло на стоянці не обов'язкове і може засліплювати. Потрібні габаритні або стоянкові ліхтарі.","ru":"Ближний свет на стоянке не обязателен и может ослеплять. Нужны габаритные или стояночные огни."}}],"c":0,"e":{"uk":"Під час зупинки в темряві чи за недостатньої видимості вмикають габаритні або стоянкові ліхтарі; за вимушеної зупинки — додатково аварійну світлову сигналізацію.","ru":"Во время остановки в темноте или при недостаточной видимости включают габаритные или стояночные огни; при вынужденной остановке — дополнительно аварийную световую сигнализацию."},"ref":["19.4"],"id":"q0b4fe4624"},{"t":"s19","q":{"uk":"Що можна ввімкнути замість ближнього світла в умовах недостатньої видимості (туман)?","ru":"Что можно включить вместо ближнего света в условиях недостаточной видимости (туман)?"},"a":[{"uk":"Лише габаритні вогні","ru":"Только габаритные огни","w":{"uk":"Габарити не освітлюють дорогу. Замість фар можна ввімкнути протитуманні фари.","ru":"Габариты не освещают дорогу. Вместо фар можно включить противотуманные фары."}},{"uk":"Протитуманні фари","ru":"Противотуманные фары"},{"uk":"Денні ходові вогні","ru":"Дневные ходовые огни","w":{"uk":"Денні ходові вогні не замінюють ближнього світла в тумані. Правила дозволяють замість нього протитуманні фари.","ru":"Дневные ходовые огни не заменяют ближний свет в тумане. Правила разрешают вместо него противотуманные фары."}}],"c":1,"e":{"uk":"В умовах недостатньої видимості на механічних транспортних засобах дозволено замість фар ближнього (дальнього) світла ввімкнути протитуманні фари.","ru":"В условиях недостаточной видимости на механических транспортных средствах разрешено вместо фар ближнего (дальнего) света включить противотуманные фары."},"ref":["19.1"],"id":"q433ca08c6"},{"t":"s20","q":{"uk":"Де треба зупинитися перед залізничним переїздом, якщо шлагбаума, світлофора, стоп-лінії та знака 2.2 немає, а наближається поїзд?","ru":"Где нужно остановиться перед железнодорожным переездом, если шлагбаума, светофора, стоп-линии и знака 2.2 нет, а приближается поезд?"},"a":[{"uk":"Не ближче 5 м до рейки","ru":"Не ближе 5 м до рельса","w":{"uk":"5 м — замало: Правила вимагають не ближче 10 м до найближчої рейки.","ru":"5 м — мало: Правила требуют не ближе 10 м до ближайшего рельса."}},{"uk":"Не ближче 10 м до найближчої рейки","ru":"Не ближе 10 м до ближайшего рельса"},{"uk":"Не ближче 50 м до переїзду","ru":"Не ближе 50 м до переезда","w":{"uk":"50 м — норма для стоянки біля переїзду. Перед поїздом зупиняються не ближче 10 м до рейки.","ru":"50 м — норма для стоянки у переезда. Перед поездом останавливаются не ближе 10 м до рельса."}}],"c":1,"e":{"uk":"Водій зупиняється перед стоп-лінією, знаком {s:2.2}, шлагбаумом чи світлофором, а якщо їх немає — не ближче 10 м до найближчої рейки.","ru":"Водитель останавливается перед стоп-линией, знаком {s:2.2}, шлагбаумом или светофором, а если их нет — не ближе 10 м до ближайшего рельса."},"ref":["20.3"],"id":"qc10960383"},{"t":"s20","q":{"uk":"Шлагбаум почав підніматися, але світлофор на переїзді ще показує заборонний сигнал. Чи можна рушати?","ru":"Шлагбаум начал подниматься, но светофор на переезде ещё показывает запрещающий сигнал. Можно ли начинать движение?"},"a":[{"uk":"Так, шлагбаум має перевагу","ru":"Да, шлагбаум имеет преимущество","w":{"uk":"Шлагбаум не головніший за світлофор: поки горить заборонний сигнал, їхати не можна.","ru":"Шлагбаум не главнее светофора: пока горит запрещающий сигнал, ехать нельзя."}},{"uk":"Ні, заборонний сигнал світлофора діє незалежно від положення шлагбаума","ru":"Нет, запрещающий сигнал светофора действует независимо от положения шлагбаума"}],"c":1,"e":{"uk":"Рух через переїзд заборонено, якщо ввімкнено заборонний сигнал світлофора чи звуковий сигнал, незалежно від наявності та положення шлагбаума.","ru":"Движение через переезд запрещено, если включён запрещающий сигнал светофора или звуковой сигнал, независимо от наличия и положения шлагбаума."},"ref":["20.5"],"id":"qc9489c6c6"},{"t":"s20","q":{"uk":"У якому з випадків рух через залізничний переїзд заборонено?","ru":"В каком из случаев движение через железнодорожный переезд запрещено?"},"a":[{"uk":"Шлагбаум почав опускатися","ru":"Шлагбаум начал опускаться","w":{"uk":"Правильно, але неповно: рух заборонено також при заторі за переїздом і коли видно поїзд.","ru":"Верно, но неполно: движение запрещено также при заторе за переездом и когда виден поезд."}},{"uk":"За переїздом затор, через який доведеться зупинитися на переїзді","ru":"За переездом затор, из-за которого придётся остановиться на переезде","w":{"uk":"Правильно, але неповно: рух заборонено й тоді, коли шлагбаум опускається чи видно поїзд.","ru":"Верно, но неполно: движение запрещено и тогда, когда шлагбаум опускается или виден поезд."}},{"uk":"У межах видимості наближається поїзд","ru":"В пределах видимости приближается поезд","w":{"uk":"Правильно, але неповно: інші названі випадки теж забороняють рух.","ru":"Верно, но неполно: другие названные случаи тоже запрещают движение."}},{"uk":"У всіх перелічених випадках","ru":"Во всех перечисленных случаях"}],"c":3,"e":{"uk":"Рух через переїзд заборонено, якщо черговий подає сигнал заборони, шлагбаум опущений чи опускається, горить заборонний сигнал, за переїздом затор або наближається поїзд.","ru":"Движение через переезд запрещено, если дежурный подаёт сигнал запрещения, шлагбаум опущен или опускается, горит запрещающий сигнал, за переездом затор или приближается поезд."},"ref":["20.5"],"id":"q29ca2d32a"},{"t":"s20","q":{"uk":"Як рухатися через переїзд, якщо немає розмітки чи знаків, що визначають кількість смуг?","ru":"Как двигаться через переезд, если нет разметки или знаков, определяющих количество полос?"},"a":[{"uk":"Лише в один ряд","ru":"Только в один ряд"},{"uk":"Не більше ніж у два ряди","ru":"Не более чем в два ряда","w":{"uk":"Без розмітки чи знаків рядність не визначена, тому дозволено лише один ряд.","ru":"Без разметки или знаков рядность не определена, поэтому разрешён только один ряд."}},{"uk":"Будь-якою кількістю рядів","ru":"Любым количеством рядов","w":{"uk":"Ні: без розмітки чи знаків через переїзд їдуть лише в один ряд.","ru":"Нет: без разметки или знаков через переезд едут только в один ряд."}}],"c":0,"e":{"uk":"Якщо перед переїздом немає розмітки чи знаків, які визначають кількість смуг, рух через нього дозволено лише в один ряд.","ru":"Если перед переездом нет разметки или знаков, определяющих количество полос, движение через него разрешено только в один ряд."},"ref":["20.4"],"id":"q13687d6f0"},{"t":"s20","q":{"uk":"Перед закритим переїздом стоїть черга автомобілів. Чи можна їх об'їхати?","ru":"Перед закрытым переездом стоит очередь автомобилей. Можно ли их объехать?"},"a":[{"uk":"Так, якщо зустрічна смуга вільна","ru":"Да, если встречная полоса свободна","w":{"uk":"Вільна зустрічна нічого не змінює: об'їжджати черги перед закритим переїздом заборонено.","ru":"Свободная встречная ничего не меняет: объезжать очередь перед закрытым переездом запрещено."}},{"uk":"Ні","ru":"Нет"},{"uk":"Так, щоб стати першим перед шлагбаумом","ru":"Да, чтобы встать первым перед шлагбаумом","w":{"uk":"Саме для цього об'їжджати й заборонено: черга перед переїздом не повинна перетворюватися на кілька рядів.","ru":"Именно поэтому объезжать и запрещено: очередь перед переездом не должна превращаться в несколько рядов."}}],"c":1,"e":{"uk":"Заборонено самовільно відкривати чи об'їжджати шлагбаум, а також об'їжджати транспортні засоби, що стоять перед переїздом, коли рух через нього заборонено.","ru":"Запрещено самовольно открывать или объезжать шлагбаум, а также объезжать транспортные средства, стоящие перед переездом, когда движение через него запрещено."},"ref":["20.7"],"id":"qb7301214b"},{"t":"s20","q":{"uk":"Автомобіль заглух на переїзді, звільнити переїзд не вдається. Що є сигналом загальної тривоги?","ru":"Автомобиль заглох на переезде, освободить переезд не удаётся. Что является сигналом общей тревоги?"},"a":[{"uk":"Безперервний звуковий сигнал","ru":"Непрерывный звуковой сигнал","w":{"uk":"Безперервний сигнал не є сигналом загальної тривоги. Правила визначають серію: один довгий і три короткі.","ru":"Непрерывный сигнал не является сигналом общей тревоги. Правила определяют серию: один длинный и три коротких."}},{"uk":"Серії з одного довгого і трьох коротких звукових сигналів","ru":"Серии из одного длинного и трёх коротких звуковых сигналов"},{"uk":"Три довгі звукові сигнали","ru":"Три длинных звуковых сигнала","w":{"uk":"Ні, сигнал тривоги — один довгий і три короткі.","ru":"Нет, сигнал тревоги — один длинный и три коротких."}}],"c":1,"e":{"uk":"Сигнал загальної тривоги — серії звукових сигналів: один довгий і три короткі. Сигнал зупинки поїзда — круговий рух руки (вдень з яскравою тканиною, вночі з ліхтарем чи факелом).","ru":"Сигнал общей тревоги — серии звуковых сигналов: один длинный и три коротких. Сигнал остановки поезда — круговое движение руки (днём с яркой тканью, ночью с фонарём или факелом)."},"ref":["20.9"],"id":"q76f5009d3"},{"t":"s20","q":{"uk":"Автомобіль вимушено зупинився на переїзді. Що водій повинен зробити насамперед?","ru":"Автомобиль вынужденно остановился на переезде. Что водитель должен сделать в первую очередь?"},"a":[{"uk":"Негайно висадити людей і вжити заходів для звільнення переїзду","ru":"Немедленно высадить людей и принять меры для освобождения переезда"},{"uk":"Увімкнути аварійну сигналізацію й чекати допомоги в салоні","ru":"Включить аварийную сигнализацию и ждать помощи в салоне","w":{"uk":"Залишатися в салоні на переїзді смертельно небезпечно. Спершу висаджують людей і звільняють переїзд.","ru":"Оставаться в салоне на переезде смертельно опасно. Сначала высаживают людей и освобождают переезд."}},{"uk":"Зателефонувати в поліцію","ru":"Позвонить в полицию","w":{"uk":"Дзвінок не врятує від поїзда. Спершу висадити людей і звільнити переїзд.","ru":"Звонок не спасёт от поезда. Сначала высадить людей и освободить переезд."}}],"c":0,"e":{"uk":"Водій негайно висаджує людей і звільняє переїзд. Якщо не вдається — за можливості посилає двох людей уздовж колій в обидва боки не менш як на 1000 м, сам залишається біля машини й подає сигнали загальної тривоги, а побачивши поїзд, біжить йому назустріч, подаючи сигнал зупинки.","ru":"Водитель немедленно высаживает людей и освобождает переезд. Если не удаётся — по возможности посылает двух человек вдоль путей в обе стороны не менее чем на 1000 м, сам остаётся у машины и подаёт сигналы общей тревоги, а увидев поезд, бежит ему навстречу, подавая сигнал остановки."},"ref":["20.8"],"id":"q9e83490cd"},{"t":"s20","q":{"uk":"На яку відстань від переїзду треба послати людей уздовж колій, щоб попередити машиніста поїзда?","ru":"На какое расстояние от переезда нужно послать людей вдоль путей, чтобы предупредить машиниста поезда?"},"a":[{"uk":"Не менш як на 300 м","ru":"Не менее чем на 300 м","w":{"uk":"300 м — замало: поїзд не встигне загальмувати. Посилають не менш як на 1000 м.","ru":"300 м — мало: поезд не успеет затормозить. Посылают не менее чем на 1000 м."}},{"uk":"Не менш як на 500 м","ru":"Не менее чем на 500 м","w":{"uk":"500 м — теж замало: гальмівний шлях поїзда великий. Потрібно щонайменше 1000 м.","ru":"500 м — тоже мало: тормозной путь поезда большой. Нужно не менее 1000 м."}},{"uk":"Не менш як на 1000 м","ru":"Не менее чем на 1000 м"}],"c":2,"e":{"uk":"За можливості двох людей посилають уздовж колій в обидва боки від переїзду не менш як на 1000 м.","ru":"По возможности двух человек посылают вдоль путей в обе стороны от переезда не менее чем на 1000 м."},"ref":["20.8"],"id":"q607fd0c7d"},{"t":"s20","q":{"uk":"Черговий по переїзду стоїть до вас грудьми з піднятим над головою жезлом. Що це означає?","ru":"Дежурный по переезду стоит к вам грудью с поднятым над головой жезлом. Что это означает?"},"a":[{"uk":"Можна проїжджати з обережністю","ru":"Можно проезжать с осторожностью","w":{"uk":"Жезл над головою — сигнал заборони, а не дозволу.","ru":"Жезл над головой — сигнал запрещения, а не разрешения."}},{"uk":"Рух через переїзд заборонено","ru":"Движение через переезд запрещено"}],"c":1,"e":{"uk":"Черговий подає сигнал заборони, стоячи до водія грудьми або спиною з піднятим над головою жезлом (червоним ліхтарем, прапорцем) або з витягнутими в сторони руками.","ru":"Дежурный подаёт сигнал запрещения, стоя к водителю грудью или спиной с поднятым над головой жезлом (красным фонарём, флажком) или с вытянутыми в стороны руками."},"ref":["20.5"],"id":"qe825cbf68"},{"t":"s21","q":{"uk":"Дитину якого зросту дозволено перевозити в легковому автомобілі без дитячого автокрісла (утримуючої системи)?","ru":"Ребёнка какого роста разрешено перевозить в легковом автомобиле без детского автокресла (удерживающей системы)?"},"a":[{"uk":"Від 120 см","ru":"От 120 см","w":{"uk":"120 см — замало: без автокрісла можна перевозити дітей лише від 150 см.","ru":"120 см — мало: без автокресла можно перевозить детей только от 150 см."}},{"uk":"Від 135 см","ru":"От 135 см","w":{"uk":"135 см — теж замало: межа в Правилах — 150 см.","ru":"135 см — тоже мало: порог в Правилах — 150 см."}},{"uk":"Від 150 см","ru":"От 150 см"}],"c":2,"e":{"uk":"Дітей зростом менше 150 см заборонено перевозити без дитячих утримуючих систем, що дають змогу пристебнути дитину штатними ременями безпеки.","ru":"Детей ростом менее 150 см запрещено перевозить без детских удерживающих систем, позволяющих пристегнуть ребёнка штатными ремнями безопасности."},"ref":["21.11"],"id":"q1ab2a7e2c"},{"t":"s21","q":{"uk":"Чи можна встановити дитяче автокрісло на передньому сидінні легкового автомобіля?","ru":"Можно ли установить детское автокресло на переднем сиденье легкового автомобиля?"},"a":[{"uk":"Так, без обмежень","ru":"Да, без ограничений","w":{"uk":"Є обмеження: спереду — лише для дитини до 3 років, проти руху й з вимкненою подушкою безпеки.","ru":"Есть ограничения: спереди — только для ребёнка до 3 лет, против движения и с выключенной подушкой безопасности."}},{"uk":"Лише для дитини до 3 років, крісло проти напрямку руху й з вимкненою фронтальною подушкою безпеки","ru":"Только для ребёнка до 3 лет, кресло против направления движения и с выключенной фронтальной подушкой безопасности"},{"uk":"Ні, ніколи","ru":"Нет, никогда","w":{"uk":"Не ніколи: для дитини до 3 років переднє сидіння допускається за певних умов.","ru":"Не никогда: для ребёнка до 3 лет переднее сиденье допускается при определённых условиях."}}],"c":1,"e":{"uk":"Дитячі утримуючі системи встановлюють не в першому ряду. Для дитини до трьох років у легковому автомобілі допускається переднє сидіння: крісло проти руху, фронтальна подушка вимкнена.","ru":"Детские удерживающие системы устанавливают не в первом ряду. Для ребёнка до трёх лет в легковом автомобиле допускается переднее сиденье: кресло против движения, фронтальная подушка выключена."},"ref":["21.13"],"id":"qb2388957a"},{"t":"s21","q":{"uk":"Коли водієві дозволено відчиняти двері автомобіля з пасажирами?","ru":"Когда водителю разрешено открывать двери автомобиля с пассажирами?"},"a":[{"uk":"Лише після повної зупинки","ru":"Только после полной остановки"},{"uk":"На швидкості до 5 км/год","ru":"На скорости до 5 км/ч","w":{"uk":"Навіть на малій швидкості відчиняти двері заборонено — лише після повної зупинки.","ru":"Даже на малой скорости открывать двери запрещено — только после полной остановки."}},{"uk":"Коли автомобіль під'їжджає до тротуару","ru":"Когда автомобиль подъезжает к тротуару","w":{"uk":"Під'їзд до тротуару — ще не зупинка. Двері відчиняють лише після повної зупинки.","ru":"Подъезд к тротуару — ещё не остановка. Двери открывают только после полной остановки."}}],"c":0,"e":{"uk":"Водієві заборонено починати рух до повного зачинення дверей та відчиняти їх до зупинки транспортного засобу.","ru":"Водителю запрещено начинать движение до полного закрытия дверей и открывать их до остановки транспортного средства."},"ref":["21.4"],"id":"q94a75bd3c"},{"t":"s21","q":{"uk":"Чи можна перевозити дітей до 16 років у кузові вантажного автомобіля?","ru":"Можно ли перевозить детей до 16 лет в кузове грузового автомобиля?"},"a":[{"uk":"Так, якщо є обладнані сидіння","ru":"Да, если есть оборудованные сиденья","w":{"uk":"Обладнані сидіння не скасовують заборони: дітей до 16 років у кузові вантажівки не возять.","ru":"Оборудованные сиденья не отменяют запрета: детей до 16 лет в кузове грузовика не возят."}},{"uk":"Ні, у кузові будь-якого вантажного автомобіля заборонено","ru":"Нет, в кузове любого грузового автомобиля запрещено"}],"c":1,"e":{"uk":"Заборонено перевозити дітей до 16 років у кузові будь-якого вантажного автомобіля, а організовані групи дітей — у темну пору доби.","ru":"Запрещено перевозить детей до 16 лет в кузове любого грузового автомобиля, а организованные группы детей — в тёмное время суток."},"ref":["21.11"],"id":"q735fe2b67"},{"t":"s23","q":{"uk":"Якою має бути довжина гнучкого зчеплення під час буксирування?","ru":"Какой должна быть длина гибкой сцепки при буксировке?"},"a":[{"uk":"До 4 м","ru":"До 4 м","w":{"uk":"До 4 м — це жорстке зчеплення. Гнучке (трос) — 4–6 м.","ru":"До 4 м — это жёсткая сцепка. Гибкая (трос) — 4–6 м."}},{"uk":"4–6 м","ru":"4–6 м"},{"uk":"6–8 м","ru":"6–8 м","w":{"uk":"Задовгий трос погіршує керованість. Правила дозволяють гнучке зчеплення 4–6 м.","ru":"Слишком длинный трос ухудшает управляемость. Правила разрешают гибкую сцепку 4–6 м."}}],"c":1,"e":{"uk":"Жорстке зчеплення забезпечує відстань не більше 4 м, гнучке — 4–6 м. Гнучке зчеплення позначають прапорцями або щитками через кожний метр.","ru":"Жёсткая сцепка обеспечивает расстояние не более 4 м, гибкая — 4–6 м. Гибкую сцепку обозначают флажками или щитками через каждый метр."},"ref":["23.3"],"id":"qa5fc21569"},{"t":"s23","q":{"uk":"Що має бути справним в автомобілі, який буксирують на гнучкому зчепленні?","ru":"Что должно быть исправно в автомобиле, который буксируют на гибкой сцепке?"},"a":[{"uk":"Лише рульове керування","ru":"Только рулевое управление","w":{"uk":"Лише кермо достатньо на жорсткому зчепленні. На тросі мають працювати ще й гальма.","ru":"Только руля достаточно на жёсткой сцепке. На тросе должны работать ещё и тормоза."}},{"uk":"Робоча гальмова система і рульове керування","ru":"Рабочая тормозная система и рулевое управление"},{"uk":"Лише гальма","ru":"Только тормоза","w":{"uk":"Самих гальм мало: без керма автомобіль на тросі некерований. Потрібні і гальма, і кермо.","ru":"Одних тормозов мало: без руля автомобиль на тросе неуправляем. Нужны и тормоза, и руль."}}],"c":1,"e":{"uk":"На гнучкому зчепленні в буксированому автомобілі мають діяти робоче гальмо і кермо, на жорсткому — кермо. Якщо кермо не працює — лише частковим навантаженням на платформу.","ru":"На гибкой сцепке в буксируемом автомобиле должны действовать рабочий тормоз и руль, на жёсткой — руль. Если руль не работает — только частичной погрузкой на платформу."},"ref":["23.4","23.7"],"id":"q971eb1548"},{"t":"s23","q":{"uk":"Коли заборонено буксирування на гнучкому зчепленні?","ru":"Когда запрещена буксировка на гибкой сцепке?"},"a":[{"uk":"Під час ожеледиці","ru":"Во время гололедицы"},{"uk":"У темну пору доби","ru":"В тёмное время суток","w":{"uk":"Вночі буксирувати на тросі можна (з увімкненими вогнями). Заборона — в ожеледицю.","ru":"Ночью буксировать на тросе можно (с включёнными огнями). Запрет — в гололедицу."}},{"uk":"У населеному пункті","ru":"В населённом пункте","w":{"uk":"У місті буксирування не заборонене. Заборона на гнучке зчеплення — під час ожеледиці.","ru":"В городе буксировка не запрещена. Запрет на гибкую сцепку — во время гололедицы."}}],"c":0,"e":{"uk":"Буксирування на гнучкому зчепленні під час ожеледиці заборонено. Також не можна буксирувати автобусами, мотоциклами без коляски, транспортним засобом з причепом і більше одного транспортного засобу.","ru":"Буксировка на гибкой сцепке во время гололедицы запрещена. Также нельзя буксировать автобусами, мотоциклами без коляски, транспортным средством с прицепом и более одного транспортного средства."},"ref":["23.10"],"id":"q4ebb958e1"},{"t":"s23","q":{"uk":"Чи можна перевозити пасажирів у легковому автомобілі, який буксирують на тросі?","ru":"Можно ли перевозить пассажиров в легковом автомобиле, который буксируют на тросе?"},"a":[{"uk":"Так, у легковому автомобілі можна","ru":"Да, в легковом автомобиле можно"},{"uk":"Ні, в жодному разі","ru":"Нет, ни в коем случае","w":{"uk":"Для легкового автомобіля на жорсткому чи гнучкому зчепленні є виняток: пасажирів у ньому перевозити можна.","ru":"Для легкового автомобиля на жёсткой или гибкой сцепке есть исключение: пассажиров в нём перевозить можно."}}],"c":0,"e":{"uk":"Під час буксирування на жорсткому чи гнучкому зчепленні заборонено перевозити пасажирів у буксированому транспортному засобі, крім легкового автомобіля. На платформі (часткове навантаження) пасажирів перевозять лише в кабіні тягача.","ru":"При буксировке на жёсткой или гибкой сцепке запрещено перевозить пассажиров в буксируемом транспортном средстве, кроме легкового автомобиля. На платформе (частичная погрузка) пассажиров перевозят только в кабине тягача."},"ref":["23.9"],"id":"qb4fcd49bd"},{"t":"s24","q":{"uk":"З якого віку можна навчатися водіння автомобіля?","ru":"С какого возраста можно учиться вождению автомобиля?"},"a":[{"uk":"З 14 років","ru":"С 14 лет","w":{"uk":"З 14 років можна вчитися водити мотоцикл чи мопед. Автомобіль — з 16.","ru":"С 14 лет можно учиться водить мотоцикл или мопед. Автомобиль — с 16."}},{"uk":"З 16 років","ru":"С 16 лет"},{"uk":"З 18 років","ru":"С 18 лет","w":{"uk":"18 років — вік для отримання посвідчення категорії B. Навчатися можна раніше — з 16.","ru":"18 лет — возраст для получения удостоверения категории B. Учиться можно раньше — с 16."}}],"c":1,"e":{"uk":"Навчатися водіння автомобіля можна з 16 років, мотоцикла чи мопеда — з 14. Навчальна їзда на дорогах — лише з інструктором; у житловій зоні та на автомагістралях вона заборонена.","ru":"Учиться вождению автомобиля можно с 16 лет, мотоцикла или мопеда — с 14. Учебная езда на дорогах — только с инструктором; в жилой зоне и на автомагистралях она запрещена."},"ref":["24.2","24.9"],"id":"q64719f3d5"},{"t":"s25","q":{"uk":"На скільки груп ділять колону без супроводу оперативних транспортних засобів?","ru":"На сколько групп делят колонну без сопровождения оперативных транспортных средств?"},"a":[{"uk":"На групи не більше п'яти транспортних засобів","ru":"На группы не более пяти транспортных средств"},{"uk":"На групи по десять","ru":"На группы по десять","w":{"uk":"Групи по 10 — це норма для колони велосипедистів. Колону автомобілів ділять на групи до 5.","ru":"Группы по 10 — это норма для колонны велосипедистов. Колонну автомобилей делят на группы до 5."}},{"uk":"Не ділять","ru":"Не делят","w":{"uk":"Колону без супроводу обов'язково ділять на групи до 5 машин, щоб інші могли її обганяти.","ru":"Колонну без сопровождения обязательно делят на группы до 5 машин, чтобы другие могли её обгонять."}}],"c":0,"e":{"uk":"Колону без супроводу ділять на групи не більше п'яти транспортних засобів з дистанцією, що дає змогу іншим обганяти групу. Іншим заборонено займати місце в колоні.","ru":"Колонну без сопровождения делят на группы не более пяти транспортных средств с дистанцией, позволяющей другим обгонять группу. Другим запрещено занимать место в колонне."},"ref":["25.4","25.6"],"id":"q9b7affec2"},{"t":"s26","q":{"uk":"Хто має перевагу в житловій зоні?","ru":"У кого преимущество в жилой зоне?"},"a":[{"uk":"Пішоходи, але вони не повинні безпідставно заважати транспорту","ru":"Пешеходы, но они не должны без причины мешать транспорту"},{"uk":"Транспортні засоби","ru":"Транспортные средства","w":{"uk":"У житловій зоні навпаки: перевагу мають пішоходи.","ru":"В жилой зоне наоборот: преимущество у пешеходов."}},{"uk":"Той, хто праворуч","ru":"Тот, кто справа","w":{"uk":"«Перешкода праворуч» стосується транспорту між собою. Пішоходи в житловій зоні мають перевагу.","ru":"«Помеха справа» касается транспорта между собой. Пешеходы в жилой зоне имеют преимущество."}}],"img":{"sign":"5.34"},"c":0,"e":{"uk":"У житловій і пішохідній зоні пішоходи можуть іти і тротуаром, і проїзною частиною та мають перевагу. Швидкість — до 20 км/год.","ru":"В жилой и пешеходной зоне пешеходы могут идти и по тротуару, и по проезжей части и имеют преимущество. Скорость — до 20 км/ч."},"ref":["26.1","12.5"],"id":"q1be42aa05"},{"t":"s26","q":{"uk":"Що заборонено в житловій зоні?","ru":"Что запрещено в жилой зоне?"},"a":[{"uk":"Будь-яка зупинка","ru":"Любая остановка","w":{"uk":"Зупинка в житловій зоні дозволена. Заборонено транзит, стоянку з працюючим двигуном і навчальну їзду.","ru":"Остановка в жилой зоне разрешена. Запрещены транзит, стоянка с работающим двигателем и учебная езда."}},{"uk":"Транзитний рух, стоянка з працюючим двигуном, навчальна їзда","ru":"Сквозное движение, стоянка с работающим двигателем, учебная езда"},{"uk":"Рух легкових автомобілів","ru":"Движение легковых автомобилей","w":{"uk":"Легкові автомобілі в житлову зону в'їжджати можуть (без транзиту). Обмежено рух вантажівок.","ru":"Легковые автомобили в жилую зону въезжать могут (без транзита). Ограничено движение грузовиков."}}],"c":1,"e":{"uk":"У житловій зоні заборонено транзитний рух, стоянку поза відведеними місцями, стоянку з працюючим двигуном, навчальну їзду та рух вантажівок (крім обслуговуючих).","ru":"В жилой зоне запрещены сквозное движение, стоянка вне отведённых мест, стоянка с работающим двигателем, учебная езда и движение грузовиков (кроме обслуживающих)."},"ref":["26.2"],"id":"q5c9f60a31"},{"t":"s26","q":{"uk":"Виїжджаючи з житлової зони, водій повинен...","ru":"Выезжая из жилой зоны, водитель должен..."},"a":[{"uk":"дати дорогу іншим учасникам дорожнього руху","ru":"уступить дорогу другим участникам дорожного движения"},{"uk":"керуватися правилом «перешкода праворуч»","ru":"руководствоваться правилом «помеха справа»","w":{"uk":"Виїзд із житлової зони прирівнюється до виїзду з прилеглої території: поступаєтеся всім.","ru":"Выезд из жилой зоны приравнивается к выезду с прилегающей территории: уступаете всем."}},{"uk":"рухатися першим, якщо їде прямо","ru":"ехать первым, если едет прямо","w":{"uk":"Напрямок руху не важливий: виїжджаючи з житлової зони, ви поступаєтеся всім.","ru":"Направление движения не важно: выезжая из жилой зоны, вы уступаете всем."}}],"c":0,"e":{"uk":"Під час виїзду з житлової та пішохідної зони водії дають дорогу іншим учасникам руху.","ru":"При выезде из жилой и пешеходной зоны водители уступают дорогу другим участникам движения."},"ref":["26.4"],"id":"q33ef82241"},{"t":"s27","q":{"uk":"Що з переліченого заборонено на автомагістралі?","ru":"Что из перечисленного запрещено на автомагистрали?"},"a":[{"uk":"Рух зі швидкістю 110 км/год","ru":"Движение со скоростью 110 км/ч","w":{"uk":"110 км/год на автомагістралі дозволено (до 130).","ru":"110 км/ч на автомагистрали разрешено (до 130)."}},{"uk":"Розворот, рух заднім ходом і зупинка поза спеціальними майданчиками","ru":"Разворот, движение задним ходом и остановка вне специальных площадок"},{"uk":"Випередження по лівій смузі","ru":"Опережение по левой полосе","w":{"uk":"Випередження лівою смугою — звичайний маневр і не заборонений.","ru":"Опережение по левой полосе — обычный манёвр и не запрещено."}}],"c":1,"e":{"uk":"На автомагістралях і дорогах для автомобілів заборонено розворот, в'їзд у технологічні розриви розділювальної смуги, рух заднім ходом, зупинку поза майданчиками {s:5.42.1}, {s:5.43}, {s:6.15}, навчальну їзду, рух тракторів.","ru":"На автомагистралях и дорогах для автомобилей запрещены разворот, въезд в технологические разрывы разделительной полосы, движение задним ходом, остановка вне площадок {s:5.42.1}, {s:5.43}, {s:6.15}, учебная езда, движение тракторов."},"ref":["27.2"],"id":"qc781291f7"},{"t":"s27","q":{"uk":"Автомобіль вимушено зупинився на проїзній частині автомагістралі. Що робити?","ru":"Автомобиль вынужденно остановился на проезжей части автомагистрали. Что делать?"},"a":[{"uk":"Увімкнути аварійку, виставити знак аварійної зупинки і прибрати автомобіль за межі проїзної частини праворуч","ru":"Включить аварийку, выставить знак аварийной остановки и убрать автомобиль за пределы проезжей части вправо"},{"uk":"Залишатися в автомобілі й чекати евакуатор","ru":"Оставаться в автомобиле и ждать эвакуатор","w":{"uk":"Сидіти в машині на проїзній частині автомагістралі небезпечно. Треба позначити автомобіль і прибрати його праворуч.","ru":"Сидеть в машине на проезжей части автомагистрали опасно. Нужно обозначить автомобиль и убрать его вправо."}},{"uk":"Рухатися заднім ходом до найближчого з'їзду","ru":"Двигаться задним ходом до ближайшего съезда","w":{"uk":"Рух заднім ходом на автомагістралі заборонено.","ru":"Движение задним ходом на автомагистрали запрещено."}}],"c":0,"e":{"uk":"За вимушеної зупинки на автомагістралі транспортний засіб позначають згідно з пунктами 9.9–9.11 (аварійка, знак аварійної зупинки) і вживають заходів, щоб прибрати його за межі проїзної частини праворуч.","ru":"При вынужденной остановке на автомагистрали транспортное средство обозначают согласно пунктам 9.9–9.11 (аварийка, знак аварийной остановки) и принимают меры, чтобы убрать его за пределы проезжей части вправо."},"ref":["27.5"],"id":"q9d703a853"},{"t":"s28","q":{"uk":"Що заборонено на гірських дорогах?","ru":"Что запрещено на горных дорогах?"},"a":[{"uk":"Рухатися з вимкненим двигуном і вимкненим зчепленням або передачею (накатом)","ru":"Двигаться с выключенным двигателем и выключенным сцеплением или передачей (накатом)"},{"uk":"Користуватися моторним гальмуванням","ru":"Пользоваться торможением двигателем","w":{"uk":"Навпаки, гальмування двигуном на спусках — правильний прийом.","ru":"Наоборот, торможение двигателем на спусках — правильный приём."}},{"uk":"Вмикати ближнє світло вдень","ru":"Включать ближний свет днём","w":{"uk":"Ближнє світло вдень не заборонене, а поза населеними пунктами навіть обов'язкове.","ru":"Ближний свет днём не запрещён, а вне населённых пунктов даже обязателен."}}],"c":0,"e":{"uk":"На гірських дорогах заборонено рухатися з непрацюючим двигуном і вимкненим зчепленням чи передачею, буксирувати на гнучкому зчепленні, а в ожеледицю — будь-яке буксирування.","ru":"На горных дорогах запрещено двигаться с неработающим двигателем и выключенным сцеплением или передачей, буксировать на гибкой сцепке, а в гололедицу — любая буксировка."},"ref":["28.3"],"id":"qcbf49dbff"},{"t":"s22","q":{"uk":"Вантаж виступає за задній габарит автомобіля на 1,5 м. Що потрібно зробити?","ru":"Груз выступает за задний габарит автомобиля на 1,5 м. Что нужно сделать?"},"a":[{"uk":"Нічого, якщо вантаж надійно закріплений","ru":"Ничего, если груз надёжно закреплён","w":{"uk":"Надійне кріплення не скасовує вимоги: вантаж, що виступає більш як на 1 м, треба позначити.","ru":"Надёжное крепление не отменяет требования: груз, выступающий более чем на 1 м, нужно обозначить."}},{"uk":"Позначити його розпізнавальним знаком «Негабаритний вантаж» (червоно-білі щитки чи прапорці)","ru":"Обозначить его опознавательным знаком «Негабаритный груз» (красно-белые щитки или флажки)"},{"uk":"Увімкнути аварійну сигналізацію на весь час руху","ru":"Включить аварийную сигнализацию на всё время движения","w":{"uk":"Аварійка не замінює знак «Негабаритний вантаж». Потрібні червоно-білі щитки чи прапорці.","ru":"Аварийка не заменяет знак «Негабаритный груз». Нужны красно-белые щитки или флажки."}}],"c":1,"e":{"uk":"Вантаж, що виступає спереду або ззаду більш як на 1 м чи збоку більш як на 0,4 м від габаритного ліхтаря, позначають знаком «Негабаритний вантаж», а вночі — ще й ліхтарями або світлоповертачами.","ru":"Груз, выступающий спереди или сзади более чем на 1 м или сбоку более чем на 0,4 м от габаритного фонаря, обозначают знаком «Негабаритный груз», а ночью — ещё и фонарями или световозвращателями."},"ref":["22.4","30.3"],"id":"qc1d641508"},{"t":"s22","q":{"uk":"За якої умови дозволено перевозити вантаж на легковому автомобілі (наприклад, на багажнику даху)?","ru":"При каком условии разрешено перевозить груз на легковом автомобиле (например, на багажнике крыши)?"},"a":[{"uk":"Якщо він не обмежує оглядовість, не закриває світлові прилади й номери та не порушує стійкість автомобіля","ru":"Если он не ограничивает обзорность, не закрывает световые приборы и номера и не нарушает устойчивость автомобиля"},{"uk":"Якщо його маса не перевищує 50 кг","ru":"Если его масса не превышает 50 кг","w":{"uk":"Правила не встановлюють такої межі. Важливо, щоб вантаж не заважав огляду й не порушував стійкість.","ru":"Правила не устанавливают такого порога. Важно, чтобы груз не мешал обзору и не нарушал устойчивость."}},{"uk":"Лише в темну пору доби","ru":"Только в тёмное время суток","w":{"uk":"Час доби не має значення. Важливо, як вантаж розміщений і закріплений.","ru":"Время суток не имеет значения. Важно, как груз размещён и закреплён."}}],"c":0,"e":{"uk":"Вантаж не повинен наражати на небезпеку інших, порушувати стійкість, обмежувати оглядовість, закривати світлові прилади, світлоповертачі й номерні знаки, шуміти чи пилити. Водій перевіряє кріплення перед рушанням і стежить за ним у дорозі.","ru":"Груз не должен подвергать опасности других, нарушать устойчивость, ограничивать обзорность, закрывать световые приборы, световозвращатели и номерные знаки, шуметь или пылить. Водитель проверяет крепление перед поездкой и следит за ним в пути."},"ref":["22.2","22.3"],"id":"q67439db2a"},{"t":"s30","q":{"uk":"Протягом якого строку треба зареєструвати придбаний автомобіль?","ru":"В течение какого срока нужно зарегистрировать приобретённый автомобиль?"},"a":[{"uk":"30 діб","ru":"30 суток","w":{"uk":"30 діб — надто довго: зареєструвати треба протягом 10 діб.","ru":"30 суток — слишком долго: зарегистрировать нужно в течение 10 суток."}},{"uk":"10 діб","ru":"10 суток"},{"uk":"3 місяці","ru":"3 месяца","w":{"uk":"3 місяці — надто довго: строк — 10 діб.","ru":"3 месяца — слишком долго: срок — 10 суток."}}],"c":1,"e":{"uk":"Власник зобов'язаний зареєструвати (перереєструвати) транспортний засіб протягом 10 діб з моменту придбання, митного оформлення або переобладнання.","ru":"Владелец обязан зарегистрировать (перерегистрировать) транспортное средство в течение 10 суток с момента приобретения, таможенного оформления или переоборудования."},"ref":["30.1"],"id":"qd560b1e8e"},{"t":"s30","q":{"uk":"Де розміщують розпізнавальний знак «Шипи»?","ru":"Где размещают опознавательный знак «Шипы»?"},"a":[{"uk":"Ззаду на транспортних засобах із шипованими шинами","ru":"Сзади на транспортных средствах с шипованными шинами"},{"uk":"Спереду і ззаду","ru":"Спереди и сзади","w":{"uk":"Спереду і ззаду ставлять знак «Навчальний транспортний засіб». «Шипи» — лише ззаду.","ru":"Спереди и сзади ставят знак «Учебное транспортное средство». «Шипы» — только сзади."}},{"uk":"На лобовому склі","ru":"На лобовом стекле","w":{"uk":"На лобове скло знак «Шипи» не клеять: його мають бачити водії позаду.","ru":"На лобовое стекло знак «Шипы» не клеят: его должны видеть водители сзади."}}],"c":0,"e":{"uk":"«Шипи» — білий трикутник із червоною каймою і літерою «Ш»; розміщують ззаду. «Навчальний транспортний засіб» — такий самий трикутник з літерою «Н», спереду і ззаду.","ru":"«Шипы» — белый треугольник с красной каймой и буквой «Ш»; размещают сзади. «Учебное транспортное средство» — такой же треугольник с буквой «Н», спереди и сзади."},"ref":["30.3"],"id":"q9c7fd783d"},{"t":"s30","q":{"uk":"На якому автомобілі обов'язково має бути знак «Обмеження максимальної швидкості» ззаду ліворуч?","ru":"На каком автомобиле обязательно должен быть знак «Ограничение максимальной скорости» сзади слева?"},"a":[{"uk":"На автомобілі, яким керує водій зі стажем до 2 років","ru":"На автомобиле, которым управляет водитель со стажем до 2 лет"},{"uk":"На будь-якому автомобілі з причепом","ru":"На любом автомобиле с прицепом","w":{"uk":"Причіп сам по собі такого знака не вимагає. Обов'язковий він, зокрема, для водіїв зі стажем до 2 років.","ru":"Прицеп сам по себе такого знака не требует. Обязателен он, в частности, для водителей со стажем до 2 лет."}},{"uk":"На автомобілі таксі","ru":"На автомобиле такси","w":{"uk":"Для таксі передбачено знак «Таксі» (шахові квадрати), а не обмеження швидкості.","ru":"Для такси предусмотрен знак «Такси» (шахматные квадраты), а не ограничение скорости."}}],"c":0,"e":{"uk":"Знак із зображенням {s:3.29} розміщують ззаду ліворуч на автомобілях водіїв зі стажем до 2 років, великогабаритних і великовагових транспортних засобах, при перевезенні небезпечних вантажів та в інших випадках, коли швидкість обмежена.","ru":"Знак с изображением {s:3.29} размещают сзади слева на автомобилях водителей со стажем до 2 лет, крупногабаритных и тяжеловесных транспортных средствах, при перевозке опасных грузов и в других случаях, когда скорость ограничена."},"ref":["30.3"],"id":"q29edef9f0"},{"t":"s31","q":{"uk":"Яка мінімальна залишкова глибина малюнка протектора шин легкового автомобіля?","ru":"Какая минимальная остаточная глубина рисунка протектора шин легкового автомобиля?"},"a":[{"uk":"1,0 мм","ru":"1,0 мм","w":{"uk":"1,0 мм — норма для вантажівок понад 3,5 т. Для легкових — 1,6 мм.","ru":"1,0 мм — норма для грузовиков более 3,5 т. Для легковых — 1,6 мм."}},{"uk":"1,6 мм","ru":"1,6 мм"},{"uk":"2,0 мм","ru":"2,0 мм","w":{"uk":"2,0 мм — норма для автобусів. Для легкових — 1,6 мм.","ru":"2,0 мм — норма для автобусов. Для легковых — 1,6 мм."}},{"uk":"0,8 мм","ru":"0,8 мм","w":{"uk":"0,8 мм — норма для мотоциклів і мопедів. Для легкових — 1,6 мм.","ru":"0,8 мм — норма для мотоциклов и мопедов. Для легковых — 1,6 мм."}}],"c":1,"e":{"uk":"Для легкових автомобілів і вантажівок до 3,5 т — не менше 1,6 мм, для вантажівок понад 3,5 т — 1,0 мм, для автобусів — 2,0 мм, для мотоциклів і мопедів — 0,8 мм.","ru":"Для легковых автомобилей и грузовиков до 3,5 т — не менее 1,6 мм, для грузовиков более 3,5 т — 1,0 мм, для автобусов — 2,0 мм, для мотоциклов и мопедов — 0,8 мм."},"ref":["31.4"],"id":"q84f7aea20"},{"t":"s31","q":{"uk":"Під час дощу перестав працювати склоочисник з боку водія. Що робити?","ru":"Во время дождя перестал работать стеклоочиститель со стороны водителя. Что делать?"},"a":[{"uk":"Їхати до найближчого сервісу з аварійкою","ru":"Ехать до ближайшего сервиса с аварийкой","w":{"uk":"Ця несправність входить до переліку, з яким подальший рух заборонено навіть до сервісу.","ru":"Эта неисправность входит в перечень, с которым дальнейшее движение запрещено даже до сервиса."}},{"uk":"Подальший рух заборонено; треба прибрати автомобіль з проїзної частини","ru":"Дальнейшее движение запрещено; нужно убрать автомобиль с проезжей части"},{"uk":"Продовжити рух із меншою швидкістю","ru":"Продолжить движение с меньшей скоростью","w":{"uk":"Зниження швидкості не допоможе: без склоочисника з боку водія в дощ рух заборонено.","ru":"Снижение скорости не поможет: без стеклоочистителя со стороны водителя в дождь движение запрещено."}}],"c":1,"e":{"uk":"Подальший рух заборонено, якщо несправні робоча гальмова система чи кермо, вночі не горять фари чи задні габарити, під час дощу або снігу не працює склоочисник з боку водія, або зіпсований зчіпний пристрій автопоїзда.","ru":"Дальнейшее движение запрещено, если неисправны рабочая тормозная система или руль, ночью не горят фары или задние габариты, во время дождя или снега не работает стеклоочиститель со стороны водителя либо неисправно сцепное устройство автопоезда."},"ref":["31.6"],"id":"qe524262b3"},{"t":"s31","q":{"uk":"Що обов'язково має бути в легковому автомобілі?","ru":"Что обязательно должно быть в легковом автомобиле?"},"a":[{"uk":"Медична аптечка, знак аварійної зупинки і вогнегасник","ru":"Медицинская аптечка, знак аварийной остановки и огнетушитель"},{"uk":"Аптечка і буксирувальний трос","ru":"Аптечка и буксировочный трос","w":{"uk":"Трос не обов'язковий. Обов'язкові аптечка, знак аварійної зупинки і вогнегасник.","ru":"Трос не обязателен. Обязательны аптечка, знак аварийной остановки и огнетушитель."}},{"uk":"Лише знак аварійної зупинки","ru":"Только знак аварийной остановки","w":{"uk":"Самого знака мало: потрібні ще аптечка і вогнегасник.","ru":"Одного знака мало: нужны ещё аптечка и огнетушитель."}}],"c":0,"e":{"uk":"Експлуатацію заборонено, якщо в легковому автомобілі немає аптечки, знака аварійної зупинки (або миготливого червоного ліхтаря) та працездатного вогнегасника.","ru":"Эксплуатация запрещена, если в легковом автомобиле нет аптечки, знака аварийной остановки (или мигающего красного фонаря) и работоспособного огнетушителя."},"ref":["31.4"],"id":"qc1d44b2d9"},{"t":"s31","q":{"uk":"Вдень у дорозі перестала горіти ліва фара ближнього світла. Як діяти?","ru":"Днём в пути перестала гореть левая фара ближнего света. Как поступить?"},"a":[{"uk":"Усунути несправність, а якщо неможливо — обережно їхати найкоротшим шляхом до місця ремонту чи стоянки","ru":"Устранить неисправность, а если невозможно — осторожно ехать кратчайшим путём к месту ремонта или стоянки"},{"uk":"Негайно зупинитися і викликати евакуатор","ru":"Немедленно остановиться и вызвать эвакуатор","w":{"uk":"Вдень з такою несправністю дозволено обережно доїхати до місця ремонту. Евакуатор не обов'язковий.","ru":"Днём с такой неисправностью разрешено осторожно доехать до места ремонта. Эвакуатор не обязателен."}},{"uk":"Продовжувати поїздку як зазвичай","ru":"Продолжать поездку как обычно","w":{"uk":"Ця несправність забороняє звичайну експлуатацію: треба їхати лише до місця ремонту, а вночі — не можна зовсім.","ru":"Эта неисправность запрещает обычную эксплуатацию: нужно ехать только до места ремонта, а ночью — нельзя вовсе."}}],"c":0,"e":{"uk":"Несправність лівої фари ближнього світла — серед несправностей п. 31.4. Якщо усунути її в дорозі не вдається, можна рухатися найкоротшим шляхом до місця ремонту чи стоянки, дотримуючись запобіжних заходів. Уночі без фар рух заборонено.","ru":"Неисправность левой фары ближнего света — среди неисправностей п. 31.4. Если устранить её в пути не удаётся, можно двигаться кратчайшим путём к месту ремонта или стоянки, соблюдая меры предосторожности. Ночью без фар движение запрещено."},"ref":["31.4","31.5","31.6"],"id":"qd03ba6bf0"},{"t":"s31","q":{"uk":"Чи можна встановлювати на одну вісь шиповані і нешиповані шини?","ru":"Можно ли устанавливать на одну ось шипованные и нешипованные шины?"},"a":[{"uk":"Так, якщо вони одного розміру","ru":"Да, если они одного размера","w":{"uk":"Однаковий розмір не допомагає: на одній осі шини мають бути однакового типу, шиповані — з шипованими.","ru":"Одинаковый размер не помогает: на одной оси шины должны быть одного типа, шипованные — с шипованными."}},{"uk":"Ні","ru":"Нет"},{"uk":"Так, лише на задню вісь","ru":"Да, только на заднюю ось","w":{"uk":"Заборона діє на будь-яку вісь.","ru":"Запрет действует на любую ось."}}],"c":1,"e":{"uk":"Заборонено ставити на одну вісь діагональні й радіальні, шиповані й нешиповані, зимові й літні шини, шини різних розмірів, конструкцій чи з різним малюнком протектора.","ru":"Запрещено ставить на одну ось диагональные и радиальные, шипованные и нешипованные, зимние и летние шины, шины разных размеров, конструкций или с разным рисунком протектора."},"ref":["31.4"],"id":"q60a915f1b"},{"t":"s31","q":{"uk":"Який граничний сумарний люфт у рульовому керуванні легкового автомобіля?","ru":"Какой предельный суммарный люфт в рулевом управлении легкового автомобиля?"},"a":[{"uk":"10°","ru":"10°"},{"uk":"20°","ru":"20°","w":{"uk":"20° — межа для вантажівок понад 3,5 т і великих автобусів. Для легкових — 10°.","ru":"20° — предел для грузовиков более 3,5 т и больших автобусов. Для легковых — 10°."}},{"uk":"25°","ru":"25°","w":{"uk":"25° — межа для знятих з виробництва моделей. Для легкових — 10°.","ru":"25° — предел для снятых с производства моделей. Для легковых — 10°."}}],"c":0,"e":{"uk":"Для легкових автомобілів і вантажівок до 3,5 т сумарний люфт керма — не більше 10°.","ru":"Для легковых автомобилей и грузовиков до 3,5 т суммарный люфт руля — не более 10°."},"ref":["31.4"],"id":"q3a3bacd96"},{"t":"s33","q":{"uk":"До якого місця діє заборонний знак 3.25 «Обгін заборонено», якщо немає таблички чи знака кінця зони?","ru":"До какого места действует запрещающий знак 3.25 «Обгон запрещён», если нет таблички или знака конца зоны?"},"a":[{"uk":"100 м за знаком","ru":"100 м за знаком","w":{"uk":"Конкретної відстані немає: знак діє до найближчого перехрестя.","ru":"Конкретного расстояния нет: знак действует до ближайшего перекрёстка."}},{"uk":"До найближчого перехрестя за ним, а в населеному пункті без перехресть — до кінця населеного пункту","ru":"До ближайшего перекрёстка за ним, а в населённом пункте без перекрёстков — до конца населённого пункта"},{"uk":"До знака 3.42","ru":"До знака 3.42","w":{"uk":"3.42 скасовує заборону раніше, але навіть без нього дія знака закінчується на найближчому перехресті.","ru":"3.42 отменяет запрет раньше, но даже без него действие знака заканчивается на ближайшем перекрёстке."}}],"img":{"sign":"3.25"},"c":1,"e":{"uk":"Зона дії більшості заборонних знаків — від місця встановлення до найближчого перехрестя. Виїзди з прилеглих територій і ґрунтові дороги без знаків пріоритету дію знака не переривають.","ru":"Зона действия большинства запрещающих знаков — от места установки до ближайшего перекрёстка. Выезды с прилегающих территорий и грунтовые дороги без знаков приоритета действие знака не прерывают."},"ref":["33.3"],"id":"q180b56bd3"},{"t":"s33","q":{"uk":"Чим знак 3.34 «Зупинку заборонено» відрізняється від знака 3.35 «Стоянку заборонено»?","ru":"Чем знак 3.34 «Остановка запрещена» отличается от знака 3.35 «Стоянка запрещена»?"},"a":[{"uk":"3.34 забороняє і зупинку, і стоянку; 3.35 — лише стоянку","ru":"3.34 запрещает и остановку, и стоянку; 3.35 — только стоянку"},{"uk":"Це однакові знаки","ru":"Это одинаковые знаки","w":{"uk":"Ні: під 3.34 не можна навіть зупинитися, а під 3.35 зупинятися можна.","ru":"Нет: под 3.34 нельзя даже остановиться, а под 3.35 останавливаться можно."}},{"uk":"3.34 діє лише вночі","ru":"3.34 действует только ночью","w":{"uk":"Знак 3.34 діє цілодобово, якщо табличка не вказує інший час.","ru":"Знак 3.34 действует круглосуточно, если табличка не указывает другое время."}}],"img":{"signs":["3.34","3.35"]},"c":0,"e":{"uk":"Під знаком {s:3.34} заборонено зупинятися і стояти (крім таксі для посадки й висадки). Під знаком {s:3.35} зупинятися можна, але стояти понад 5 хвилин — ні. Обидва діють лише на тому боці дороги, де встановлені.","ru":"Под знаком {s:3.34} запрещено останавливаться и стоять (кроме такси для посадки и высадки). Под знаком {s:3.35} останавливаться можно, но стоять более 5 минут — нельзя. Оба действуют только на той стороне дороги, где установлены."},"ref":["33.3"],"id":"q17a4eaa5f"},{"t":"s33","q":{"uk":"Знак 3.23 «Поворот ліворуч заборонено». Чи можна на цьому перехресті розвернутися?","ru":"Знак 3.23 «Поворот налево запрещён». Можно ли на этом перекрёстке развернуться?"},"a":[{"uk":"Так, розворот дозволено","ru":"Да, разворот разрешён"},{"uk":"Ні, розворот теж заборонено","ru":"Нет, разворот тоже запрещён","w":{"uk":"Знак 3.23 забороняє лише поворот ліворуч. Розворот забороняє інший знак — 3.24.","ru":"Знак 3.23 запрещает только поворот налево. Разворот запрещает другой знак — 3.24."}}],"img":{"sign":"3.23"},"c":0,"e":{"uk":"Знак {s:3.23} забороняє поворот ліворуч, але дозволяє розворот. Знак {s:3.24} навпаки: забороняє розворот, але дозволяє поворот ліворуч.","ru":"Знак {s:3.23} запрещает поворот налево, но разрешает разворот. Знак {s:3.24} наоборот: запрещает разворот, но разрешает поворот налево."},"ref":["33.3"],"id":"qc52ba8e6d"},{"t":"s33","q":{"uk":"Що дозволяє знак 4.3 «Рух ліворуч»?","ru":"Что разрешает знак 4.3 «Движение налево»?"},"a":[{"uk":"Лише поворот ліворуч","ru":"Только поворот налево","w":{"uk":"Не лише: знаки 4.3, 4.5 і 4.6 дозволяють також розворот.","ru":"Не только: знаки 4.3, 4.5 и 4.6 разрешают также разворот."}},{"uk":"Поворот ліворуч і розворот","ru":"Поворот налево и разворот"},{"uk":"Рух прямо і ліворуч","ru":"Движение прямо и налево","w":{"uk":"Прямо і ліворуч дозволяє знак 4.5. Знак 4.3 — лише ліворуч (і розворот).","ru":"Прямо и налево разрешает знак 4.5. Знак 4.3 — только налево (и разворот)."}}],"img":{"sign":"4.3"},"c":1,"e":{"uk":"Знаки {s:4.3}, {s:4.5} і {s:4.6} дозволяють також розворот. Наказові знаки напрямку не поширюються на маршрутні транспортні засоби.","ru":"Знаки {s:4.3}, {s:4.5} и {s:4.6} разрешают также разворот. Предписывающие знаки направления не распространяются на маршрутные транспортные средства."},"ref":["33.4"],"id":"q1e0fff511"},{"t":"s33","q":{"uk":"Ви наближаєтеся до вузької ділянки, перед якою встановлено цей знак. Як діяти?","ru":"Вы приближаетесь к узкому участку, перед которым установлен этот знак. Как поступить?"},"a":[{"uk":"Дати дорогу зустрічним транспортним засобам, що вже на вузькій ділянці, і не в'їжджати, якщо заважатимете їм","ru":"Уступить дорогу встречным транспортным средствам, которые уже на узком участке, и не въезжать, если будете им мешать"},{"uk":"Проїхати першим, бо ви маєте перевагу","ru":"Проехать первым, так как у вас преимущество","w":{"uk":"Знак 2.5 означає, що перевагу мають зустрічні, а не ви.","ru":"Знак 2.5 означает, что преимущество у встречных, а не у вас."}},{"uk":"Подати звуковий сигнал і проїхати","ru":"Подать звуковой сигнал и проехать","w":{"uk":"Сигнал не дає переваги: при знаку 2.5 ви пропускаєте зустрічних на вузькій ділянці.","ru":"Сигнал не даёт преимущества: при знаке 2.5 вы пропускаете встречных на узком участке."}}],"img":{"sign":"2.5"},"c":0,"e":{"uk":"{s:2.5} «Перевага зустрічного руху» — забороняє в'їзд на вузьку ділянку, якщо це утруднить зустрічний рух. Перевагу на вузькій ділянці має той, перед ким стоїть {s:2.6}.","ru":"{s:2.5} «Преимущество встречного движения» — запрещает въезд на узкий участок, если это затруднит встречное движение. Преимущество на узком участке у того, перед кем стоит {s:2.6}."},"ref":["33.2"],"id":"q24a7e427b"},{"t":"s33","q":{"uk":"Де треба зупинитися перед знаком 2.2 «Проїзд без зупинки заборонено», якщо стоп-лінії немає?","ru":"Где нужно остановиться перед знаком 2.2 «Проезд без остановки запрещён», если стоп-линии нет?"},"a":[{"uk":"Не обов'язково зупинятися, якщо дорога вільна","ru":"Не обязательно останавливаться, если дорога свободна","w":{"uk":"Знак 2.2 вимагає зупинитися завжди, навіть коли дорога вільна.","ru":"Знак 2.2 требует остановиться всегда, даже когда дорога свободна."}},{"uk":"Перед знаком","ru":"Перед знаком"},{"uk":"На краю перехрещуваної проїзної частини","ru":"На краю пересекаемой проезжей части","w":{"uk":"Стоп-лінії немає — значить зупиняються перед самим знаком, а не біля краю перехрещуваної дороги.","ru":"Стоп-линии нет — значит останавливаются перед самим знаком, а не у края пересекаемой дороги."}}],"img":{"sign":"2.2"},"c":1,"e":{"uk":"Знак {s:2.2} вимагає обов'язкової зупинки перед стоп-лінією {m:1.12}, а якщо її немає — перед знаком, навіть коли дорога вільна. Після цього треба пропустити тих, хто їде перехрещуваною дорогою.","ru":"Знак {s:2.2} требует обязательной остановки перед стоп-линией {m:1.12}, а если её нет — перед знаком, даже когда дорога свободна. После этого нужно пропустить тех, кто едет по пересекаемой дороге."},"ref":["33.2"],"id":"q26639c1e0"},{"t":"s33","q":{"uk":"На якій відстані до небезпечної ділянки встановлюють попереджувальні знаки поза населеним пунктом?","ru":"На каком расстоянии до опасного участка устанавливают предупреждающие знаки вне населённого пункта?"},"a":[{"uk":"50–100 м","ru":"50–100 м","w":{"uk":"50–100 м — відстань у населених пунктах. Поза ними — 150–300 м.","ru":"50–100 м — расстояние в населённых пунктах. Вне их — 150–300 м."}},{"uk":"150–300 м","ru":"150–300 м"},{"uk":"300–500 м","ru":"300–500 м","w":{"uk":"Такої норми немає: поза населеним пунктом — 150–300 м.","ru":"Такой нормы нет: вне населённого пункта — 150–300 м."}}],"c":1,"e":{"uk":"Попереджувальні знаки ставлять поза населеними пунктами за 150–300 м, у населених пунктах — за 50–100 м до небезпечної ділянки. Інша відстань позначається табличкою {s:7.1.1}.","ru":"Предупреждающие знаки ставят вне населённых пунктов за 150–300 м, в населённых пунктах — за 50–100 м до опасного участка. Иное расстояние обозначается табличкой {s:7.1.1}."},"ref":["33.1"],"id":"qa0486a5e2"},{"t":"s33","q":{"uk":"Що означає знак 5.49 «Початок населеного пункту» на білому фоні?","ru":"Что означает знак 5.49 «Начало населённого пункта» на белом фоне?"},"a":[{"uk":"З цього місця діють правила руху в населених пунктах (зокрема обмеження 50 км/год)","ru":"С этого места действуют правила движения в населённых пунктах (в частности ограничение 50 км/ч)"},{"uk":"Лише інформує про назву, правила не змінюються","ru":"Только информирует о названии, правила не меняются","w":{"uk":"Лише назву показує синій знак 5.51. Білий 5.49 вмикає правила для населених пунктів.","ru":"Только название показывает синий знак 5.51. Белый 5.49 включает правила для населённых пунктов."}}],"img":{"sign":"5.49"},"c":0,"e":{"uk":"Знак {s:5.49} (білий) вмикає правила для населених пунктів: швидкість до 50 км/год, звуковий сигнал заборонено тощо. Знак {s:5.51} (синій) лише інформує про назву: правила для населених пунктів на цій дорозі не діють.","ru":"Знак {s:5.49} (белый) включает правила для населённых пунктов: скорость до 50 км/ч, звуковой сигнал запрещён и т. п. Знак {s:5.51} (синий) только информирует о названии: правила для населённых пунктов на этой дороге не действуют."},"ref":["33.5","12.4"],"id":"q303588ea2"},{"t":"s33","q":{"uk":"Що дозволяє і що забороняє знак 5.29 «Місце для розвороту»?","ru":"Что разрешает и что запрещает знак 5.29 «Место для разворота»?"},"a":[{"uk":"Дозволяє розворот; поворот ліворуч заборонено","ru":"Разрешает разворот; поворот налево запрещён"},{"uk":"Дозволяє розворот і поворот ліворуч","ru":"Разрешает разворот и поворот налево","w":{"uk":"Знак 5.29 якраз забороняє поворот ліворуч, дозволяючи лише розворот.","ru":"Знак 5.29 как раз запрещает поворот налево, разрешая только разворот."}},{"uk":"Дозволяє лише стоянку","ru":"Разрешает только стоянку","w":{"uk":"Знак 5.29 позначає місце для розвороту, а не стоянку.","ru":"Знак 5.29 обозначает место для разворота, а не стоянку."}}],"img":{"sign":"5.29"},"c":0,"e":{"uk":"Знаки {s:5.29} і {s:5.30} позначають місце (зону) для розвороту. Поворот ліворуч у цьому місці заборонено.","ru":"Знаки {s:5.29} и {s:5.30} обозначают место (зону) для разворота. Поворот налево в этом месте запрещён."},"ref":["33.5"],"id":"q420301f17"},{"t":"s33","q":{"uk":"Встановлено знаки 3.36 і 3.37 одночасно. Коли треба переставити автомобіль на інший бік вулиці?","ru":"Установлены знаки 3.36 и 3.37 одновременно. Когда нужно переставить автомобиль на другую сторону улицы?"},"a":[{"uk":"З 7 до 9 год ранку","ru":"С 7 до 9 часов утра","w":{"uk":"Ранковий час Правила не встановлюють: перестановка — з 19 до 24 год.","ru":"Утреннее время Правила не устанавливают: перестановка — с 19 до 24 ч."}},{"uk":"З 19 до 24 год","ru":"С 19 до 24 часов"},{"uk":"Опівночі","ru":"В полночь","w":{"uk":"Не точно опівночі: переставити авто треба в проміжку з 19 до 24 год.","ru":"Не ровно в полночь: переставить авто нужно в промежутке с 19 до 24 ч."}}],"img":{"signs":["3.36","3.37"]},"c":1,"e":{"uk":"За одночасного застосування знаків {s:3.36} і {s:3.37} час перестановки автомобілів з одного боку на інший — з 19 до 24 год.","ru":"При одновременном применении знаков {s:3.36} и {s:3.37} время перестановки автомобилей с одной стороны на другую — с 19 до 24 ч."},"ref":["33.3"],"id":"q8e3ad9c25"},{"t":"s33","q":{"uk":"Дію яких знаків скасовує знак 3.42 «Кінець усіх заборон і обмежень»?","ru":"Действие каких знаков отменяет знак 3.42 «Конец всех запрещений и ограничений»?"},"a":[{"uk":"Одночасно кількох заборонних знаків: обгону, швидкості, звукового сигналу, зупинки, стоянки тощо","ru":"Одновременно нескольких запрещающих знаков: обгона, скорости, звукового сигнала, остановки, стоянки и т. п."},{"uk":"Усіх знаків, включно з пріоритету","ru":"Всех знаков, включая приоритета","w":{"uk":"Знаки пріоритету 3.42 не скасовує — лише заборонні знаки з переліку.","ru":"Знаки приоритета 3.42 не отменяет — только запрещающие знаки из перечня."}},{"uk":"Лише обмеження швидкості","ru":"Только ограничения скорости","w":{"uk":"Не лише швидкість: 3.42 скасовує одночасно кілька заборон (обгін, сигнал, зупинку, стоянку тощо).","ru":"Не только скорость: 3.42 отменяет одновременно несколько запретов (обгон, сигнал, остановку, стоянку и т. п.)."}}],"img":{"sign":"3.42"},"c":0,"e":{"uk":"{s:3.42} одночасно скасовує дію знаків {s:3.20}, {s:3.25}, {s:3.27}, {s:3.29}, {s:3.31}, {s:3.33}–{s:3.38}, {s:3.44}, {s:3.45}.","ru":"{s:3.42} одновременно отменяет действие знаков {s:3.20}, {s:3.25}, {s:3.27}, {s:3.29}, {s:3.31}, {s:3.33}–{s:3.38}, {s:3.44}, {s:3.45}."},"ref":["33.3"],"id":"q5fe25c49d"},{"t":"s33","q":{"uk":"Знак 3.35 «Стоянку заборонено» встановлено праворуч. Чи можна стояти на лівому боці цієї вулиці (у дозволених місцях)?","ru":"Знак 3.35 «Стоянка запрещена» установлен справа. Можно ли стоять на левой стороне этой улицы (в разрешённых местах)?"},"a":[{"uk":"Так, знак діє лише на тому боці, де встановлений","ru":"Да, знак действует только на той стороне, где установлен"},{"uk":"Ні, знак діє на обидва боки","ru":"Нет, знак действует на обе стороны","w":{"uk":"Знаки зупинки і стоянки діють лише на тому боці дороги, де встановлені.","ru":"Знаки остановки и стоянки действуют только на той стороне дороги, где установлены."}}],"img":{"sign":"3.35"},"c":0,"e":{"uk":"Знаки {s:3.9}, {s:3.10}, {s:3.34}, {s:3.35}, {s:3.36}, {s:3.37} діють лише на тому боці дороги, на якому встановлені.","ru":"Знаки {s:3.9}, {s:3.10}, {s:3.34}, {s:3.35}, {s:3.36}, {s:3.37} действуют только на той стороне дороги, на которой установлены."},"ref":["33.3"],"id":"q8ce00d659"},{"t":"s33","q":{"uk":"Що означає табличка 7.8 під знаком «Головна дорога»?","ru":"Что означает табличка 7.8 под знаком «Главная дорога»?"},"a":[{"uk":"Показує напрямок головної дороги на перехресті","ru":"Показывает направление главной дороги на перекрёстке"},{"uk":"Показує, куди можна повертати","ru":"Показывает, куда можно поворачивать","w":{"uk":"Табличка 7.8 не дозволяє і не забороняє повороти — вона лише показує, куди йде головна дорога.","ru":"Табличка 7.8 не разрешает и не запрещает повороты — она лишь показывает, куда идёт главная дорога."}},{"uk":"Попереджає про круговий рух","ru":"Предупреждает о круговом движении","w":{"uk":"Про кільце попереджає знак 1.19. Табличка 7.8 показує напрямок головної дороги.","ru":"О кольце предупреждает знак 1.19. Табличка 7.8 показывает направление главной дороги."}}],"img":{"signs":["2.3","7.8"]},"c":0,"e":{"uk":"Табличка {s:7.8} «Напрямок головної дороги» застосовується зі знаками {s:2.1}, {s:2.2}, {s:2.3} і показує, куди повертає головна дорога.","ru":"Табличка {s:7.8} «Направление главной дороги» применяется со знаками {s:2.1}, {s:2.2}, {s:2.3} и показывает, куда поворачивает главная дорога."},"ref":["33.7","16.14"],"id":"qde4dcadd3"},{"t":"s34","q":{"uk":"Чи можна перетинати лінію розмітки 1.1?","ru":"Можно ли пересекать линию разметки 1.1?"},"a":[{"uk":"Так, для обгону будь-якого транспортного засобу","ru":"Да, для обгона любого транспортного средства","w":{"uk":"Обганяти можна лише поодинокі ТЗ, що їдуть повільніше 30 км/год. Обгін будь-якого — порушення.","ru":"Обгонять можно только одиночные ТС, едущие медленнее 30 км/ч. Обгон любого — нарушение."}},{"uk":"Ні, крім об'їзду нерухомої перешкоди та обгону поодиноких транспортних засобів, що їдуть повільніше 30 км/год","ru":"Нет, кроме объезда неподвижного препятствия и обгона одиночных транспортных средств, едущих медленнее 30 км/ч"},{"uk":"Так, якщо зустрічна смуга вільна","ru":"Да, если встречная полоса свободна","w":{"uk":"Вільна зустрічна не дає права перетинати суцільну 1.1.","ru":"Свободная встречная не даёт права пересекать сплошную 1.1."}}],"img":{"mark":"1.1"},"c":1,"e":{"uk":"Лінії {m:1.1} і {m:1.3} перетинати заборонено. Як виняток, {m:1.1} можна перетнути, щоб безпечно об'їхати нерухому перешкоду або обігнати поодинокий транспортний засіб, що рухається зі швидкістю менше 30 км/год.","ru":"Линии {m:1.1} и {m:1.3} пересекать запрещено. Как исключение, {m:1.1} можно пересечь, чтобы безопасно объехать неподвижное препятствие или обогнать одиночное транспортное средство, движущееся со скоростью менее 30 км/ч."},"ref":["34.1"],"id":"q11053a2db"},{"t":"s34","q":{"uk":"З якого боку дозволено перетинати розмітку 1.11?","ru":"С какой стороны разрешено пересекать разметку 1.11?"},"a":[{"uk":"З боку переривчастої лінії; з боку суцільної — лише для завершення обгону чи об'їзду","ru":"Со стороны прерывистой линии; со стороны сплошной — только для завершения обгона или объезда"},{"uk":"З будь-якого боку","ru":"С любой стороны","w":{"uk":"Ні: з боку суцільної лінії 1.11 перетинати не можна (крім повернення після обгону чи об'їзду).","ru":"Нет: со стороны сплошной линии 1.11 пересекать нельзя (кроме возвращения после обгона или объезда)."}},{"uk":"З боку суцільної лінії","ru":"Со стороны сплошной линии","w":{"uk":"Навпаки: з боку суцільної перетинати заборонено, з боку переривчастої — можна.","ru":"Наоборот: со стороны сплошной пересекать запрещено, со стороны прерывистой — можно."}}],"img":{"mark":"1.11"},"c":0,"e":{"uk":"Лінію {m:1.11} дозволено перетинати з боку переривчастої частини, а з боку суцільної — лише повертаючись на свою смугу після обгону чи об'їзду.","ru":"Линию {m:1.11} разрешено пересекать со стороны прерывистой части, а со стороны сплошной — только возвращаясь на свою полосу после обгона или объезда."},"ref":["34.1"],"id":"qa577df58b"},{"t":"s34","q":{"uk":"Що забороняє жовта суцільна лінія біля краю проїзної частини (розмітка 1.4)?","ru":"Что запрещает жёлтая сплошная линия у края проезжей части (разметка 1.4)?"},"a":[{"uk":"Лише стоянку","ru":"Только стоянку","w":{"uk":"Лише стоянку забороняє жовта переривчаста 1.10.1. Жовта суцільна 1.4 забороняє ще й зупинку.","ru":"Только стоянку запрещает жёлтая прерывистая 1.10.1. Жёлтая сплошная 1.4 запрещает ещё и остановку."}},{"uk":"Зупинку (і стоянку) з того боку, де вона нанесена","ru":"Остановку (и стоянку) с той стороны, где она нанесена"},{"uk":"Рух вантажівок","ru":"Движение грузовиков","w":{"uk":"Розмітка 1.4 стосується зупинки, а не видів транспорту.","ru":"Разметка 1.4 касается остановки, а не видов транспорта."}}],"img":{"mark":"1.4"},"c":1,"e":{"uk":"Розмітка {m:1.4} (жовта суцільна) забороняє зупинку, а {m:1.10.1} (жовта переривчаста) — стоянку з того боку, де вона нанесена.","ru":"Разметка {m:1.4} (жёлтая сплошная) запрещает остановку, а {m:1.10.1} (жёлтая прерывистая) — стоянку с той стороны, где она нанесена."},"ref":["34.1"],"id":"q7d62051ef"},{"t":"s34","q":{"uk":"Чи можна перетинати лінію 1.5?","ru":"Можно ли пересекать линию 1.5?"},"a":[{"uk":"Так, з будь-якого боку","ru":"Да, с любой стороны"},{"uk":"Ні","ru":"Нет","w":{"uk":"Лінія 1.5 переривчаста: її можна перетинати з будь-якого боку.","ru":"Линия 1.5 прерывистая: её можно пересекать с любой стороны."}},{"uk":"Лише для повороту ліворуч","ru":"Только для поворота налево","w":{"uk":"Обмеження «лише для повороту» немає: 1.5 можна перетинати для будь-якого маневру.","ru":"Ограничения «только для поворота» нет: 1.5 можно пересекать для любого манёвра."}}],"img":{"mark":"1.5"},"c":0,"e":{"uk":"Лінії {m:1.5}, {m:1.6}, {m:1.7}, {m:1.8} дозволено перетинати з будь-якого боку. Лінія {m:1.6} попереджає про наближення до суцільної — готуйтеся завершити маневр.","ru":"Линии {m:1.5}, {m:1.6}, {m:1.7}, {m:1.8} разрешено пересекать с любой стороны. Линия {m:1.6} предупреждает о приближении к сплошной — готовьтесь завершить манёвр."},"ref":["34.1"],"id":"q02b005c72"},{"t":"s34","q":{"uk":"Коли можна перетнути широку суцільну лінію 1.2, що позначає край проїзної частини?","ru":"Когда можно пересечь широкую сплошную линию 1.2, обозначающую край проезжей части?"},"a":[{"uk":"Для вимушеної зупинки на узбіччі, а також в інших випадках, якщо це не заборонено знаками","ru":"Для вынужденной остановки на обочине, а также в других случаях, если это не запрещено знаками"},{"uk":"Ніколи","ru":"Никогда","w":{"uk":"Крайову лінію 1.2 перетинати можна, якщо знаки не забороняють, — наприклад, для вимушеної зупинки.","ru":"Краевую линию 1.2 пересекать можно, если знаки не запрещают, — например, для вынужденной остановки."}},{"uk":"Лише для обгону","ru":"Только для обгона","w":{"uk":"Обгін через крайову лінію (узбіччям) не дозволяється. Перетинати 1.2 можна, зокрема, для зупинки.","ru":"Обгон через краевую линию (по обочине) не разрешается. Пересекать 1.2 можно, в частности, для остановки."}}],"img":{"mark":"1.2"},"c":0,"e":{"uk":"Лінію {m:1.2}, якою позначено край проїзної частини, перетинати дозволено, якщо це не заборонено знаками, зокрема для вимушеної зупинки на узбіччі.","ru":"Линию {m:1.2}, которой обозначен край проезжей части, пересекать разрешено, если это не запрещено знаками, в частности для вынужденной остановки на обочине."},"ref":["34.1"],"id":"q505a0bc27"},{"t":"s34","q":{"uk":"Що означає жовта сітка на перехресті (розмітка 1.10.3)?","ru":"Что означает жёлтая сетка на перекрёстке (разметка 1.10.3)?"},"a":[{"uk":"Стоянку таксі","ru":"Стоянку такси","w":{"uk":"Стоянку таксі позначає розмітка 1.17.3 з написом TAXI.","ru":"Стоянку такси обозначает разметка 1.17.3 с надписью TAXI."}},{"uk":"Заборону в'їжджати на перехрестя, якщо утворився затор","ru":"Запрет въезжать на перекрёсток, если образовался затор"},{"uk":"Зупинку маршрутного транспорту","ru":"Остановку маршрутного транспорта","w":{"uk":"Зупинку маршрутного транспорту позначає жовтий зигзаг 1.17.1.","ru":"Остановку маршрутного транспорта обозначает жёлтый зигзаг 1.17.1."}}],"img":{"mark":"1.10.3"},"c":1,"e":{"uk":"Коробчаста жовта розмітка {m:1.10.3} попереджає: не в'їжджайте на перехрестя, якщо через затор доведеться на ньому зупинитися.","ru":"Коробчатая жёлтая разметка {m:1.10.3} предупреждает: не въезжайте на перекрёсток, если из-за затора придётся на нём остановиться."},"ref":["34.1","16.4"],"id":"q355d8b7a5"},{"t":"safe","q":{"uk":"Як зміниться гальмівний шлях, якщо швидкість збільшити вдвічі?","ru":"Как изменится тормозной путь, если скорость увеличить вдвое?"},"a":[{"uk":"Збільшиться вдвічі","ru":"Увеличится вдвое","w":{"uk":"Ні: гальмівний шлях росте пропорційно квадрату швидкості, тобто приблизно вчетверо.","ru":"Нет: тормозной путь растёт пропорционально квадрату скорости, то есть примерно вчетверо."}},{"uk":"Збільшиться приблизно вчетверо","ru":"Увеличится примерно вчетверо"},{"uk":"Не зміниться","ru":"Не изменится","w":{"uk":"Швидкість дуже впливає на гальмівний шлях: удвічі швидше — приблизно вчетверо довше.","ru":"Скорость сильно влияет на тормозной путь: вдвое быстрее — примерно вчетверо длиннее."}}],"c":1,"e":{"uk":"Гальмівний шлях пропорційний квадрату швидкості: удвічі вища швидкість — приблизно вчетверо довший гальмівний шлях.","ru":"Тормозной путь пропорционален квадрату скорости: вдвое большая скорость — примерно вчетверо длиннее тормозной путь."},"id":"qc4942c42f"},{"t":"safe","q":{"uk":"Як діяти, якщо задні колеса автомобіля занесло вправо?","ru":"Как действовать, если задние колёса автомобиля занесло вправо?"},"a":[{"uk":"Плавно повернути кермо вправо (у бік заносу), не гальмуючи різко","ru":"Плавно повернуть руль вправо (в сторону заноса), не тормозя резко"},{"uk":"Різко повернути кермо вліво","ru":"Резко повернуть руль влево","w":{"uk":"Різкий поворот кермом у протилежний бік посилить занос або розверне автомобіль.","ru":"Резкий поворот руля в противоположную сторону усилит занос или развернёт автомобиль."}},{"uk":"Різко натиснути на гальмо","ru":"Резко нажать на тормоз","w":{"uk":"Різке гальмування блокує колеса і посилює занос.","ru":"Резкое торможение блокирует колёса и усиливает занос."}}],"c":0,"e":{"uk":"Під час заносу кермо повертають у бік заносу задньої осі, плавно зменшують подачу палива і не гальмують різко — так шини відновлюють зчеплення.","ru":"При заносе руль поворачивают в сторону заноса задней оси, плавно уменьшают подачу топлива и не тормозят резко — так шины восстанавливают сцепление."},"id":"qd573dcd1e"},{"t":"safe","q":{"uk":"Як знизити ризик аквапланування на мокрій дорозі?","ru":"Как снизить риск аквапланирования на мокрой дороге?"},"a":[{"uk":"Підвищити тиск у шинах понад норму","ru":"Повысить давление в шинах сверх нормы","w":{"uk":"Підвищений тиск зменшує пляму контакту шини й погіршує зчеплення.","ru":"Повышенное давление уменьшает пятно контакта шины и ухудшает сцепление."}},{"uk":"Знизити швидкість і не їхати на зношених шинах","ru":"Снизить скорость и не ездить на изношенных шинах"},{"uk":"Їхати з увімкненою аварійною сигналізацією","ru":"Ехать с включённой аварийной сигнализацией","w":{"uk":"Аварійка не впливає на зчеплення шин з дорогою.","ru":"Аварийка не влияет на сцепление шин с дорогой."}}],"c":1,"e":{"uk":"Аквапланування виникає, коли шина не встигає витіснити воду. Ризик зростає зі швидкістю та зношенням протектора. Якщо автомобіль «поплив», плавно скиньте газ і тримайте кермо прямо, без різкого гальмування.","ru":"Аквапланирование возникает, когда шина не успевает вытеснить воду. Риск растёт со скоростью и износом протектора. Если автомобиль «поплыл», плавно сбросьте газ и держите руль прямо, без резкого торможения."},"id":"qf60ebf42a"},{"t":"safe","q":{"uk":"Як правильно екстрено гальмувати на автомобілі з ABS?","ru":"Как правильно экстренно тормозить на автомобиле с ABS?"},"a":[{"uk":"Сильно натиснути педаль гальма і тримати її, керуючи кермом за потреби","ru":"Сильно нажать педаль тормоза и держать её, при необходимости управляя рулём"},{"uk":"Переривчасто натискати педаль","ru":"Прерывисто нажимать педаль","w":{"uk":"Переривчасте натискання потрібне на машинах без ABS. З ABS система робить це сама — педаль тримають натиснутою.","ru":"Прерывистое нажатие нужно на машинах без ABS. С ABS система делает это сама — педаль держат нажатой."}},{"uk":"Гальмувати лише стоянковим гальмом","ru":"Тормозить только стояночным тормозом","w":{"uk":"Стоянкове гальмо гальмує лише задні колеса і може спричинити занос.","ru":"Стояночный тормоз тормозит только задние колёса и может вызвать занос."}}],"c":0,"e":{"uk":"ABS сама запобігає блокуванню коліс. Водієві треба сильно натиснути педаль і не відпускати; автомобіль при цьому залишається керованим. Вібрація педалі — нормальна робота системи.","ru":"ABS сама предотвращает блокировку колёс. Водителю нужно сильно нажать педаль и не отпускать; автомобиль при этом остаётся управляемым. Вибрация педали — нормальная работа системы."},"id":"qa96d6359b"},{"t":"safe","q":{"uk":"Водій відчуває сильну втому за кермом. Що робити?","ru":"Водитель чувствует сильную усталость за рулём. Что делать?"},"a":[{"uk":"Відкрити вікно і їхати далі","ru":"Открыть окно и ехать дальше","w":{"uk":"Свіже повітря допомагає ненадовго, втома нікуди не дінеться. Треба зупинитися й відпочити.","ru":"Свежий воздух помогает ненадолго, усталость никуда не денется. Нужно остановиться и отдохнуть."}},{"uk":"Збільшити гучність музики","ru":"Увеличить громкость музыки","w":{"uk":"Гучна музика не знімає втоми і ще більше відволікає.","ru":"Громкая музыка не снимает усталости и ещё больше отвлекает."}},{"uk":"Зупинитися в безпечному місці й відпочити","ru":"Остановиться в безопасном месте и отдохнуть"}],"c":2,"e":{"uk":"Керувати в стані стомлення заборонено. Кава і відчинене вікно діють недовго — єдиний надійний спосіб відновитися — зупинитися й відпочити (за потреби поспати).","ru":"Управлять в состоянии утомления запрещено. Кофе и открытое окно действуют недолго — единственный надёжный способ восстановиться — остановиться и отдохнуть (при необходимости поспать)."},"ref":["2.9"],"id":"q4505cf03a"},{"t":"safe","q":{"uk":"Як зміниться безпечна дистанція на мокрій або слизькій дорозі?","ru":"Как изменится безопасная дистанция на мокрой или скользкой дороге?"},"a":[{"uk":"Її треба збільшити","ru":"Её нужно увеличить"},{"uk":"Вона не залежить від покриття","ru":"Она не зависит от покрытия","w":{"uk":"Залежить: на мокрому покритті гальмівний шлях довший, тож дистанцію збільшують.","ru":"Зависит: на мокром покрытии тормозной путь длиннее, поэтому дистанцию увеличивают."}},{"uk":"Її можна зменшити, бо всі їдуть повільніше","ru":"Её можно уменьшить, так как все едут медленнее","w":{"uk":"Навіть на меншій швидкості на слизькій дорозі гальмувати важче. Дистанцію треба збільшувати.","ru":"Даже на меньшей скорости на скользкой дороге тормозить труднее. Дистанцию нужно увеличивать."}}],"c":0,"e":{"uk":"На мокрій і слизькій дорозі зчеплення гірше, тож гальмівний шлях довшає. Безпечна дистанція має бути більшою. Зручний орієнтир на сухій дорозі — щонайменше 2 секунди до автомобіля попереду, на мокрій — удвічі більше.","ru":"На мокрой и скользкой дороге сцепление хуже, поэтому тормозной путь удлиняется. Безопасная дистанция должна быть больше. Удобный ориентир на сухой дороге — не менее 2 секунд до автомобиля впереди, на мокрой — вдвое больше."},"ref":["13.1"],"id":"q972bfc00f"},{"t":"safe","q":{"uk":"Як найкраще контролювати швидкість на тривалому слизькому спуску?","ru":"Как лучше всего контролировать скорость на долгом скользком спуске?"},"a":[{"uk":"Гальмувати двигуном на знижувальній передачі","ru":"Тормозить двигателем на пониженной передаче"},{"uk":"Їхати накатом на нейтральній передачі","ru":"Ехать накатом на нейтральной передаче","w":{"uk":"Накатом на нейтралі автомобіль розганяється, і гальма перегріваються. На гірських дорогах це заборонено.","ru":"Накатом на нейтрали автомобиль разгоняется, и тормоза перегреваются. На горных дорогах это запрещено."}},{"uk":"Постійно тримати натиснутою педаль гальма","ru":"Постоянно держать нажатой педаль тормоза","w":{"uk":"Постійне гальмування перегріває гальма, і вони можуть відмовити.","ru":"Постоянное торможение перегревает тормоза, и они могут отказать."}}],"c":0,"e":{"uk":"На спуску безпечніше гальмувати двигуном на нижчій передачі: колеса не блокуються, гальма не перегріваються. Рух накатом з вимкненою передачею на гірських дорогах заборонено.","ru":"На спуске безопаснее тормозить двигателем на пониженной передаче: колёса не блокируются, тормоза не перегреваются. Движение накатом с выключенной передачей на горных дорогах запрещено."},"ref":["28.3"],"id":"q0b178c928"},{"t":"safe","q":{"uk":"Що треба зробити перед перестроюванням, крім огляду в дзеркала?","ru":"Что нужно сделать перед перестроением, кроме взгляда в зеркала?"},"a":[{"uk":"Коротко глянути через плече, щоб перевірити «сліпу зону»","ru":"Коротко взглянуть через плечо, чтобы проверить «слепую зону»"},{"uk":"Нічого, дзеркал достатньо","ru":"Ничего, зеркал достаточно","w":{"uk":"Дзеркала не показують «сліпу зону». Без огляду через плече можна не помітити автомобіль поруч.","ru":"Зеркала не показывают «слепую зону». Без взгляда через плечо можно не заметить автомобиль рядом."}},{"uk":"Подати звуковий сигнал","ru":"Подать звуковой сигнал","w":{"uk":"Звуковий сигнал не перевіряє, чи вільна смуга, а в місті його використання заборонене.","ru":"Звуковой сигнал не проверяет, свободна ли полоса, а в городе его использование запрещено."}}],"c":0,"e":{"uk":"Дзеркала не показують усього простору поруч — у «сліпій зоні» може бути автомобіль чи мотоцикл. Перед маневром перевірте її поворотом голови і переконайтеся, що маневр безпечний.","ru":"Зеркала не показывают всё пространство рядом — в «слепой зоне» может быть автомобиль или мотоцикл. Перед манёвром проверьте её поворотом головы и убедитесь, что манёвр безопасен."},"ref":["10.1"],"id":"q083074640"},{"t":"med","q":{"uk":"Ви першим під'їхали до місця ДТП з постраждалими. Що зробити насамперед?","ru":"Вы первым подъехали к месту ДТП с пострадавшими. Что сделать в первую очередь?"},"a":[{"uk":"Переконатися у власній безпеці (аварійка, знак, жилет) і викликати допомогу (103 або 112)","ru":"Убедиться в собственной безопасности (аварийка, знак, жилет) и вызвать помощь (103 или 112)"},{"uk":"Одразу витягнути всіх постраждалих з автомобілів","ru":"Сразу вытащить всех пострадавших из автомобилей","w":{"uk":"Без потреби переміщувати постраждалих не можна: це може посилити травми. Спершу — безпека й виклик допомоги.","ru":"Без необходимости перемещать пострадавших нельзя: это может усилить травмы. Сначала — безопасность и вызов помощи."}},{"uk":"Дати постраждалим попити води","ru":"Дать пострадавшим попить воды","w":{"uk":"Пити постраждалим не дають: при травмах живота чи операції це небезпечно.","ru":"Пить пострадавшим не дают: при травмах живота или операции это опасно."}}],"c":0,"e":{"uk":"Спочатку оцініть безпеку для себе: зупиніться, увімкніть аварійку, виставте знак аварійної зупинки. Потім викличте екстрену допомогу (103 — швидка, 112 — єдиний номер) і надавайте домедичну допомогу.","ru":"Сначала оцените безопасность для себя: остановитесь, включите аварийку, выставьте знак аварийной остановки. Затем вызовите экстренную помощь (103 — скорая, 112 — единый номер) и оказывайте домедицинскую помощь."},"ref":["2.10","9.10"],"id":"qce737e4d4"},{"t":"med","q":{"uk":"Масивна кровотеча з рани на нозі (кров б'є струменем). Що робити?","ru":"Массивное кровотечение из раны на ноге (кровь бьёт струёй). Что делать?"},"a":[{"uk":"Промити рану водою","ru":"Промыть рану водой","w":{"uk":"Промивання не зупинить сильну кровотечу, а час втрачається. Потрібен турнікет.","ru":"Промывание не остановит сильное кровотечение, а время теряется. Нужен турникет."}},{"uk":"Накласти турнікет (джгут) вище рани, затягнути до зупинки кровотечі й записати час накладання","ru":"Наложить турникет (жгут) выше раны, затянуть до остановки кровотечения и записать время наложения"},{"uk":"Підняти ногу й чекати швидку","ru":"Поднять ногу и ждать скорую","w":{"uk":"Підняття ноги не зупинить артеріальну кровотечу. Людина може втратити багато крові до приїзду швидкої.","ru":"Поднятие ноги не остановит артериальное кровотечение. Человек может потерять много крови до приезда скорой."}}],"c":1,"e":{"uk":"Масивну кровотечу з кінцівки зупиняють турнікетом (джгутом) вище рани, затягнувши до зупинки кровотечі. Обов'язково фіксують час накладання. Якщо турнікета немає — сильно тиснуть на рану або тампонують її.","ru":"Массивное кровотечение из конечности останавливают турникетом (жгутом) выше раны, затянув до остановки кровотечения. Обязательно фиксируют время наложения. Если турникета нет — сильно давят на рану или тампонируют её."},"id":"q64978baa4"},{"t":"med","q":{"uk":"Постраждалий без свідомості, але дихає нормально. У якому положенні його залишити до прибуття швидкої?","ru":"Пострадавший без сознания, но дышит нормально. В каком положении его оставить до прибытия скорой?"},"a":[{"uk":"Сидячи","ru":"Сидя","w":{"uk":"Людина без свідомості в положенні сидячи може задихнутися: язик западає.","ru":"Человек без сознания в положении сидя может задохнуться: язык западает."}},{"uk":"У стабільному положенні на боці, постійно контролюючи дихання","ru":"В устойчивом положении на боку, постоянно контролируя дыхание"},{"uk":"На спині з піднятою головою","ru":"На спине с поднятой головой","w":{"uk":"На спині язик або блювотні маси можуть перекрити дихальні шляхи.","ru":"На спине язык или рвотные массы могут перекрыть дыхательные пути."}}],"c":1,"e":{"uk":"Стабільне положення на боці не дає язику запасти, а блювотним масам — потрапити в дихальні шляхи. Дихання перевіряють постійно. Якщо є підозра на травму хребта і людина дихає — без потреби її не перекладають.","ru":"Устойчивое положение на боку не даёт языку западать, а рвотным массам — попасть в дыхательные пути. Дыхание проверяют постоянно. Если есть подозрение на травму позвоночника и человек дышит — без необходимости его не перекладывают."},"id":"q5f2536621"},{"t":"med","q":{"uk":"Постраждалий не дихає. Яке співвідношення натискань на грудну клітку і вдихів під час серцево-легеневої реанімації дорослого?","ru":"Пострадавший не дышит. Какое соотношение нажатий на грудную клетку и вдохов при сердечно-лёгочной реанимации взрослого?"},"a":[{"uk":"15 : 2","ru":"15 : 2","w":{"uk":"15 : 2 — застаріле співвідношення. Для дорослих — 30 натискань і 2 вдихи.","ru":"15 : 2 — устаревшее соотношение. Для взрослых — 30 нажатий и 2 вдоха."}},{"uk":"30 : 2","ru":"30 : 2"},{"uk":"5 : 1","ru":"5 : 1","w":{"uk":"Такого співвідношення в сучасних рекомендаціях немає. Для дорослих — 30 : 2.","ru":"Такого соотношения в современных рекомендациях нет. Для взрослых — 30 : 2."}}],"c":1,"e":{"uk":"Дорослим роблять 30 натискань на центр грудної клітки (глибина 5–6 см, темп 100–120 за хвилину) і 2 вдихи. Якщо вдихи робити не вмієте — лише безперервні натискання до прибуття медиків.","ru":"Взрослым делают 30 нажатий на центр грудной клетки (глубина 5–6 см, темп 100–120 в минуту) и 2 вдоха. Если делать вдохи не умеете — только непрерывные нажатия до прибытия медиков."},"id":"q0d6dbf2e5"},{"t":"med","q":{"uk":"Чи можна переносити постраждалого з підозрою на травму хребта?","ru":"Можно ли переносить пострадавшего с подозрением на травму позвоночника?"},"a":[{"uk":"Лише якщо йому загрожує безпосередня небезпека (пожежа, вибух)","ru":"Только если ему угрожает непосредственная опасность (пожар, взрыв)"},{"uk":"Так, щоб посадити його зручніше","ru":"Да, чтобы усадить его удобнее","w":{"uk":"Зайві рухи можуть пошкодити спинний мозок. Переміщують лише за загрози життю.","ru":"Лишние движения могут повредить спинной мозг. Перемещают только при угрозе жизни."}},{"uk":"Так, щоб відвезти до лікарні на своєму автомобілі","ru":"Да, чтобы отвезти в больницу на своём автомобиле","w":{"uk":"Самостійне перевезення без фіксації хребта небезпечне. Викликайте швидку.","ru":"Самостоятельная перевозка без фиксации позвоночника опасна. Вызывайте скорую."}}],"c":0,"e":{"uk":"Зайві рухи можуть пошкодити спинний мозок. Постраждалого з підозрою на травму хребта переміщують лише за загрози життю (вогонь, вибух), намагаючись фіксувати голову і шию.","ru":"Лишние движения могут повредить спинной мозг. Пострадавшего с подозрением на травму позвоночника перемещают только при угрозе жизни (огонь, взрыв), стараясь фиксировать голову и шею."},"id":"q582b3ed7e"},{"t":"med","q":{"uk":"Як надати допомогу при термічному опіку руки?","ru":"Как оказать помощь при термическом ожоге руки?"},"a":[{"uk":"Змастити олією або жиром","ru":"Смазать маслом или жиром","w":{"uk":"Олія і жир утримують тепло та підвищують ризик інфекції. Опік охолоджують водою.","ru":"Масло и жир удерживают тепло и повышают риск инфекции. Ожог охлаждают водой."}},{"uk":"Проколоти пухирі","ru":"Проколоть волдыри","w":{"uk":"Пухирі захищають рану від інфекції. Проколювати їх не можна.","ru":"Волдыри защищают рану от инфекции. Прокалывать их нельзя."}},{"uk":"Охолоджувати проточною прохолодною водою 10–20 хвилин і накрити чистою пов'язкою","ru":"Охлаждать проточной прохладной водой 10–20 минут и накрыть чистой повязкой"}],"c":2,"e":{"uk":"Опік охолоджують прохолодною проточною водою щонайменше 10–20 хвилин, потім накривають чистою сухою пов'язкою. Олію, жир чи лід не використовують, пухирі не проколюють.","ru":"Ожог охлаждают прохладной проточной водой не менее 10–20 минут, затем накрывают чистой сухой повязкой. Масло, жир или лёд не используют, волдыри не прокалывают."},"id":"q11cccf55e"},{"t":"med","q":{"uk":"Що робити при підозрі на перелом кінцівки?","ru":"Что делать при подозрении на перелом конечности?"},"a":[{"uk":"Знерухомити кінцівку в тому положенні, в якому вона є, і викликати швидку","ru":"Обездвижить конечность в том положении, в котором она находится, и вызвать скорую"},{"uk":"Спробувати вправити кістку","ru":"Попытаться вправить кость","w":{"uk":"Вправляти кістку може лише лікар. Інакше можна пошкодити судини й нерви.","ru":"Вправлять кость может только врач. Иначе можно повредить сосуды и нервы."}},{"uk":"Попросити постраждалого поворушити кінцівкою","ru":"Попросить пострадавшего пошевелить конечностью","w":{"uk":"Рухи зламаною кінцівкою посилюють біль і травму. Її треба знерухомити.","ru":"Движения сломанной конечностью усиливают боль и травму. Её нужно обездвижить."}}],"c":0,"e":{"uk":"Кінцівку з підозрою на перелом не вправляють, а знерухомлюють (шиною чи підручними засобами), захоплюючи сусідні суглоби. Якщо є кровотеча — спочатку її зупиняють.","ru":"Конечность с подозрением на перелом не вправляют, а обездвиживают (шиной или подручными средствами), захватывая соседние суставы. Если есть кровотечение — сначала его останавливают."},"id":"q1520475ca"},{"t":"med","q":{"uk":"Мотоцикліст лежить без свідомості в шоломі, але дихає. Чи знімати шолом?","ru":"Мотоциклист лежит без сознания в шлеме, но дышит. Снимать ли шлем?"},"a":[{"uk":"Так, обов'язково і негайно","ru":"Да, обязательно и немедленно","w":{"uk":"Якщо людина дихає, знімати шолом не потрібно: можна пошкодити шийний відділ хребта.","ru":"Если человек дышит, снимать шлем не нужно: можно повредить шейный отдел позвоночника."}},{"uk":"Ні, якщо він дихає; шолом знімають лише якщо треба відновити дихання або прохідність дихальних шляхів","ru":"Нет, если он дышит; шлем снимают только если нужно восстановить дыхание или проходимость дыхательных путей"}],"c":1,"e":{"uk":"Знімання шолома може травмувати шийний відділ хребта. Якщо людина дихає — шолом не чіпають до приїзду медиків. Знімають обережно, удвох, лише коли треба відновити дихання або провести реанімацію.","ru":"Снятие шлема может травмировать шейный отдел позвоночника. Если человек дышит — шлем не трогают до приезда медиков. Снимают осторожно, вдвоём, только когда нужно восстановить дыхание или провести реанимацию."},"id":"q9796012cb"}]};
